window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s9-516","number":516,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿وسيرى الله عملكم ورسوله﴾، فأعاد باب العمل بعد الأعذار؟","answer":"بعد إبطال الأقوال أحال الحكم إلى العمل المستقبل؛ فصدق التوبة لا تثبته الأعذار، بل ما سيراه الله ورسوله من أفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص108، تحت «بلاغة الكناية في جملة وسيرى الله»","url":""}]},{"id":"s9-517","number":517,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"لماذا وصف الله بـ﴿عالم الغيب والشهادة﴾ في خاتمة الآية؟","answer":"وصفه بـ﴿عالم الغيب والشهادة﴾ لأنه يعلم أعذارهم الباطنة وأعمالهم الظاهرة، فلا تخفى عليه حقيقة التوبة ولا النفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص112، تحت «سر التعبير بلفظي عالم الغيب والشهادة»","url":""}]},{"id":"s9-518","number":518,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿فينبئكم بما كنتم تعملون﴾ مع أنهم يعرفون أعمالهم؟","answer":"الإنباء هنا إظهار حقيقة الأعمال والحكم عليها والجزاء بها يوم القيامة، لا مجرد إخبارهم بوقائع يعرفونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص113، تحت «بلاغة الكناية في فينبئكم»","url":""}]},{"id":"s9-519","number":519,"surah":9,"verses":[94,105],"references":[{"surah":9,"verses":[94,105]}],"verseLabel":"التوبة: 94؛ التوبة: 105","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الآية 94: ﴿وسيرى الله عملكم ورسوله ثم تردون﴾، وقوله في الآية 105: ﴿فسيرى الله عملكم ورسوله والمؤمنون وستردون﴾؟","answer":"في الآية94 حديث عن المنافقين وما يخفونه؛ فاقتصر على الله ورسوله، وعطفت الرؤية بالواو على كشف أخبارهم، وجاءت ثم للتراخي والإمهال قبل الرد للجزاء. وفي الآية105 الحديث عن العمل الظاهر، فذكر المؤمنون، ورتبت رؤيته بالفاء على الأمر بالعمل. وتفيد الواو مع السين في وستردون تقريب الجزاء ثوابًا أو عقابًا؛ فلا تختص العبارة بالوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص116، تحت «سر استعمال الواو في لفظ وسيرى»","url":""}]},{"id":"s9-520","number":520,"surah":9,"verses":[95],"references":[{"surah":9,"verses":[95]}],"verseLabel":"التوبة: 95","question":"لماذا سيحلفون بالله عند الرجوع: ﴿لتعرضوا عنهم﴾؟","answer":"يحلفون لتكون غاية المؤمنين مجرد ترك اللوم والمؤاخذة، لا التصديق والمحبة؛ فهم يريدون السلامة من تبعات تخلفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص126، تحت «دلالة اللام في قوله لتعرضوا»","url":""}]},{"id":"s9-521","number":521,"surah":9,"verses":[95],"references":[{"surah":9,"verses":[95]}],"verseLabel":"التوبة: 95","question":"لماذا جاء الأمر: ﴿فأعرضوا عنهم﴾ موافقًا لما طلبوه؟","answer":"أُمروا بالإعراض لا عفوًا ولا رضا، بل إعراض هجر واحتقار؛ فوافق اللفظ مطلوبهم وخالف مرادهم، إذ أرادوا سلامة وقبولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص128، تحت «الغرض من الأمر في الفعل فأعرضوا»","url":""}]},{"id":"s9-522","number":522,"surah":9,"verses":[95],"references":[{"surah":9,"verses":[95]}],"verseLabel":"التوبة: 95","question":"لماذا علل الإعراض بقوله: ﴿إنهم رجس﴾؟","answer":"الرجس الخبث المعنوي الناشئ من النفاق والكذب؛ فالبعد عنهم صيانة للمؤمنين لا استجابة تكريم لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص128، تحت «دلالة فصل جملة إنهم رجس»","url":""}]},{"id":"s9-523","number":523,"surah":9,"verses":[95],"references":[{"surah":9,"verses":[95]}],"verseLabel":"التوبة: 95","question":"ما دلالة التعبير بالجملة الاسمية في قوله تعالى: ﴿ومأواهم جهنم﴾؟","answer":"تفيد الجملة الاسمية ثبات هذا المصير واستقراره؛ فجهنم هي المأوى الذي ينتهون إليه ويلزمونه جزاء نفاقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص130، تحت «فائدة التعبير بالاسمية في ومأواهم جهنم»","url":""}]},{"id":"s9-758","number":758,"surah":9,"verses":[95],"references":[{"surah":9,"verses":[95]}],"verseLabel":"التوبة: 95","question":"ما سرّ التعبير بقوله تعالى: ﴿بما كانوا يكسبون﴾؟","answer":"نسب الجزاء إلى ما تعمدوا اكتسابه من الكذب والنفاق، فدلّ على أن العذاب ثمرة طريق اختاروه وداوموا عليه، لا عقوبة بلا سبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص131، تحت «سر التعبير بيكسبون»","url":""}]},{"id":"s9-524","number":524,"surah":9,"verses":[96],"references":[{"surah":9,"verses":[96]}],"verseLabel":"التوبة: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿يحلفون لكم لترضوا عنهم﴾ بعد قوله في الآية السابقة ﴿لتعرضوا عنهم﴾؟","answer":"في الأولى طلب ترك اللوم والمؤاخذة، وفي الثانية بيان طلب الرضا عنهم، وهو أزيد من مجرد الإعراض. ويعرض المصدر أوجهًا في تكرار الحلف تتعلق باختلاف غرضه أو المخاطبين به؛ فلا يلزم أن يكون حلفًا لاحقًا في الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص132، تحت «غرض تكرار الحلف في يحلفون بعد سيحلفون»","url":""}]},{"id":"s9-525","number":525,"surah":9,"verses":[96],"references":[{"surah":9,"verses":[96]}],"verseLabel":"التوبة: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن ترضوا عنهم فإن الله لا يرضى عن القوم الفاسقين﴾؟","answer":"رضا الناس لا يغير حكم الله؛ فإن رضي المؤمنون ظاهرًا بسبب الحلف، فإن الله لا يرضى عن قوم رسخ فسقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص134، تحت «دلالة الفاء ومعناها»","url":""}]},{"id":"s9-526","number":526,"surah":9,"verses":[96],"references":[{"surah":9,"verses":[96]}],"verseLabel":"التوبة: 96","question":"لماذا لم ينه المؤمنين مباشرة عن الرضا، بل بيّن أن الله لا يرضى؟","answer":"المقصود تحذير المؤمنين من الرضا عنهم؛ إذ إن رضا الناس لا ينفع مع سخط الله. فذكر أن الله لا يرضى عن الفاسقين يحمل المؤمنين على الامتناع عن الرضا الذي يناقض حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص135، تحت «بلاغة التعبير بالجملة الشرطية فإن ترضوا عنهم»","url":""}]},{"id":"s9-527","number":527,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿الأعراب أشد كفرًا ونفاقًا﴾، دون أن يقال: «كل الأعراب كفار»؟","answer":"ليس في الآية تعميم الحكم على جميع الأعراب؛ بل بيان أن بيئة البداوة فيمن كفر أو نافق تجعل كفره ونفاقه أشد لبعده عن العلم، وقد استثنت الآيات التالية مؤمنيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص146–147، 170، تحت «دلالة أل على الجنس في لفظ الأعراب»","url":""}]},{"id":"s9-528","number":528,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"لماذا جمع بين الكفر والنفاق في وصف الأعراب؟","answer":"جمعهما لاستيعاب الفريقين: من أظهر الكفر ومن ستره بالنفاق، أو لأن بعضهم جمع شدة الكفر الباطن وإظهار الإسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص149، تحت «دلالة الجمع بين الكفر والنفاق في قوله كفرًا ونفاقًا»","url":""}]},{"id":"s9-529","number":529,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"ما صلة قوله: ﴿وأجدر ألا يعلموا حدود ما أنزل الله﴾ بوصف الأعراب بالشدة في الكفر والنفاق؟","answer":"عطف صفة الجهل بحدود الشرع على شدة الكفر والنفاق، فجمع وصفين يرتبطان ببعدهم عن مجالس العلم وسماع الوحي. وأجدر بمعنى أحق وأخلق بهذا الجهل بحسب حالهم المذكورة، وليس حكمًا لازمًا لكل فرد من الأعراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص150، تحت «دلالة العطف في جملة وأجدر»","url":""}]},{"id":"s9-530","number":530,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿حدود ما أنزل الله على رسوله﴾؟","answer":"الحدود هي أحكام الله الفاصلة بين الحلال والحرام والطاعة والمعصية، وإضافتها إلى ما أنزل وربطها بالرسول ﷺ يثبت مصدرها وطريق تبليغها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص151، تحت «سر اختيار لفظ حدود»","url":""}]},{"id":"s9-531","number":531,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"لماذا ختم وصف الأعراب بـ﴿والله عليم حكيم﴾؟","answer":"هو عليم بخفايا النفوس وأحوال هؤلاء الأعراب، وحكيم في تدبير خلقه وجزائهم؛ فناسب الاسمان بيان صفاتهم وما يستحقونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص153، تحت «سر تذييل الآية بقوله والله عليم حكيم»","url":""}]},{"id":"s9-759","number":759,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"لماذا قدم ﴿عليم﴾ على ﴿حكيم﴾ في ختام وصف الأعراب؟","answer":"لأن الحكم المحكم يقوم على العلم، فقدم ما هو أساس الحكمة ومبدؤها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص154، تحت «نكتة التقديم عليم على حكيم»","url":""}]},{"id":"s9-760","number":760,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"ما سر التعبير بالجملة الاسمية في ﴿والله عليم حكيم﴾؟","answer":"تفيد الجملة الاسمية ثبوت العلم والحكمة لله ودوام اتصافه بهما، لا حدوثهما في وقت دون وقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص154، تحت «سر التعبير بالجملة الاسمية»","url":""}]},{"id":"s9-532","number":532,"surah":9,"verses":[98],"references":[{"surah":9,"verses":[98]}],"verseLabel":"التوبة: 98","question":"ما سرّ التعبير في قوله تعالى عن بعض الأعراب: ﴿يتخذ ما ينفق مغرمًا﴾؟","answer":"يعد النفقة غرامة وخسارة لازمة لا قربة؛ لأنه يدفعها كارهًا بلا إيمان بثوابها، فكشف اللفظ ميزانه المادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص156، تحت «نكتة التعبير بلفظ يتخذ»","url":""}]},{"id":"s9-533","number":533,"surah":9,"verses":[98],"references":[{"surah":9,"verses":[98]}],"verseLabel":"التوبة: 98","question":"ما دلالة المضارع في قوله عن الأعراب المنافقين: ﴿ما ينفق﴾؟","answer":"يفيد تجدد الإنفاق؛ فكلما وقعت منهم نفقة نظروا إليها على أنها غرامة وخسارة. وبذلك يصور استمرار هذا الموقف منهم مع تجدد النفقة، لا حكمهم على نفقة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص159، تحت «دلالة التعبير بالمضارع ينفق»","url":""}]},{"id":"s9-534","number":534,"surah":9,"verses":[98],"references":[{"surah":9,"verses":[98]}],"verseLabel":"التوبة: 98","question":"ما سرّ التعبير في قوله تعالى: ﴿ويتربص بكم الدوائر﴾ بصيغة الجمع؟","answer":"الدوائر جمع دائرة، وهي تقلبات الدهر ومصائبه؛ والجمع يدل على ترقبهم أنواع النكبات متتابعة بالمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص161، تحت «نكتة التعبير بالجمع الدوائر»","url":""}]},{"id":"s9-535","number":535,"surah":9,"verses":[98],"references":[{"surah":9,"verses":[98]}],"verseLabel":"التوبة: 98","question":"لماذا جاء الجزاء: ﴿عليهم دائرة السوء﴾ من جنس لفظهم؟","answer":"رد الدعاء عليهم من جنس لفظهم: ما تمنوه للمؤمنين يحيق بهم، و﴿دائرة السوء﴾ تخصهم بالدائرة القبيحة العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص162، تحت «سر المغايرة بالتعبير دائرة السوء مقابل الدوائر»","url":""}]},{"id":"s9-536","number":536,"surah":9,"verses":[98],"references":[{"surah":9,"verses":[98]}],"verseLabel":"التوبة: 98","question":"لماذا ختم بـ﴿والله سميع عليم﴾؟","answer":"﴿سميع﴾ لأقوالهم ودعائهم الخفي، و﴿عليم﴾ بما تضمره قلوبهم من تربص وكراهة؛ فلا يخفى نفاقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص165، تحت «نكتة التذييل بالاسمين الجليلين سميع عليم»","url":""}]},{"id":"s9-537","number":537,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا استدرك بصورة أخرى من الأعراب: ﴿ومن الأعراب من يؤمن بالله واليوم الآخر﴾؟","answer":"جاءت المقابلة لرفع التعميم: ليس الأعراب سواء، فمنهم مؤمن صادق يجعل نفقته قربة بعد ذكر من يجعلها مغرمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص170، تحت «دلالة أل في الأعراب»","url":""}]},{"id":"s9-538","number":538,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا تكرر تركيب ﴿يتخذ ما ينفق﴾ في الفريقين مع اختلاف النتيجة؟","answer":"اتحد العمل الظاهر وهو الإنفاق، واختلفت النية: الكافر يراه غرامة، والمؤمن يتخذه قربات؛ فدل التكرار على أن قيمة العمل بنيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص172، تحت «سر التعبير بقوله يتخذ دون يحتسب»","url":""}]},{"id":"s9-539","number":539,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"ما دلالة تسمية النفقات ﴿قربات﴾؟","answer":"سميت قربات لأنها أسباب تقرّب أصحابها إلى رضا الله وثوابه؛ فعبّر بالمسبَّب عن سببه، وفيه إشعار بصدق نيتهم في الإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص172، تحت «الغرض من التعبير بالمجاز المرسل القربات»","url":""}]},{"id":"s9-761","number":761,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"ما دلالة إضافة ﴿الصلوات﴾ إلى الرسول ﷺ؟","answer":"الإضافة تبين أن دعاء الرسول ﷺ لهم بالخير والبركة ثمرة من ثمرات صدقهم، فجمع لهم قبول الله ودعاء رسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص175، تحت «فائدة إضافة الصلوات للرسول الأكرم»","url":""}]},{"id":"s9-540","number":540,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا جاءت ﴿قربات﴾ بالجمع؟","answer":"لأن وجوه التقرب تتعدد بتعدد النفقات والطاعات والنيات الصالحة، فكل نفقة صادقة باب قرب مستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص172، تحت «سر التعبير بالجمع قربات دون قربة بالإفراد»","url":""}]},{"id":"s9-762","number":762,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا جاءت ﴿صلوات الرسول﴾ بالجمع؟","answer":"يشير الجمع إلى تكرر دعوات الرسول ﷺ لهم وتنوع ما تتضمنه من رحمة وبركة وخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص175، تحت «نكتة الجمع صلوات في قوله وصلوات الرسول»","url":""}]},{"id":"s9-541","number":541,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا أكد بقوله: ﴿ألا إنها قربة لهم﴾؟","answer":"افتتحت الجملة بألا التنبيهية وأكدت بإن وبالجملة الاسمية؛ تثبيتًا لصدق رجائهم في القرب من الله وبشارة بقبول نفقتهم. فليست القربة مجرد اعتقاد منهم، بل شهد الله لهم بتحققها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص175، تحت «الغرض من استئناف ألا إنها قربة لهم في السياق»","url":""}]},{"id":"s9-542","number":542,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿سيدخلهم الله في رحمته﴾، فصوّر الرحمة مكانًا يدخلونه؟","answer":"صورت الرحمة فضاء يحيط بهم ويدخلون فيه، للدلالة على شمولها وتمكنهم منها؛ والسين وعد بتحقق ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص177، تحت «دلالة دخول السين في سيدخلهم»","url":""}]},{"id":"s9-543","number":543,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا ختم بـ﴿إن الله غفور رحيم﴾؟","answer":"﴿غفور﴾ لما يقع منهم من تقصير، و﴿رحيم﴾ يقبل نفقتهم ويدخلهم في رحمته؛ فناسبت الخاتمة وعد المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص178، تحت «دلالة فصل جملة إن الله غفور رحيم عما قبلها»","url":""}]},{"id":"s9-544","number":544,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما سرّ تقديم ﴿السابقون الأولون﴾ قبل المهاجرين والأنصار؟","answer":"﴿السابقون﴾ وصف جامع، ثم بين أنهم الأوائل من المهاجرين والأنصار؛ وتقديم الوصف يشرف السبق نفسه ويجعله أساس المنزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص185، تحت «معنى أل في السابقون»","url":""}]},{"id":"s9-545","number":545,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿من المهاجرين والأنصار﴾، فقدم المهاجرين؟","answer":"قُدم المهاجرون لسبقهم إلى الإيمان وتحملهم مفارقة الديار والأموال، ثم الأنصار الذين آووا ونصروا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص187–188، تحت «دلالة تقديم المهاجرين على الأنصار»","url":""}]},{"id":"s9-546","number":546,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"لماذا قيد أتباعهم بقوله: ﴿بإحسان﴾؟","answer":"قيد الاتباع بالإحسان حتى لا تكون مجرد الدعوى أو الصحبة كافية؛ بل لا بد من اقتفاء منهج السابقين في صحة الاعتقاد والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص190، تحت «معنى الباء في بإحسان»","url":""}]},{"id":"s9-547","number":547,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿رضي الله عنهم ورضوا عنه﴾؟","answer":"رضاه عنهم يتضمن قبول صالح أعمالهم ومغفرة ذنوبهم وإدخالهم الجنة. ورضاهم عنه شكرهم له على نعمه وإيمانهم به وطاعتهم له، ورضاهم بما أعطاهم؛ فاجتمع الجزاء الكريم ورضا العبد وشكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص194، تحت «بلاغة المشاكلة بين رضا الله عنهم ورضاهم عنه»","url":""}]},{"id":"s9-548","number":548,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما سرّ تقديم رضا الله عنهم على رضاهم عنه؟","answer":"رضا الله أعلى مراتب الجزاء، فناسب تقديمه. كما أن رضاهم بما نالوه من النعمة والكرامة تابع لرضاه عنهم، فتقدم السبب على ما نشأ عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص193، تحت «نكتة تقديم رضاه عنهم قبل رضاهم عنه»","url":""}]},{"id":"s9-549","number":549,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"لماذا جمع بين الرضوان وإعداد الجنات؟","answer":"الرضوان نعيم معنوي وسبب القبول، والجنات نعيم حسي دائم؛ فجمع كرامة القرب ومتعة المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص194، تحت «بلاغة العطف في وأعد لهم جنات»","url":""}]},{"id":"s9-550","number":550,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما فائدة قوله تعالى: ﴿أبدًا﴾ بعد ﴿خالدين فيها﴾؟","answer":"يزيل ﴿أبدًا﴾ كل توهم لانتهاء الخلود أو انقطاع النعيم، فيؤكد امتداده الدائم الذي لا تحده غاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص199، تحت «فائدة الظرف أبدًا بعد التعبير بالخلود»","url":""}]},{"id":"s9-763","number":763,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"لماذا وُصف الفوز بأنه ﴿العظيم﴾؟","answer":"لأنه فوز يجمع رضا الله والنعيم الدائم والنجاة من العذاب، فلا يدانيه فوز دنيوي محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص201، تحت «فائدة وصف الفوز بالعظيم»","url":""}]},{"id":"s9-551","number":551,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"لماذا قدّم في التوبة: ﴿رضي الله عنهم ورضوا عنه﴾ على ذكر الجنات، بينما قدّم في المائدة الجنات ثم قال: ﴿رضي الله عنهم ورضوا عنه﴾؟","answer":"في التوبة كان المقام مقام الثناء على السابقين واتباعهم، فقدم الرضا المتعلق بأعمالهم ثم ثنى بالجزاء؛ وفي المائدة كان المقام مقام جزاء الصادقين يوم القيامة، فقدم الجنة ثم ختم برضا الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص171–172، تحت «التشابه بين آيتي سورة المائدة والتوبة وسر تقديم الرضا في إحداهما دون الأخرى»","url":""}]},{"id":"s9-552","number":552,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما سرّ التعبير في قوله تعالى في أكثر آيات الجنة: ﴿تجري من تحتها الأنهار﴾، وحذف ﴿من﴾ في التوبة فقال: ﴿تجري تحتها الأنهار﴾؟","answer":"الإثبات بـ﴿من تحتها﴾ يدل على ابتداء جريان الأنهار من تحت الجنات أو أشجارها، وحذف ﴿من﴾ في التوبة يكتفي بتصوير جريانها تحتها؛ والتنويع اللفظي مع بقاء أصل النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص197–198، تحت «بلاغة القراءات القرآنية المتواترة»","url":""}]},{"id":"s9-553","number":553,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿وممن حولكم من الأعراب منافقون ومن أهل المدينة﴾؟","answer":"قدم منافقي الأعراب المحيطين بالمدينة ثم عطف منافقي أهلها، فدل على إحاطة الخطر من خارج المدينة وداخلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص210، تحت «نكتة العطف في ومن أهل المدينة»","url":""}]},{"id":"s9-554","number":554,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿مردوا على النفاق﴾؟","answer":"﴿مردوا﴾ أي مرنوا وتمرنوا واستمروا على النفاق حتى صار لهم عادة ومهارة، فهو أبلغ من مجرد وقوعهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص213، تحت «عود الضمير في مردوا»","url":""}]},{"id":"s9-555","number":555,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"ما وجه قوله تعالى للنبي ﷺ: ﴿لا تعلمهم نحن نعلمهم﴾ مع فراسته ووحيه؟","answer":"المنفي علم أشخاص بأعيانهم ممن أخفى النفاق وأتقنه، لا مطلق فراسة النبي ﷺ أو ما أعلمه الله به؛ فعلم الغيب لله ويطلع رسوله على ما يشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص215، تحت «فائدة العدول من الفعلية إلى الاسمية»","url":""}]},{"id":"s9-556","number":556,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"لماذا انتقل من الغيبة إلى ضمير العظمة: ﴿نحن نعلمهم سنعذبهم﴾؟","answer":"ضمير العظمة يبرز اختصاص الله بإحاطة العلم بهم وبالقدرة على عقوبتهم، في مقابلة خفائهم عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص214، تحت «بلاغة المؤكدات في التعبير بالاسمية وذكر المسند إليه مرتين في جملة نحن نعلمهم»","url":""}]},{"id":"s9-557","number":557,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"كيف يزيد قوله: ﴿سنعذبهم مرتين﴾ الوعيد للمنافقين؟","answer":"يؤكد السين تحقق الوعيد، وتفيد مرتين تكرر العقوبة قبل العذاب العظيم في الآخرة. ويعرض المصدر أوجهًا في العذابين، منها عذاب الدنيا وعذاب القبر، كما يذكر احتمال إرادة التكثير؛ فلا يجزم بتعيين صورة واحدة للعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص217، تحت «دلالة دخول سين التسويف على العذاب»","url":""}]},{"id":"s9-558","number":558,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم يردون إلى عذاب عظيم﴾ بعد العذاب مرتين؟","answer":"بعد عقوبتين قبل القيامة يردون إلى عذاب الآخرة العظيم؛ و﴿ثم﴾ تدل على تراخي المراحل مع تفاوت عظم العذاب الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص219، تحت «فائدة وصف العذاب بأنه عظيم»","url":""}]},{"id":"s9-559","number":559,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿وآخرون اعترفوا بذنوبهم﴾ دون ذكر اعتذارهم؟","answer":"الاعتراف الصادق يغني عن الاعتذار المصنوع؛ فهم أقروا بالذنب ولم يحاولوا تزيينه، فتميزوا من المنافقين المعتذرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص221، تحت «معنى الباء في بذنوبهم»","url":""}]},{"id":"s9-560","number":560,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما دلالة إضافة الذنوب إلى ضميرهم في قوله: ﴿اعترفوا بذنوبهم﴾؟","answer":"تؤكد الإضافة تحملهم مسؤولية ما اقترفوه وصدق ندمهم؛ فهم يقرون بأنها ذنوبهم التي فعلوها، ولا يدفعون تبعتها إلى غيرهم أو يسترونها بأعذار مصنوعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص221–222، تحت «غرض إضافة الذنوب إلى ضميرهم»","url":""}]},{"id":"s9-561","number":561,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿خلطوا عملًا صالحًا وآخر سيئًا﴾، فجعل العملين كشيئين يختلطان؟","answer":"شبهت الأعمال بأشياء مزج بعضها ببعض؛ إذ لم يخلص حالهم للصلاح ولا للسوء، بل اجتمع صدق الإيمان مع معصية التخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص223، تحت «دلالة التعبير بخلطوا مادة وصيغة»","url":""}]},{"id":"s9-562","number":562,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما سرّ تقديم العمل الصالح على السيئ؟","answer":"في تقديم الصالح تشريف له وتنويه بما في حالهم من خير؛ فقد خالط تقصيرهم عمل صالح، فرجح ذلك جانب الرجاء فيهم. ولا يلزم من التقديم وحده أن يكون الصلاح غالبًا على جميع أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص223، تحت «نكتة التنكير والإفراد في عملًا وصالحًا وتقديمهما»","url":""}]},{"id":"s9-563","number":563,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿عسى الله أن يتوب عليهم﴾ مع اعترافهم وندمهم؟","answer":"﴿عسى﴾ من جهة المخاطبين تربيهم بين الرجاء والخوف ولا تجعل التوبة حقًا واجبًا لهم، ووعد الله بها متحقق لمن صدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص226، تحت «غرض التعبير بالمضارع في يتوب»","url":""}]},{"id":"s9-564","number":564,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"لماذا ختمت آية المعترفين بذنوبهم (التوبة: 102) بـ﴿إن الله غفور رحيم﴾؟","answer":"﴿غفور﴾ يستر ذنوب المعترفين إذا تابوا، و﴿رحيم﴾ يقبلهم ويعيدهم إلى أهل الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص226، تحت «بلاغة التذييل بهذين الاسمين الجليلين»","url":""}]},{"id":"s9-764","number":764,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما غرض صيغ المبالغة في ﴿غفور رحيم﴾؟","answer":"تفيد كثرة المغفرة وسعة الرحمة ودوامهما، فتفتح للمعترفين باب التوبة والقبول مهما عظم تقصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص228، تحت «غرض صيغ المبالغة فيهما»","url":""}]},{"id":"s9-565","number":565,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"لماذا أُمر النبي ﷺ أن يأخذ من أموالهم صدقة بعد اعترافهم؟","answer":"كان أخذ الصدقة مظهرًا عمليًا لصدق توبتهم، ولا سيما أن التعلق بالأموال والتثاقل عن الإنفاق كان من أسباب تخلفهم. فبذل المال يعالج هذا التقصير، وتكون الصدقة سببًا لتطهيرهم وتزكيتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص233، تحت «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s9-566","number":566,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿تطهرهم وتزكيهم بها﴾، وما الفرق بين التطهير والتزكية؟","answer":"التطهير إزالة دنس الذنب والبخل، والتزكية تنمية الخير والبركة ورفع المنزلة؛ فالصدقة تزيل النقص وتنمي الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص268، تحت «التطهير والتزكية»","url":""}]},{"id":"s9-567","number":567,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"كيف يختلف إسناد التطهير في ﴿تطهرهم﴾ بحسب عود التاء إلى النبي ﷺ أو إلى الصدقة؟","answer":"يجوز أن تكون التاء للخطاب، فيكون النبي ﷺ مطهرًا لهم بأخذ صدقتهم. ويجوز أن تكون للغيبة، فيكون الفاعل ضمير الصدقة؛ فهي سبب تطهيرهم بما يترتب عليها من مغفرة وثواب. ويرجع الوجهان إلى بيان أثر الصدقة المقبولة في أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص242، تحت «نكتة عود التاء في تطهرهم»","url":""}]},{"id":"s9-568","number":568,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿وصل عليهم إن صلاتك سكن لهم﴾؟","answer":"الصلاة عليهم دعاء لهم، و﴿سكن﴾ طمأنينة تستقر بها قلوبهم لقبول توبتهم وبركة دعاء الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص247، تحت «بلاغة الاستئناف البياني إن صلاتك سكن لهم»","url":""}]},{"id":"s9-569","number":569,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"لماذا عبر باسم الألوهية دون الربوبية في هذا السياق؟","answer":"لأن اسم الجلالة يجمع صفات الكمال ويوافق مقام العبادة والتطهير وقبول التوبة، وهو أعم من استحضار معنى التربية وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص251، تحت «سر التعبير بالألوهية دون الربوبية»","url":""}]},{"id":"s9-765","number":765,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"لماذا ختمت آية أخذ الصدقة (التوبة: 103) بـ﴿والله سميع عليم﴾؟","answer":"هو سميع لدعاء الرسول واعترافهم، وعليم بصدق نياتهم وتوبتهم؛ فيجازي كلًا على ظاهره وباطنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص252، تحت «بلاغة التذييل بهذين الاسمين الجليلين»","url":""}]},{"id":"s9-766","number":766,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"لماذا قدم ﴿سميع﴾ على ﴿عليم﴾؟","answer":"لأن السياق بدأ بالدعاء المسموع، فقدم السمع المتصل بظاهر القول ثم أتبع بالعلم المحيط بالنيات والسرائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص252، تحت «نكتة تقديم سميع على عليم»","url":""}]},{"id":"s9-570","number":570,"surah":9,"verses":[104],"references":[{"surah":9,"verses":[104]}],"verseLabel":"التوبة: 104","question":"لماذا سأل: ﴿ألم يعلموا أن الله هو يقبل التوبة عن عباده ويأخذ الصدقات﴾؟","answer":"الاستفهام للتقرير والحض على التوبة والصدقة؛ فالله وحده يقبل توبة عباده ويقبل صدقاتهم، فلا ييأس المذنب ولا يمن بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص253، تحت «نكتة فصل الآية ألم يعلموا أن الله هو يقبل عن سابقتها»","url":""}]},{"id":"s9-571","number":571,"surah":9,"verses":[104],"references":[{"surah":9,"verses":[104]}],"verseLabel":"التوبة: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿يقبل التوبة عن عباده﴾ بـ﴿عن﴾ لا «من»؟","answer":"﴿عن﴾ تشعر بالتجاوز والصفح عن الذنب عند قبول التوبة، أما ﴿من﴾ فمجرد ابتداء الأخذ من التائب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص260، تحت «بلاغة تضمين الفعل يقبل الفعل يتجاوز وتعديتها بعن»","url":""}]},{"id":"s9-572","number":572,"surah":9,"verses":[104],"references":[{"surah":9,"verses":[104]}],"verseLabel":"التوبة: 104","question":"ما سرّ نسبة أخذ الصدقات إلى الله مع أن النبي ﷺ هو الذي يأخذها؟","answer":"نسب الأخذ إلى الله لأنه الآمر بالصدقة والمتقبل لها والمثيب عليها، والنبي ﷺ مباشر لأخذها؛ فنسب الفعل إلى مسبب قبوله وغايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص263، تحت «بلاغة الاستعارة في أخذ الصدقات»","url":""}]},{"id":"s9-573","number":573,"surah":9,"verses":[104],"references":[{"surah":9,"verses":[104]}],"verseLabel":"التوبة: 104","question":"لماذا جاء ضمير الفصل في ﴿وأن الله هو التواب الرحيم﴾؟","answer":"ضمير الفصل ﴿هو﴾ يقصر كمال قبول التوبة والرحمة على الله، ويؤكد أنه كثير التوبة على عباده لا يرده ذنب مع صدق الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص266، تحت «بلاغة القصر في تعريف طرفي الإسناد وفي ضمير الفصل»","url":""}]},{"id":"s9-574","number":574,"surah":9,"verses":[105],"references":[{"surah":9,"verses":[105]}],"verseLabel":"التوبة: 105","question":"لماذا جاء الأمر المطلق: ﴿وقل اعملوا﴾ بعد الحديث عن التوبة والصدقة؟","answer":"الأمر عام ليستأنف التائبون عملًا يصدق توبتهم، ويعلم الجميع أن الاعتبار بما يعملون بعد الدعوى والاعتراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص271، تحت «بلاغة العطف في وقل اعملوا»","url":""}]},{"id":"s9-575","number":575,"surah":9,"verses":[105],"references":[{"surah":9,"verses":[105]}],"verseLabel":"التوبة: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿فسيرى الله عملكم ورسوله والمؤمنون﴾؟","answer":"الفاء تصل العمل بنتيجته القريبة: لا يخفى على الله، ويظهر أثره للرسول والمؤمنين؛ ففيها وعد للمحسن ووعيد للمسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص273، تحت «معنى الفاء في فسيرى»","url":""}]},{"id":"s9-576","number":576,"surah":9,"verses":[105],"references":[{"surah":9,"verses":[105]}],"verseLabel":"التوبة: 105","question":"لماذا أعيد ذكر رؤية الله والرسول للعمل بعد الآية 94 وزيد هنا ﴿المؤمنون﴾؟","answer":"آية 94 في المنافقين وضمائرهم الخفية، فاقتصر على الله ورسوله بإطلاع الله؛ وهذه في التائبين المؤمنين وأعمالهم الظاهرة، فزاد ﴿المؤمنون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص285، تحت «سر ذكر لفظ والمؤمنون هنا وعدم حذفه»","url":""}]},{"id":"s9-577","number":577,"surah":9,"verses":[105],"references":[{"surah":9,"verses":[105]}],"verseLabel":"التوبة: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿وستردون إلى عالم الغيب والشهادة﴾ بدل «إلى الله»؟","answer":"الوصف يستحضر إحاطة علمه بكل باطن وظاهر عند الرجوع إليه؛ فلا ينفع ستر النية ولا تجميل العمل أمام الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص280، تحت «سر العدول عن الظاهر للمضمر في عالم الغيب والشهادة»","url":""}]},{"id":"s9-578","number":578,"surah":9,"verses":[105],"references":[{"surah":9,"verses":[105]}],"verseLabel":"التوبة: 105","question":"لماذا ختم بـ﴿فينبئكم بما كنتم تعملون﴾؟","answer":"الإنباء إظهار حقيقة الأعمال والحكم عليها والجزاء بها؛ فهو ختام يربط الأمر بالعمل بالحساب النهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص282، تحت «معنى الفاء في فينبئكم»","url":""}]},{"id":"s9-579","number":579,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿وآخرون مرجون لأمر الله﴾ بعد ذكر المعترفين التائبين؟","answer":"بعد من اعترفوا وتابوا ذكر فريقًا أُخر حكمهم مؤخر ينتظر أمر الله؛ فميز بين توبة ظهرت وحال لم يُقض فيها بعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص291، تحت «دلالة العطف في وآخرون»","url":""}]},{"id":"s9-580","number":580,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"لماذا بُني ﴿مرجون﴾ للمجهول؟","answer":"البناء للمجهول يركز على حالهم: مؤخرون موقوف أمرهم، مع العلم بأن المؤخر هو الله؛ وفيه تصوير القلق والانتظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص292، تحت «فائدة التعبير بمرجون مادة وصيغة»","url":""}]},{"id":"s9-581","number":581,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"لماذا قابل: ﴿إما يعذبهم وإما يتوب عليهم﴾؟","answer":"﴿إما... وإما﴾ تبقيهم بين احتمال العقوبة واحتمال قبول التوبة بحسب علم الله وحكمته، فلا يقطع لهم قبل صدور الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص294، تحت «الموقع البياني إما يعذبهم وإما يتوب عليهم»","url":""}]},{"id":"s9-582","number":582,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"ما سرّ تقديم احتمال العذاب على التوبة؟","answer":"قدم العذاب لأن سبب استحقاقه، وهو التخلف بلا عذر، متحقق ظاهرًا، أما التوبة ففضل مرجو متعلق بصدق رجوعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص295–296، تحت «نكتة تقديم العذاب على التوبة»","url":""}]},{"id":"s9-583","number":583,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"لماذا ختم الحديث عن المرجئين بـ﴿والله عليم حكيم﴾؟","answer":"هو عليم بحقيقة قلوبهم وتوبتهم، وحكيم في اختيار العذاب أو القبول؛ فلا يكون التأخير عن جهل أو تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص297، تحت «بلاغة التذييل بهذين الاسمين الجليلين»","url":""}]},{"id":"s9-767","number":767,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"لماذا قدم ﴿عليم﴾ على ﴿حكيم﴾ في شأن المرجئين؟","answer":"لأن الحكم في قبولهم أو عذابهم مبني على العلم بحقائقهم، فقدم أساس الحكم على أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص297، تحت «نكتة تقديم عليم على حكيم»","url":""}]},{"id":"s9-584","number":584,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين اتخذوا مسجدًا ضرارًا﴾، فسمى المكان مسجدًا مع فساد قصده؟","answer":"سماه مسجدًا بحسب الصورة والاسم الذي وضعه أصحابه، ثم كشفت الأغراض المنصوبة فساد حقيقته؛ فالعبرة بالمقصد لا بالاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص305، تحت «دلالة التعبير بصيغة الافتعال في اتخذوا»","url":""}]},{"id":"s9-585","number":585,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"لماذا عدّد أغراض مسجد الضرار: ضرارًا وكفرًا وتفريقًا وإرصادًا؟","answer":"عددها لكشف طبقات الجريمة: الإضرار بالمؤمنين، وتقوية الكفر، وتفريق الجماعة، وإعداد المكان لمن حارب الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص307، تحت «بلاغة حذف متعلقات ضرارًا وكفرًا»","url":""}]},{"id":"s9-586","number":586,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"ما سرّ تقديم الضرار على الكفر؟","answer":"يرتب المصدر الأغراض من الأعم إلى الأخص: فالضرار يشمل الأذى في الدين وغيره، والكفر وتقوية النفاق أخص منه، ثم تفريق المؤمنين، ثم الإرصاد لمن حارب الله ورسوله. فتقديم الضرار يفتتح بالغرض الأوسع ثم يفصل وجوهه الأخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص307–308، تحت «نكتة الترتيب في العطف بين علل اتخاذ المسجد»","url":""}]},{"id":"s9-587","number":587,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"ما معنى ﴿إرصادًا لمن حارب الله ورسوله﴾؟","answer":"الإرصاد الإعداد والترقب؛ أي اتخذوه موضعًا مهيأ لمن سبق بمحاربة الله ورسوله ليكون قاعدة له عند قدومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص308، تحت «معنى من في لمن حارب»","url":""}]},{"id":"s9-588","number":588,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿من قبل﴾ بعد ذكر المحاربة؟","answer":"﴿من قبل﴾ تبين أن المحاربة سابقة على بناء المسجد، وأن الإرصاد امتداد لخطة قديمة لا حادثة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص310، تحت «معنى من في من قبل»","url":""}]},{"id":"s9-589","number":589,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"لماذا أكدوا حلفهم: ﴿وليحلفن إن أردنا إلا الحسنى﴾؟","answer":"اللام ونون التوكيد في الحلف تقابلان شناعة مقاصدهم؛ وحصروا إرادتهم في ﴿الحسنى﴾ زاعمين الإحسان والخير لستر الضرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص311، تحت «معنى اللام في وليحلفن ودلالة المؤكدات فيها»","url":""}]},{"id":"s9-590","number":590,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿والله يشهد إنهم لكاذبون﴾؟","answer":"قابل حلفهم بشهادة الله المحيطة ببواطنهم، وأكد كذبهم بـ﴿إن﴾ واللام؛ فشهادة الله أصدق من أيمانهم المؤكدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص313، تحت «معنى الواو في والله يشهد وموقع الجملة بعدها»","url":""}]},{"id":"s9-591","number":591,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"لماذا جاء النهي: ﴿لا تقم فيه أبدًا﴾، ولم يقل: «لا تصل فيه»؟","answer":"عبر عن الصلاة بالقيام، وهو ركن منها، فأطلق الجزء وأراد الكل على سبيل المجاز المرسل، مع الاهتمام بشأن هذا الركن. وأكد النهي بأبدًا ليشمل جميع الأزمنة؛ فالمراد في هذا الموضع منع الصلاة في مسجد الضرار منعًا دائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص348، تحت «لا تقم فيه ولا تصل»","url":""}]},{"id":"s9-592","number":592,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"لماذا قابل مسجد الضرار بمسجد ﴿أسس على التقوى من أول يوم﴾؟","answer":"المقابلة تكشف أن قيمة المسجد بأساسه وغايته: ذاك أسس للإضرار والكفر، وهذا أسس منذ البدء على تقوى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص318، تحت «بلاغة الاستعارة المكنية في أسس على التقوى»","url":""}]},{"id":"s9-593","number":593,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿من أول يوم﴾؟","answer":"تدل على أن التقوى صاحبت تأسيسه من أول لحظة ولم تطرأ عليه بعد ذلك، فثبت إخلاص الأصل واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص318، تحت «معنى من في من أول يوم»","url":""}]},{"id":"s9-594","number":594,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿أحق أن تقوم فيه﴾ مع أن القيام في مسجد الضرار منهي عنه؟","answer":"﴿أحق﴾ للمفاضلة بالنظر إلى دعواهم أن مسجدهم أعد للخير، أي هذا وحده أجدر بالقيام؛ ومع النهي عن الآخر تصير الأحقية تعيينًا لا مشاركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص319، تحت «دلالة التعبير بأحق لغة وصرفا»","url":""}]},{"id":"s9-595","number":595,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"لماذا وصف أهله بأنهم ﴿يحبون أن يتطهروا﴾، ولم يقل: «يتطهرون»؟","answer":"ذكر محبتهم للتطهر لأنها الدافع الباطني المستمر إلى استعمال أسبابه، والمدح بمحبة الطهارة أبلغ من فعل قد يقع بلا إخلاص أو مداومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص323، تحت «غرض التعبير بالمضارعة في يحبون ويتطهروا»","url":""}]},{"id":"s9-596","number":596,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"لماذا ختم بـ﴿والله يحب المطهرين﴾؟","answer":"الخاتمة تعلل مدح أهل المسجد: محبتهم للطهارة عمل يحبه الله، وفيها ترغيب في الجمع بين طهارة الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص324، تحت «معنى الواو في والله»","url":""}]},{"id":"s9-597","number":597,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"لماذا صوّر العمل الصالح بأنه بنيان مؤسس على تقوى ورضوان؟","answer":"شُبهت الأعمال ببنيان لأن العقيدة والقصد أساس يحمل العمل؛ فما قام على التقوى ثبت ونفع صاحبه كما يثبت البناء على أصل محكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص332، تحت «بلاغة الاستعارة في تأسيس البنيان على التقوى»","url":""}]},{"id":"s9-598","number":598,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"لماذا جمع بين ﴿تقوى من الله ورضوان﴾؟","answer":"التقوى اجتناب سخط الله وهي أساس العمل، والرضوان غايته وثمرته؛ فجمع سلامة المبدأ وحسن المقصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص332، تحت «نكتة تنكير لفظي تقوى ورضوان»","url":""}]},{"id":"s9-599","number":599,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"لماذا شبه عمل المنافق ببنيان على ﴿شفا جرف هار﴾؟","answer":"شفا الجرف حافته التي أكلها السيل من أسفل فأشرفت على السقوط. فتمثل الصورة عمل المنافق القائم على أصل واهٍ، ينتهي انهياره بصاحبه إلى الهلاك؛ وتقابله صورة البناء المحكم على التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص334، تحت «بلاغة التشبيه المتفرع عن الاستعارة المكنية في الآية»","url":""}]},{"id":"s9-600","number":600,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿فانهار به في نار جهنم﴾، فجعل البنيان يهوي بصاحبه؟","answer":"الفاء تصور سرعة الانهيار، والباء في ﴿به﴾ تجعل الباني مصاحبًا لبنيانه في السقوط؛ ففساد العمل يورد صاحبه النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص336، تحت «معنى الفاء في فانهار به»","url":""}]},{"id":"s9-601","number":601,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"ما فائدة التعبير بالمضارع في ﴿يهدي﴾؟","answer":"يفيد تجدد نفي التوفيق واستمراره ما داموا مصرين على الظلم، فلا تنفك النتيجة عن سببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص339، تحت «فائدة التعبير بالمضارع يهدي»","url":""}]},{"id":"s9-768","number":768,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"لماذا وصفوا بالظلم في ﴿والله لا يهدي القوم الظالمين﴾؟","answer":"لأنهم وضعوا العبادة في غير موضعها واتخذوا المسجد للإضرار والتفريق، فكان الظلم أنسب وصف يكشف حقيقة صنيعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص340، تحت «علة وصفهم بالظلم»","url":""}]},{"id":"s9-602","number":602,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يزال بنيانهم الذي بنوا ريبة في قلوبهم﴾؟","answer":"ظل البناء سبب شك واضطراب في قلوبهم بما تعلق به من نفاق وحسرة بعد هدمه؛ فالجملة تصور دوام أثر الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص341، تحت «نكتة الفصل لا يزال بنيانهم»","url":""}]},{"id":"s9-603","number":603,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"لماذا كرر الجذر: ﴿بنيانهم الذي بنوا﴾؟","answer":"التكرار يواجههم بصنيعهم: هذا البنيان المنسوب إليهم هو الذي تعمدوا بناءه، فلا ينفصل أثره عن كسبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص342، تحت «فائدة التعبير بالاسم الموصول وصلته الذي بنوا»","url":""}]},{"id":"s9-604","number":604,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"لماذا جعل غاية الريبة: ﴿إلا أن تقطع قلوبهم﴾؟","answer":"المعنى أن الريبة تلازمهم إلى أن تتقطع قلوبهم بالموت أو الندم الشديد؛ فجعل لها غاية تهول استمرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص343، تحت «نكتة الاستثناء المصدّر بالأداة إلا»","url":""}]},{"id":"s9-605","number":605,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"لماذا لم يقل: «حتى يموتوا»؟","answer":"﴿تقطع قلوبهم﴾ يصور الموت أو تمزق القلوب بالحسرة تصويرًا محسوسًا، وهو أبلغ من الخبر المباشر عن انتهاء الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص345، تحت «بلاغة الكناية عن صفة في تقطيع القلوب»","url":""}]},{"id":"s9-606","number":606,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"لماذا ختم خبر مسجد الضرار بـ﴿والله عليم حكيم﴾؟","answer":"هو عليم بنياتهم الخفية في البناء، وحكيم في كشفها وهدم مسجد الضرار وترتيب الجزاء عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص346، تحت «سر تذييل الآية بهذين الاسمين الجليلين»","url":""}]},{"id":"s9-769","number":769,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"ما سر تقديم العلم على الحكمة؟","answer":"لأن الحكمة في الحكم والجزاء ثمرة العلم بالنيات والحقائق، فقدم السبب الذي يقوم عليه الحكم المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص347، تحت «سر تقديم العلم على الحكمة»","url":""}]},{"id":"s9-607","number":607,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"لماذا صوّر علاقة المؤمن بالله بالبيع: ﴿إن الله اشترى من المؤمنين أنفسهم وأموالهم﴾؟","answer":"البيع تمثيل لعهد المؤمن: يبذل نفسه وماله لله في مقابل الجنة، وفي الصورة توثيق للالتزام وتشريف للعوض والمعوَّض.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص353، تحت «بلاغة الاستعارة إن الله اشترى»","url":""}]},{"id":"s9-608","number":608,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"ما سرّ تقديم الأنفس هنا على الأموال، بخلاف مواضع الجهاد السابقة؟","answer":"قدمت الأنفس لأنها أعز ما يملكه الإنسان، ولأن المقام مقام بذلها حتى القتل في سبيل الله. أما تقديم الأموال في مواضع أخرى فيناسب كونها وسيلة إلى تجهيز الجهاد وحماية النفس؛ فلكل ترتيب ما يلائم سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص355، تحت «علة تقديم الأنفس على الأموال»","url":""}]},{"id":"s9-609","number":609,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"ما وجه تصوير المعاملة بالشراء في قوله تعالى: ﴿إن الله اشترى من المؤمنين أنفسهم وأموالهم﴾ مع أن الله مالكهم ومالك أموالهم؟","answer":"ملك الله لهم أصلي، لكنه عاملهم تفضلًا معاملة المالك المختار، فسمى بذل ما استخلفهم فيه بيعًا وأعطاهم عليه الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص353، تحت «بلاغة الاستعارة إن الله اشترى»","url":""}]},{"id":"s9-610","number":610,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"لماذا جعل الثمن ﴿بأن لهم الجنة﴾؟","answer":"الباء للمقابلة، والجنة ثمن كريم دائم لنفس ومال فانيين؛ وفيه إظهار عظم فضل المشتري وربح المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص355، تحت «معنى الباء في بأن»","url":""}]},{"id":"s9-611","number":611,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿فيقتلون ويُقتلون﴾، وقدم الفعل المعلوم على المبني للمجهول؟","answer":"في قراءة تقديم الفعل المعلوم إبراز لقتالهم عدوهم ثم احتمال قتلهم في سبيل الله؛ وفي القراءة الأخرى قدم المبني للمجهول للاهتمام بالشهادة. وتدل القراءتان على ثباتهم على القتال وإن قتل بعضهم، ولا يلزم أن يقع الفعلان من كل فرد بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص358، تحت «بلاغة توجيه القراءات في فيقتلون ويقتلون»","url":""}]},{"id":"s9-612","number":612,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"لماذا ذكر التوراة والإنجيل والقرآن في توثيق الوعد؟","answer":"ذكر الكتب الثلاثة لبيان قدم الوعد وثباته في الشرائع الكبرى، وأنه عهد إلهي واحد لم ينفرد به القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص361، تحت «بلاغة الترتيب بين الكتب الثلاثة»","url":""}]},{"id":"s9-613","number":613,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن أوفى بعهده من الله﴾ بصيغة السؤال؟","answer":"الاستفهام إنكاري تقريري: لا أحد أوفى بعهده من الله، فيورث اليقين بالعوض ويزيل كل تردد في الصفقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص362، تحت «بلاغة الاستفهام وغرضه ومن أوفى»","url":""}]},{"id":"s9-614","number":614,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"لماذا ختم بـ﴿فاستبشروا ببيعكم... وذلك هو الفوز العظيم﴾؟","answer":"الأمر بالاستبشار يعلن تمام الصفقة وربحها، واسم الإشارة مع ﴿هو﴾ يقصر الفوز العظيم على هذا البيع المضمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص366، تحت «بلاغة التذييل التعليلي في الإشارة إلى الفوز العظيم»","url":""}]},{"id":"s9-615","number":615,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"لماذا جاءت صفات المؤمنين سلسلة أسماء: ﴿التائبون العابدون الحامدون...﴾؟","answer":"الأسماء تدل على ثبوت الصفات ورسوخها، وتعرض المؤمنين كأن كل خصلة صارت سمة معروفة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص375، تحت «دلالة التعبير عن أوصاف المؤمنين بأسماء الفاعلين»","url":""}]},{"id":"s9-616","number":616,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"لماذا بدأت الصفات بالتوبة؟","answer":"بدأت بالتوبة لأنها تطهر من الموانع وتفتح طريق العبودية؛ فمن رجع عن الذنب استقام له ما بعدها من الصفات.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص376، تحت «سر ترتيب هذه الصفات»","url":""}]},{"id":"s9-617","number":617,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿السائحون﴾، وما صلتها بالصيام أو طلب العلم والجهاد؟","answer":"السياحة مفارقة المألوف في طاعة الله؛ ففسرت بالصيام لانقطاع الصائم عن الشهوات، وبالسفر في طلب العلم أو الجهاد، ويجمعها التجرد للطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص378، تحت «بلاغة الاستعارة في السائحون»","url":""}]},{"id":"s9-618","number":618,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"لماذا أفرد الركوع والسجود كصفتين بعد العبادة؟","answer":"خُصا لأنهما أبرز هيئات الصلاة وأدلها على الخضوع، والسجود غاية التذلل؛ ففصلا بعد عموم العبادة للتنويه بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص379، تحت «سر التعبير عن الصلاة ببعض أجزائها»","url":""}]},{"id":"s9-619","number":619,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"لماذا عطف ﴿الناهون عن المنكر﴾ على ﴿الآمرون بالمعروف﴾ بالواو، مع تتابع الصفات السابقة بلا عطف؟","answer":"تتابع الصفات السابقة بلا عطف يصورها صفات متلازمة لموصوف واحد. أما الواو بين الأمر بالمعروف والنهي عن المنكر فتبرز التمييز بين الوظيفتين والاعتداد بكل واحدة، مع تلازمهما في إصلاح الغير؛ فلا يكتفى بأحدهما عن الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص380، تحت «نكتة العطف في الآمرون بالمعروف والناهون عن المنكر»","url":""}]},{"id":"s9-620","number":620,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"لماذا ختم الصفات بـ﴿والحافظون لحدود الله﴾؟","answer":"حفظ الحدود جامع للقيام بالأوامر واجتناب النواهي، فختم به ليستوعب ما لم تفصله الصفات السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص384، تحت «سر ختم هذه الصفات بالحفظ لحدود الله»","url":""}]},{"id":"s9-621","number":621,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"ما سرّ التعبير في قوله تعالى في النهاية: ﴿وبشر المؤمنين﴾ بدل إعادة الصفات؟","answer":"ردهم إلى الاسم الجامع ﴿المؤمنين﴾ لأن تلك الصفات شواهد الإيمان، ولتعم البشارة كل من تحقق بها دون إعادة طويلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص387، تحت «سر ختام الآية بالبشارة وبشر المؤمنين مع سبق ذكرها»","url":""}]},{"id":"s9-622","number":622,"surah":9,"verses":[113],"references":[{"surah":9,"verses":[113]}],"verseLabel":"التوبة: 113","question":"لماذا نُهي النبي والمؤمنون عن الاستغفار للمشركين ولو كانوا أولي قربى؟","answer":"إذا تبين موت المشرك على الشرك انقطع محل المغفرة، وقرابة النسب لا تقدم على حق الله ولا تغير حكم الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص397، تحت «سر التعبير ولو كانوا أولي قربى»","url":""}]},{"id":"s9-623","number":623,"surah":9,"verses":[113],"references":[{"surah":9,"verses":[113]}],"verseLabel":"التوبة: 113","question":"لماذا جاء القيد: ﴿من بعد ما تبين لهم أنهم أصحاب الجحيم﴾؟","answer":"يقيد النهي بحصول التبين، ومن صوره في المصدر موت المشرك على شركه أو ورود الوحي ببيان مآله. أما قبل ذلك فلا يلزم انقطاع الرجاء في إيمانه؛ ويذكر المصدر الدعاء للأحياء بطلب توفيقهم إلى الهدى. فلا يخلط الدعاء بالهداية بالاستغفار لمن ثبت موته على الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص399، تحت «دلالة تقييد النهي بالتبيين من بعد ما تبين لهم»","url":""}]},{"id":"s9-624","number":624,"surah":9,"verses":[113],"references":[{"surah":9,"verses":[113]}],"verseLabel":"التوبة: 113","question":"لماذا وصفوا بـ﴿أصحاب الجحيم﴾؟","answer":"الصحبة تفيد الملازمة؛ أي هم أهل الجحيم الملازمون لها، لا عذابًا عابرًا ينتهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص401، تحت «سر اختيار الجحيم دون غيرها من أوصاف النار»","url":""}]},{"id":"s9-625","number":625,"surah":9,"verses":[114],"references":[{"surah":9,"verses":[114]}],"verseLabel":"التوبة: 114","question":"لماذا استغفر إبراهيم لأبيه مع النهي الوارد في الآية السابقة؟","answer":"كان استغفاره متعلقًا بموعدة ورجاء إيمان أبيه، لا استغفارًا بعد ثبوت مآله على الشرك. ومن أوجه الضمير أن إبراهيم وعد أباه بالاستغفار، ويذكر المصدر أيضًا أن أباه وعده بالإيمان؛ فلما تبينت عداوته لله تبرأ منه، فلا تعارض مع النهي بعد التبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص403، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-626","number":626,"surah":9,"verses":[114],"references":[{"surah":9,"verses":[114]}],"verseLabel":"التوبة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما تبين له أنه عدو لله تبرأ منه﴾؟","answer":"الفاء تفيد أن البراءة أعقبت التبين بلا إبطاء، فقدم حق الله على عاطفة الأبوة حين انكشف المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص409، تحت «سر التعبير بقوله تبرأ منه»","url":""}]},{"id":"s9-627","number":627,"surah":9,"verses":[114],"references":[{"surah":9,"verses":[114]}],"verseLabel":"التوبة: 114","question":"لماذا ختم بوصف إبراهيم: ﴿لأواه حليم﴾؟","answer":"﴿أواه﴾ كثير التضرع والتأوه رحمة، و﴿حليم﴾ لا يعجل بالعقوبة؛ فالوصفان يفسران رفقه واستغفاره قبل التبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص411، تحت «سر ختم الآية بهذين الوصفين»","url":""}]},{"id":"s9-628","number":628,"surah":9,"verses":[115],"references":[{"surah":9,"verses":[115]}],"verseLabel":"التوبة: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان الله ليضل قومًا بعد إذ هداهم حتى يبين لهم ما يتقون﴾؟","answer":"نفت الآية أن يؤاخذ الله المهتدين على أمر لم يبين لهم وجوب اتقائه؛ فالحجة والبيان يسبقان المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص416، تحت «دلالة النفي في وما كان»","url":""}]},{"id":"s9-629","number":629,"surah":9,"verses":[115],"references":[{"surah":9,"verses":[115]}],"verseLabel":"التوبة: 115","question":"ما دلالة صيغة النفي في قوله: ﴿وما كان الله ليضل قومًا﴾؟","answer":"تؤكد الصيغة نفي الحكم بالضلال والمؤاخذة قبل البيان؛ فإقامة الحجة سابقة للمؤاخذة، وهذه سنة ثابتة في معاملة العباد. وفي ذلك طمأنة لمن خاف المؤاخذة بفعل سبق ورود النهي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص416، تحت «دلالة النفي في وما كان»","url":""}]},{"id":"s9-630","number":630,"surah":9,"verses":[115],"references":[{"surah":9,"verses":[115]}],"verseLabel":"التوبة: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿بعد إذ هداهم﴾؟","answer":"تذكرهم بنعمة الهداية السابقة وتطمئنهم أنها لا تسلب لمجرد فعل وقع قبل بيان حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص419، تحت «فائدة التعبير بالظرفية في بعد إذ هداهم»","url":""}]},{"id":"s9-631","number":631,"surah":9,"verses":[115],"references":[{"surah":9,"verses":[115]}],"verseLabel":"التوبة: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى يبين لهم ما يتقون﴾ لا «ما يفعلون»؟","answer":"التقوى لفظ جامع لما يتقى به سخط الله؛ فيشمل امتثال الأوامر واجتناب النواهي، ومن ذلك النهي عن الاستغفار للمشركين في السياق. فالتعبير يربط البيان بما يحقق الوقاية، ولا يقتصر على مجرد معرفة ما يفعلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص422، تحت «دلالة التعبير بما»","url":""}]},{"id":"s9-632","number":632,"surah":9,"verses":[115],"references":[{"surah":9,"verses":[115]}],"verseLabel":"التوبة: 115","question":"لماذا ختم بـ﴿إن الله بكل شيء عليم﴾؟","answer":"علمه بكل شيء يقتضي علمه بأحوال العباد وما بلّغوا وما خفي عنهم، فيجري البيان والمؤاخذة على عدل تام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص422، تحت «بلاغة الفصل في إن الله بكل شيء عليم»","url":""}]},{"id":"s9-633","number":633,"surah":9,"verses":[116],"references":[{"surah":9,"verses":[116]}],"verseLabel":"التوبة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الله له ملك السماوات والأرض﴾ بعد الحديث عن الهداية والبيان؟","answer":"الملك المطلق دليل قدرته على الهداية والتشريع والجزاء؛ فمن له السماوات والأرض وحده له الحكم والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص430، تحت «سر التعبير بقوله له ملك»","url":""}]},{"id":"s9-634","number":634,"surah":9,"verses":[116],"references":[{"surah":9,"verses":[116]}],"verseLabel":"التوبة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿يحيي ويميت﴾ بالمضارع؟","answer":"المضارعان يدلان على تجدد آثار قدرته واستمرارها في إحياء الخلق وإماتتهم، وأن الأمر كله بيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص433، تحت «سر التعبير بالفعل المضارع يحيي ويميت»","url":""}]},{"id":"s9-635","number":635,"surah":9,"verses":[116],"references":[{"surah":9,"verses":[116]}],"verseLabel":"التوبة: 116","question":"لماذا نُفي الولي والنصير معًا؟","answer":"الولي يتولى شؤونهم ويجلب النفع، والنصير يدفع الضر؛ فنفيهما يستوعب وجهي الحماية من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص436، تحت «دلالة الجمع بين الولي والنصير في النفي»","url":""}]},{"id":"s9-636","number":636,"surah":9,"verses":[116],"references":[{"surah":9,"verses":[116]}],"verseLabel":"التوبة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿من دون الله من ولي ولا نصير﴾ بتكرار ﴿من﴾؟","answer":"ليست من في الموضعين لوظيفة واحدة: فالأولى في ﴿من دون الله﴾ تبين أن الولاية والنصرة المقصودتين لا تكونان استقلالًا من غيره. وأما ﴿من ولي﴾ مع النفي فتفيد استغراق جنس الولي، ويؤكد تكرار لا شمول النفي للنصير أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص434، تحت «دلالة من في من دون الله»","url":""}]},{"id":"s9-637","number":637,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد تاب الله على النبي والمهاجرين والأنصار﴾ مع عصمة النبي ﷺ؟","answer":"يعرض المصدر للتوبة درجات بحسب من أسندت إليه؛ فتكون في حق النبي ﷺ ارتقاءً في مراتب الكمال، أو رجوعًا إلى الأولى والأفضل في شأن الإذن للمتخلفين. وفي تقديم ذكره تشريف للمهاجرين والأنصار وترغيب للجميع في التوبة، دون تسوية أحوالهم جميعًا في الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص441، تحت «سر التعبير بالتوبة لقد تاب»","url":""}]},{"id":"s9-638","number":638,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"ما سرّ تقديم النبي ثم المهاجرين ثم الأنصار؟","answer":"قُدم النبي ﷺ لشرفه وقيادته، ثم المهاجرون لسبقهم، ثم الأنصار لنصرتهم؛ ترتيبًا للرتب مع شمول الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص444، تحت «سر تقديم المهاجرين على الأنصار في الذكر»","url":""}]},{"id":"s9-639","number":639,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"لماذا سميت الغزوة ﴿ساعة العسرة﴾ مع امتداد زمنها؟","answer":"الساعة هنا وقت العسرة، لا مقدار الساعة الاصطلاحي. ويذكر المصدر أنها تهوين لمدة الكرب وحث على الصبر؛ فزمن الشدة يسير إلى جانب ما يعقبه من الأجر. وإضافتها إلى العسرة تجمع ما وقع من شدة الحر وقلة الزاد والماء والظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص447، تحت «نكتة إضافة الساعة إلى العسرة»","url":""}]},{"id":"s9-640","number":640,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما كاد يزيغ قلوب فريق منهم﴾؟","answer":"﴿كاد﴾ تصور قرب بعضهم من الميل بسبب شدة العسرة، ثم أدركتهم التوبة والعناية قبل وقوع الزيغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص449، تحت «دلالة إسناد الزيغ إلى القلوب»","url":""}]},{"id":"s9-641","number":641,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"لماذا قيد مقاربة الزيغ بقوله: ﴿قلوب فريق منهم﴾؟","answer":"حتى لا يعمم هذا الوصف على المهاجرين والأنصار؛ فقد ثبت معظمهم مع شدة العسرة، وقاربت قلوب فريق منهم الميل بسببها. ففي القيد إنصاف لهم وإبراز لقوة إيمان من لم تؤثر الشدة في عزيمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص450، تحت «سر التعبير بالفريق قلوب فريق منهم»","url":""}]},{"id":"s9-642","number":642,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"لماذا كرر: ﴿ثم تاب عليهم﴾ بعد قوله: ﴿لقد تاب الله﴾؟","answer":"من توجيهات التكرار أن التوبة الأولى توفيق لهم إلى الرجوع، والثانية قبول وإثابة، وفيه تأكيد للعناية بهم. ومن أوجه ضمير عليهم أن يعود إلى الفريق الذي قاربت قلوبه الزيغ، كما يجوز عوده إلى المهاجرين والأنصار جميعًا؛ فلا يحصر التكرار في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص450، تحت «دلالة تكرار فعل التوبة»","url":""}]},{"id":"s9-643","number":643,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"لماذا ختم بـ﴿إنه بهم رؤوف رحيم﴾؟","answer":"الرأفة أبلغ الرحمة وألطفها، والرحمة أعم؛ فهما تفسران إنقاذهم من الزيغ وقبولهم بعد العسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص451، تحت «بلاغة الفصل إنه بهم رؤوف رحيم»","url":""}]},{"id":"s9-644","number":644,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"لماذا عطف ﴿وعلى الثلاثة الذين خلفوا﴾ دون ذكر أسمائهم؟","answer":"عطفوا على من تاب الله عليهم لتشريفهم بإدخالهم في حكم التوبة، وأعيد حرف الجر لتأكيد شمولها لهم بعد طول الفصل. أما ترك التصريح بأسمائهم فذكر المصدر أنهم كانوا معروفين، وفيه لطف بهم وستر لما ارتبط بقصتهم من تقصير وحزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص457، تحت «سر إعادة حرف الجر وعلى الثلاثة»","url":""}]},{"id":"s9-645","number":645,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿خُلّفوا﴾ بالبناء للمجهول، لا «تخلفوا»؟","answer":"﴿خُلّفوا﴾ يدل على أن أمرهم أُخّر عن قبول الآخرين، أو خلّفهم الحكم الإلهي، لا مجرد أنهم اختاروا التخلف عن الغزو.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص458، تحت «علة التعبير بالفعل الماضي المبني للمفعول»","url":""}]},{"id":"s9-646","number":646,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"ما الصورة في قوله: ﴿ضاقت عليهم الأرض بما رحبت﴾؟","answer":"تمثيل لشدة الكرب والوحشة: مع سعة الأرض لم يجدوا مكانًا يطمئنون إليه، فكأنها ضاقت حقيقة حولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص460، تحت «سر التعبير بالمجاز في ضاقت عليهم الأرض»","url":""}]},{"id":"s9-647","number":647,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"لماذا انتقل من ضيق الأرض إلى ﴿وضاقت عليهم أنفسهم﴾؟","answer":"ضيق الأرض خارجي، ثم بلغ الكرب باطنهم فلم تسعهم نفوسهم؛ فانتقل من إحاطة المكان إلى أشد ضيق نفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص462، تحت «دلالة العطف في وضاقت عليهم أنفسهم»","url":""}]},{"id":"s9-648","number":648,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿وظنوا أن لا ملجأ من الله إلا إليه﴾؟","answer":"علموا أنه لا مهرب من عقاب الله إلا بالرجوع إليه؛ فجمع التركيب الخوف منه واللجوء إليه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص466، تحت «دلالة إلا إليه»","url":""}]},{"id":"s9-649","number":649,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم تاب عليهم ليتوبوا﴾، وما وجه تقدم توبة الله عليهم على توبتهم؟","answer":"يبرز تقديم توبته عليهم فضل الله وامتنانه. ويذكر المصدر أن قبوله لهم يدعوهم إلى الثبات على التوبة والاستمرار فيها، وأنه لطف وهداية للرجوع إليه؛ فلا يلزم حصر ترتيب الجملة في توبة واحدة للعبد تسبقها توبة واحدة من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص470، تحت «سر تقديم توبة الله تعالى على توبة العباد»","url":""}]},{"id":"s9-650","number":650,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"لماذا ختم بـ﴿إن الله هو التواب الرحيم﴾ بضمير الفصل؟","answer":"ضمير الفصل يقصر كمال قبول التوبة والرحمة على الله، ويؤكد أنه كثير القبول لمن صدق مهما اشتد كربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص470، تحت «دلالة التذييل إن الله هو التواب الرحيم»","url":""}]},{"id":"s9-651","number":651,"surah":9,"verses":[119],"references":[{"surah":9,"verses":[119]}],"verseLabel":"التوبة: 119","question":"لماذا جاء بعد قصة الثلاثة الأمر: ﴿اتقوا الله وكونوا مع الصادقين﴾؟","answer":"قصة الثلاثة برهان على نجاة الصدق وهلاك الكذب؛ فجاء الأمر بالتقوى وملازمة الصادقين تعميمًا لعبرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص476، تحت «سر العدول عن خطاب الثلاثة إلى خطاب المؤمنين جميعًا»","url":""}]},{"id":"s9-652","number":652,"surah":9,"verses":[119],"references":[{"surah":9,"verses":[119]}],"verseLabel":"التوبة: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿مع الصادقين﴾ لا «من الصادقين»؟","answer":"﴿مع﴾ تأمر بملازمة جماعتهم ونصرتهم والسير في طريقهم، وفي ذلك معنى الصحبة العملية المستمرة، لا مجرد الانتساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص478، تحت «سر إيثار التعبير وكونوا مع الصادقين»","url":""}]},{"id":"s9-653","number":653,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله﴾؟","answer":"﴿ما كان﴾ تنفي استحقاق التخلف وتقرر أنه لا يليق بأهل المدينة ومن حولها مع قربهم وقدرة الرسول ﷺ بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص485، تحت «دلالة التعبير ومن حولهم من الأعراب»","url":""}]},{"id":"s9-654","number":654,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يرغبوا بأنفسهم عن نفسه﴾؟","answer":"لا ينبغي أن يطلبوا لأنفسهم الراحة معرضين عن نفس الرسول ﷺ؛ فحياته ونفسه أولى بالحفظ والبذل من أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص486، تحت «دلالة التعبير بقوله ولا يرغبوا بأنفسهم عن نفسه»","url":""}]},{"id":"s9-655","number":655,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما سرّ ترتيب الظمأ والنصب والمخمصة والموطئ والنيل من العدو؟","answer":"رتبت الآية مشاق الغزو وآثاره على نسق وقوعها: تعب الطريق وحاجاته، ثم دخول أرض العدو، ثم ما يناله المسلمون منه؛ فاستوعبت مراحل السعي التي يكتب الله بها العمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص500، تحت «براعة ترتيب الأحداث في الآية»","url":""}]},{"id":"s9-770","number":770,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما دلالة التعبير بقوله تعالى: ﴿ولا يطؤون موطئًا يغيظ الكفار﴾؟","answer":"يجمع اللفظ وطء المكان حقيقة وما يترتب عليه من إذلال العدو وقهره؛ فكل تقدم في أرضه يغيظه ويكتب للمؤمنين به عمل صالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص492، تحت «دلالة التعبير بيطؤون بين الحقيقة والاستعارة»","url":""}]},{"id":"s9-771","number":771,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما سرّ التعبير بالمصدر في قوله تعالى: ﴿ولا ينالون من عدو نيلًا﴾؟","answer":"جاء المصدر نكرة ليعم كل ما يصيبونه من العدو قليلًا أو كثيرًا، ماديًا أو معنويًا؛ فلا يضيع من أثر جهادهم شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص494، تحت «دلالة التعبير بالمصدر في نيلا»","url":""}]},{"id":"s9-656","number":656,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"لماذا تكرر ﴿ولا﴾ في تعداد المشاق؟","answer":"التكرار يجعل كل مشقة وعمل مستقلًا في إثبات الأجر، فلا يضيع واحد منها تابعًا لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص493، تحت «دلالة تتابع الجمل المنفية»","url":""}]},{"id":"s9-657","number":657,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا كتب لهم به عمل صالح﴾، فجعل المشقة نفسها عملًا؟","answer":"تفضل الله فأجرى ما ليس فعلًا اختياريًا كالظمأ والتعب مجرى العمل الصالح، لأنه نشأ عن مسيرهم في الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص496، تحت «دلالة التعبير بكتابة العمل الصالح دون قوله في كتب لهم»","url":""}]},{"id":"s9-658","number":658,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"لماذا ختم بـ﴿إن الله لا يضيع أجر المحسنين﴾؟","answer":"الخاتمة تضمن حفظ كل مشقة وعمل، وتسميهم محسنين لأنهم بذلوا طاقتهم في نصرة الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص498، تحت «سر الختم بقوله إن الله لا يضيع أجر المحسنين»","url":""}]},{"id":"s9-659","number":659,"surah":9,"verses":[120,121],"references":[{"surah":9,"verses":[120,121]}],"verseLabel":"التوبة: 120؛ التوبة: 121","question":"ما سرّ التعبير في قوله تعالى في الآية 120: ﴿إلا كتب لهم به عمل صالح﴾، ثم قال في الآية 121: ﴿إلا كتب لهم﴾ وحذف ﴿به عمل صالح﴾؟","answer":"الآية 120 جمعت مشاقًا ليست أفعالًا لهم مع أعمالهم، فأجراها الله مجرى العمل فقال ﴿به عمل صالح﴾؛ أما 121 فذكرت الإنفاق وقطع الوادي وهما من فعلهم، فاكتفى بـ﴿كتب لهم﴾ أي كتب نفس العمل وثوابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص508، تحت «بلاغة الحذف في إلا كتب لهم»","url":""}]},{"id":"s9-660","number":660,"surah":9,"verses":[121],"references":[{"surah":9,"verses":[121]}],"verseLabel":"التوبة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا ينفقون نفقة صغيرة ولا كبيرة﴾؟","answer":"قوبلت الصغيرة بالكبيرة لاستغراق كل نفقة مهما قل قدرها أو كثر، فلا يضيع منها شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص504، تحت «سر التنكير في المفعول به نفقة»","url":""}]},{"id":"s9-661","number":661,"surah":9,"verses":[121],"references":[{"surah":9,"verses":[121]}],"verseLabel":"التوبة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يقطعون واديًا إلا كتب لهم﴾؟","answer":"القطع في أصله فصل الشيء، واستعمل هنا في اجتياز الطريق والسير في الجهاد؛ فكأن السائر يفصل بمسيره قطعة من الأرض عن أخرى. وذكر الوادي يصور مراحل هذا السير، وكل ذلك محفوظ لهم بأجره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص506، تحت «سر العطف في ولا يقطعون واديًا إلا كتب لهم»","url":""}]},{"id":"s9-662","number":662,"surah":9,"verses":[121],"references":[{"surah":9,"verses":[121]}],"verseLabel":"التوبة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿ليجزيهم الله أحسن ما كانوا يعملون﴾، لا «بما كانوا يعملون»؟","answer":"يذكر المصدر وجهين: أن يجزيهم بأحسن أعمالهم، أو أن يجزيهم جزاءً هو أحسن من أعمالهم تفضلًا منه. فصيغة أحسن تبين كرم الجزاء، ولا تحصره في مقابلة حسابية مساوية للعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص508، تحت «دلالة اللام في ليجزيهم الله»","url":""}]},{"id":"s9-663","number":663,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان المؤمنون لينفروا كافة﴾ بعد الأمر السابق بالنفير؟","answer":"النفير العام لا يجب في كل حال؛ بل تتوزع وظائف الأمة بين الجهاد والتفقه، فلا يخلو الثغر ولا يخلو الناس من العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص514، تحت «سر المقابلة بين التحريضين على الغزو والعلم»","url":""}]},{"id":"s9-664","number":664,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿فلولا نفر من كل فرقة منهم طائفة﴾؟","answer":"لولا للتحضيض على النفير، وذكر طائفة من كل فرقة يبين حصول الكفاية بجماعة تتفقه وتنذر قومها. وفي توزيع النافرين على الفرق تعميم لنفع العلم، وقرب من قبول كل قوم لمن يعلمهم من بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص516، تحت «دلالة الفاء في فلولا نفر»","url":""}]},{"id":"s9-665","number":665,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"لماذا استعمل ﴿نفر﴾ لطالب العلم كما استعمله للجهاد؟","answer":"النفر يدل على الخروج بجد ونشاط لمهمة عظيمة؛ فطلب العلم جهاد يحتاج حركة وبذلًا كما يحتاجه القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص515، تحت «نكتة التعبير لينفروا في سياق طلب العلم بالفقه»","url":""}]},{"id":"s9-666","number":666,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿ليتفقهوا في الدين﴾ لا «ليتعلموا»؟","answer":"التفقه فهم عميق لأحكام الدين ومقاصده يجاوز جمع المعلومات، وهو الذي يؤهل صاحبه للإنذار والتعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص518، تحت «سر التعبير بصيغة التفعل»","url":""}]},{"id":"s9-667","number":667,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"ما سرّ تقديم التفقه على إنذار القوم؟","answer":"لا يصح الإنذار إلا بعد علم راسخ؛ فقدم إعداد المبلّغ بالتفقه على أثره في قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص519، تحت «دلالة الاقتصار على الإنذار وترك البشارة»","url":""}]},{"id":"s9-668","number":668,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"لماذا ختم بـ﴿لعلهم يحذرون﴾ لا «يعلمون»؟","answer":"غاية العلم أن يثمر حذرًا وامتثالًا، لا أن يبقى معرفة ذهنية؛ لذلك ختم بالأثر العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص520، تحت «دلالة الختم بأسلوب الإنشاء غير الطلبي»","url":""}]},{"id":"s9-669","number":669,"surah":9,"verses":[123],"references":[{"surah":9,"verses":[123]}],"verseLabel":"التوبة: 123","question":"لماذا أمر بقتال ﴿الذين يلونكم من الكفار﴾؟","answer":"البدء بالأقرب تنظيم للقتال ودفع للخطر المباشر، ثم ينتقل إلى من وراءه، وفيه حماية للحدود واستكمال للقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص530، تحت «دلالة استعمال يلونكم دون مرادفاتها»","url":""}]},{"id":"s9-670","number":670,"surah":9,"verses":[123],"references":[{"surah":9,"verses":[123]}],"verseLabel":"التوبة: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿وليجدوا فيكم غلظة﴾، فجعل الغلظة شيئًا يوجد؟","answer":"جعل الغلظة شيئًا يلقونه في المؤمنين لتظهر في الموقف والثبات بحيث يحسها العدو أثرًا واقعيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص533، تحت «سر إيثار صيغة الأمر باللام والفعل المضارع وليجدوا»","url":""}]},{"id":"s9-671","number":671,"surah":9,"verses":[123],"references":[{"surah":9,"verses":[123]}],"verseLabel":"التوبة: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿غلظة﴾ لا «قسوة»؟","answer":"الغلظة شدة وحزم في موضع القتال مع بقاء العدل، أما القسوة فغلظ القلب المذموم؛ فاختير اللفظ المنضبط بالمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص535، تحت «نكتة التعبير بلفظ غلظة»","url":""}]},{"id":"s9-673","number":673,"surah":9,"verses":[124],"references":[{"surah":9,"verses":[124]}],"verseLabel":"التوبة: 124","question":"ما دلالة قول المنافقين عند نزول السورة: ﴿أيكم زادته هذه إيمانًا﴾؟","answer":"قالوها استهزاءً وتشكيكًا في أثر الوحي، يسأل بعضهم بعضًا سؤال إنكار لا طلب هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص549، تحت «دلالة أي في سياق السؤال»","url":""}]},{"id":"s9-674","number":674,"surah":9,"verses":[124],"references":[{"surah":9,"verses":[124]}],"verseLabel":"التوبة: 124","question":"لماذا نُسبت زيادة الإيمان إلى السورة؟","answer":"لأن نزول السورة يمد المؤمن بعلم جديد من قصص وأحكام، ويقيم له دليلًا على توحيد الله ومعرفته، ويزيل شكًا أو شبهة؛ فهي سبب زيادة تصديقه ويقينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص549، تحت «نكتة استعمال مفردة الزيادة في الفعل زادته»","url":""}]},{"id":"s9-675","number":675,"surah":9,"verses":[124],"references":[{"surah":9,"verses":[124]}],"verseLabel":"التوبة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿فأما الذين آمنوا فزادتهم إيمانًا وهم يستبشرون﴾؟","answer":"جاء التفصيل ردًا على تشكيك المنافقين، فبين أثر السورة في المؤمنين. والفاء في ﴿فزادتهم﴾ تربط جواب أما وتبين تسبب تلقي القرآن في زيادة الإيمان، والجملة الحالية ﴿وهم يستبشرون﴾ تصور فرحهم المتجدد بنزول الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص552، تحت «معنى الفاء في لفظ فأما»","url":""}]},{"id":"s9-676","number":676,"surah":9,"verses":[125],"references":[{"surah":9,"verses":[125]}],"verseLabel":"التوبة: 125","question":"ما وجه اختلاف أثر السورة؛ فتزيد المؤمن إيمانًا وتزيد مريض القلب رجسًا؟","answer":"السورة سبب واحد، لكن المحل مختلف: المؤمن يقبلها فتزيد يقينه، والمريض يردها فتضيف كفرًا ونفاقًا إلى ما فيه؛ فالاختلاف في القلوب لا في الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص558، تحت «نكتة تعدية الزيادة إليهم لا إلى القلوب في سياق الآية الكريمة»","url":""}]},{"id":"s9-677","number":677,"surah":9,"verses":[125],"references":[{"surah":9,"verses":[125]}],"verseLabel":"التوبة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿فزادتهم رجسًا إلى رجسهم﴾؟","answer":"﴿إلى﴾ تصور انضمام رجس جديد إلى رجس سابق وتراكمه، فكل رد لآية يزيد مرض القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص559، تحت «بلاغة ذكر قيد إلى رجسهم»","url":""}]},{"id":"s9-678","number":678,"surah":9,"verses":[125],"references":[{"surah":9,"verses":[125]}],"verseLabel":"التوبة: 125","question":"لماذا ختم بـ﴿وماتوا وهم كافرون﴾؟","answer":"الخاتمة تبين نهاية التراكم: استمر رجسهم حتى خرجوا من الدنيا على الكفر من غير توبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص560، تحت «فن الازدواج بين وهم يستبشرون وماتوا وهم كافرون»","url":""}]},{"id":"s9-679","number":679,"surah":9,"verses":[126],"references":[{"surah":9,"verses":[126]}],"verseLabel":"التوبة: 126","question":"ما سرّ التعبير في قوله تعالى: ﴿أولا يرون أنهم يفتنون في كل عام مرة أو مرتين﴾؟","answer":"الاستفهام للتوبيخ على ترك الاعتبار بالابتلاء المتكرر، و﴿مرة أو مرتين﴾ يدل على أن الفرص تتجدد كل عام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص569، تحت «فائدة استعمال لفظ مرة أو مرتين»","url":""}]},{"id":"s9-680","number":680,"surah":9,"verses":[126],"references":[{"surah":9,"verses":[126]}],"verseLabel":"التوبة: 126","question":"ما دلالة بناء الفعل ﴿يفتنون﴾ للمفعول؟","answer":"يوجه البناء للمفعول الاهتمام إلى الفتنة ومقاصدها؛ أي ما يصيبهم من ابتلاء ينبههم إلى التوبة والاعتبار، دون الانشغال بذكر فاعل الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص566–567، تحت «فائدة بناء الفعل يفتنون للمفعول»","url":""}]},{"id":"s9-681","number":681,"surah":9,"verses":[126],"references":[{"surah":9,"verses":[126]}],"verseLabel":"التوبة: 126","question":"لماذا جمع بين ﴿لا يتوبون﴾ و﴿لا هم يذكرون﴾؟","answer":"نفت التوبة التي تصلح العمل، ونفت التذكر الذي يوقظ القلب ويفضي إليها؛ فجمع غياب الثمرة وسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص570، تحت «دلالة النفي بلا في دخوله على الفعل يتوبون»","url":""}]},{"id":"s9-682","number":682,"surah":9,"verses":[127],"references":[{"surah":9,"verses":[127]}],"verseLabel":"التوبة: 127","question":"لماذا نظر المنافقون بعضهم إلى بعض عند نزول السورة؟","answer":"تبادلوا النظر خفية يستأذنون بعضهم بعضًا في الانصراف ويتفقدون هل يراهم أحد، فكشفت النظرات تواطؤهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص576، تحت «سر التعبير بالفعل نظر»","url":""}]},{"id":"s9-683","number":683,"surah":9,"verses":[127],"references":[{"surah":9,"verses":[127]}],"verseLabel":"التوبة: 127","question":"ما دلالة استفهام المنافقين: ﴿هل يراكم من أحد﴾؟","answer":"استفهموا بالإشارة خوف افتضاح خروجهم؛ أي هل يراقبنا أحد من المؤمنين قبل أن ننصرف؟","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص578، تحت «علة فصل جملة هل يراكم من أحد»","url":""}]},{"id":"s9-684","number":684,"surah":9,"verses":[127],"references":[{"surah":9,"verses":[127]}],"verseLabel":"التوبة: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم انصرفوا صرف الله قلوبهم﴾؟","answer":"انصرفوا بأبدانهم عن مجلس الوحي، فجازاهم الله بصرف قلوبهم عن الهدى؛ جزاء من جنس فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص580، تحت «بلاغة الاستئناف البياني في ذكر صرف القلوب»","url":""}]},{"id":"s9-685","number":685,"surah":9,"verses":[127],"references":[{"surah":9,"verses":[127]}],"verseLabel":"التوبة: 127","question":"لماذا علل صرف القلوب بأنهم ﴿قوم لا يفقهون﴾؟","answer":"لأنهم لا يتدبرون الوحي ولا يتأملون مقاصده وما يؤول إليه إعراضهم، فعدم الفقه سبب لصرف قلوبهم. ونفي الفقه أبلغ هنا من نفي مجرد العلم؛ إذ المطلوب فهم يتبعه انتفاع وعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص584، تحت «نكتة إيثار نفي الفقه دون العلم أو العقل»","url":""}]},{"id":"s9-686","number":686,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد جاءكم رسول من أنفسكم﴾؟","answer":"اللام و﴿قد﴾ تؤكدان عظم المنة ووقوعها: جاءهم رسول قريب منهم، يعرفون نسبه وصدقه ولسانه وأحواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص589، تحت «فائدة التوكيد والتحقيق بلفظ لقد»","url":""}]},{"id":"s9-687","number":687,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"لماذا اختير ﴿من أنفسكم﴾ لا «منكم» فقط؟","answer":"﴿من أنفسكم﴾ أبلغ في شدة الاتصال، أي من جنسكم وخالص جماعتكم، فكأنه من نفسكم لا غريبًا عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص592، تحت «بلاغة استعمال قيد من أنفسكم»","url":""}]},{"id":"s9-688","number":688,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿عزيز عليه ما عنتم﴾؟","answer":"﴿عزيز عليه﴾ أي شديد شاق عليه ما يصيبهم من عنت ومشقة. والتعدية بـ﴿على﴾ تصور شدة ثقل معاناتهم عليه، فيظهر كمال شفقته بهم ورحمته لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص594، تحت «بلاغة تعدية عزيز بحرف الاستعلاء على»","url":""}]},{"id":"s9-689","number":689,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"ما بلاغة التعبير بقوله تعالى: ﴿حريص عليكم﴾؟","answer":"يصوّر شدة عنايته بهم ورعايته لأحوالهم وحرصه على إيمانهم ونجاتهم؛ حتى شُبّه حرصه عليهم بحرْص الشفيق على ما يخاف ضياعه، مبالغة في تعلقه بخيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص595–596، تحت «براعة استعمال مفردة حريص مع حرف الاستعلاء في السياق»","url":""}]},{"id":"s9-690","number":690,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"لماذا خص المؤمنين بقوله: ﴿بالمؤمنين رؤوف رحيم﴾ بعد عموم حرصه على الناس؟","answer":"حرصه عام في دعوة الناس، أما الرأفة والرحمة الخاصة النافعة فبالمؤمنين الذين قبلوا هديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص597، تحت «نكتة تقديم المتعلق على عامله»","url":""}]},{"id":"s9-691","number":691,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"ما سرّ تقديم ﴿رؤوف﴾ على ﴿رحيم﴾؟","answer":"الرأفة أشد الرحمة، فقدم الوصف الأقوى المناسب لحرصه على المؤمنين، ثم أتبعه بالرحمة الأعم؛ وفي ترتيب الوصفين تأكيد للشفقة وجمع بين الخاص والعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص598، تحت «بلاغة تقديم صفة رؤوف على صفة رحيم»","url":""}]},{"id":"s9-692","number":692,"surah":9,"verses":[129],"references":[{"surah":9,"verses":[129]}],"verseLabel":"التوبة: 129","question":"لماذا انتقل من وصف رحمة الرسول إلى قوله: ﴿فإن تولوا فقل حسبي الله﴾؟","answer":"بعد بيان بلوغ شفقته أقصى مدى، سلاه إن أعرضوا بأن الله كافيه؛ فعليه البلاغ لا حملهم على الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص604، تحت «غرض الأمر فقل حسبي الله في السياق»","url":""}]},{"id":"s9-693","number":693,"surah":9,"verses":[129],"references":[{"surah":9,"verses":[129]}],"verseLabel":"التوبة: 129","question":"ما بلاغة الانتقال من الغيبة في ﴿فإن تولوا﴾ إلى خطاب النبي ﷺ في ﴿فقل حسبي الله﴾؟","answer":"يوجه الخطاب إلى النبي ﷺ ليثبت على الاستعانة بالله وتفويض الأمر إليه بعد إعراضهم؛ وفي الأمر طمأنة له بأن الله كافيه، فلا يضره توليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص604، تحت «بلاغة الالتفات من الغيبة إلى الخصوص»","url":""}]},{"id":"s9-694","number":694,"surah":9,"verses":[129],"references":[{"surah":9,"verses":[129]}],"verseLabel":"التوبة: 129","question":"ما مناسبة إتباع الكفاية بالتوحيد في قوله تعالى: ﴿لا إله إلا هو﴾؟","answer":"الجملة استئناف يقرر وحدانية الله ويعلل كفايته: فهو يكفي رسوله ﷺ لأنه لا معبود بحق ولا مدبر للأمر سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص605، تحت «علة الفصل في لا إله إلا هو»","url":""}]},{"id":"s9-695","number":695,"surah":9,"verses":[129],"references":[{"surah":9,"verses":[129]}],"verseLabel":"التوبة: 129","question":"ما سرّ تقديم الجار والمجرور في قوله تعالى: ﴿عليه توكلت﴾؟","answer":"تقديم ﴿عليه﴾ للاختصاص؛ أي لا أفوض أمري ولا أعتمد إلا على الله، فالتوكل عبادة لا تصرف لسواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص606، تحت «سر تقديم الجار والمجرور عليه»","url":""}]},{"id":"s9-696","number":696,"surah":9,"verses":[129],"references":[{"surah":9,"verses":[129]}],"verseLabel":"التوبة: 129","question":"ما مناسبة ختام السورة بقوله تعالى: ﴿وهو رب العرش العظيم﴾؟","answer":"الخاتمة ثناء على عظيم قدرة الله وتعليل للكفاية والتوكل؛ فمن كان رب العرش، أعظم المخلوقات، فهو قادر على نصرة رسوله ﷺ وكفايته ممن تولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص608، تحت «سر ختم السورة برب العرش العظيم»","url":""}]},{"id":"s10-156","number":156,"surah":10,"verses":[1],"references":[{"surah":10,"verses":[1]}],"verseLabel":"يونس: 1","question":"ما سرّ التعبير باسم الإشارة للبعيد في ﴿تلك آيات الكتاب﴾، مع أن الآيات قريبة تُتلى وتُسمع؟","answer":"الإشارة بالبعيد ترفع منزلة الآيات في نفس السامع؛ فهي قريبة في تلاوتها، عالية في قدرها ومعانيها. فالبعد هنا يصور علو الرتبة، ويهيئ القارئ لتلقي كلام جليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص621، تحت «علة إيثار اسم الإشارة ﴿تلك﴾»","url":""}]},{"id":"s10-157","number":157,"surah":10,"verses":[1],"references":[{"surah":10,"verses":[1]}],"verseLabel":"يونس: 1","question":"ما دلالة وصف الكتاب بـ﴿الحكيم﴾؟","answer":"يحتمل الوصف الإحكام والإتقان، واشتمال الكتاب على الحكمة، وكونه حاكمًا على الكتب وبالحلال والحرام؛ فجمع لفظ واحد هذه المعاني المتقاربة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص624، تحت «وجه إيثار الوصف بـ﴿الحكيم﴾»","url":""}]},{"id":"s10-158","number":158,"surah":10,"verses":[2],"references":[{"surah":10,"verses":[2]}],"verseLabel":"يونس: 2","question":"ما سرّ تعميم الإنذار وتخصيص البشارة في قوله: ﴿أن أنذر الناس وبشر الذين آمنوا﴾؟","answer":"الإنذار ينبه الجميع إلى ما يجب اجتنابه وعاقبة مخالفته، أما البشارة بالجزاء الحسن فلمن آمن واستجاب. فاختلاف المفعولين يميز بين عموم التحذير وخصوص الوعد لمن تحقق فيه سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص637، تحت «سر تغاير مفعولي الإنذار والتبشير»","url":""}]},{"id":"s10-159","number":159,"surah":10,"verses":[2],"references":[{"surah":10,"verses":[2]}],"verseLabel":"يونس: 2","question":"ما دلالة إضافة ﴿القدم﴾ إلى ﴿الصدق﴾ في قوله تعالى: ﴿قدم صدق عند ربهم﴾؟","answer":"تفيد الإضافة أن سابقة المؤمنين ومنزلتهم عند الله ثابتة في الحق والخير، خالصة من الزيف؛ فليست منزلة مدعاة، بل قدم موصوفة بالصدق والثبوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص639، تحت «فائدة إضافة (القدم) إلى (الصدق)»","url":""}]},{"id":"s10-175","number":175,"surah":10,"verses":[2],"references":[{"surah":10,"verses":[2]}],"verseLabel":"يونس: 2","question":"ما الصورة البلاغية في قوله تعالى: ﴿قدم صدق عند ربهم﴾؟","answer":"كنّى بالقدم عن العمل الصالح السابق والمنزلة المتقدمة، ويجوز حملها على الاستعارة؛ لأن القدم آلة التقدم والثبات، فأطلقت على ما يتقدم به المؤمن إلى كرامة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص640، تحت «﴿قدم صدق﴾ بين الاستعارة، والكناية»","url":""}]},{"id":"s10-160","number":160,"surah":10,"verses":[3],"references":[{"surah":10,"verses":[3]}],"verseLabel":"يونس: 3","question":"ما سرّ تكرار لفظ الربوبية في قوله تعالى: ﴿إن ربكم الله﴾ ثم ﴿ذلكم الله ربكم﴾؟","answer":"كرر لفظ الربوبية لزيادة التقرير والتذكير، وللتنبيه إلى أن من خلق العالم ودبره وربّى عباده هو وحده المستحق للعبادة؛ ولذلك تفرع عنه الأمر: ﴿فاعبدوه﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص664، تحت «تكرار لفظ الربوبية»","url":""}]},{"id":"s10-161","number":161,"surah":10,"verses":[4],"references":[{"surah":10,"verses":[4]}],"verseLabel":"يونس: 4","question":"ما سرّ التعبير بـ﴿يبدأ الخلق ثم يعيده﴾ دون ذكر الموت بين البداية والإعادة؟","answer":"لأن الإعادة تدل على ما سبقها من حياة ثم موت، فاستُغني بالمذكور عن المحذوف. وبذلك اتصل طرفا الحجة مباشرة: من أنشأ الخلق أول مرة قادر على إعادته، وهو المقصود في الرد على منكري البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص676، تحت «بلاغة الإضمار في: ﴿إنه يبدأ الخلق﴾»","url":""}]},{"id":"s10-162","number":162,"surah":10,"verses":[5],"references":[{"surah":10,"verses":[5]}],"verseLabel":"يونس: 5","question":"ما سرّ التعبير عن الشمس بـ﴿ضياء﴾ وعن القمر بـ﴿نورًا﴾؟","answer":"الضياء يدل هنا على الإشراق القوي الساطع، أما النور فأعم، ويناسب ضوء القمر الألطف. فاختلاف اللفظين يصور اختلاف أثرهما الذي نراه، وما في كل منهما من منفعة ملائمة للنهار أو الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص688، تحت «سر نسبة الضياء إلى الشمس، والنور إلى القمر»","url":""}]},{"id":"s10-163","number":163,"surah":10,"verses":[5,6],"references":[{"surah":10,"verses":[5,6]}],"verseLabel":"يونس: 5، 6","question":"ما سرّ ختم آية الشمس والقمر بـ﴿لقوم يعلمون﴾، والتي بعدها بـ﴿لقوم يتقون﴾؟","answer":"العلم يفتح باب فهم الدلائل وإدراك إحكامها، والتقوى تحمل صاحبها على الاعتبار بها والحذر من مخالفة خالقها. فتنوع الخاتمتين يبرز جانبين من الانتفاع بالآيات: بصيرة تفهم، وقلب يستجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص707، تحت «بيان التشابه بين ﴿لقوم يعلمون﴾، و﴿لقوم يتقون﴾»","url":""}]},{"id":"s10-164","number":164,"surah":10,"verses":[7],"references":[{"surah":10,"verses":[7]}],"verseLabel":"يونس: 7","question":"ما سر تقديم ﴿رَضُوا بِالْحَيَاةِ الدُّنْيَا﴾ على ﴿وَاطْمَأَنُّوا بِهَا﴾؟","answer":"يوجه المصدر الترتيب بأنه تقديم للنتيجة على علتها؛ إذ سكونهم إلى الدنيا واطمئنانهم بها حملهم على الرضا بها. ويحتمل أن تكون الواو للحال: رضوا بها حال كونهم مطمئنين إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص716، تحت «بلاغة تقديم الرضا على الطمأنينة»","url":""}]},{"id":"s10-165","number":165,"surah":10,"verses":[8],"references":[{"surah":10,"verses":[8]}],"verseLabel":"يونس: 8","question":"ما سرّ التعبير بـ﴿بما كانوا يكسبون﴾ دون «بما كسبوا»؟","answer":"اجتماع ﴿كانوا﴾ مع المضارع يصور الكسب السيئ عادة متكررة استمروا عليها، لا فعلًا عابرًا انقضى. فنسبت الآية العاقبة إلى طريق سلكوه وأصروا عليه من الكفر والغفلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص721، تحت «فائدة ذكر ﴿كانوا﴾»","url":""}]},{"id":"s10-166","number":166,"surah":10,"verses":[9],"references":[{"surah":10,"verses":[9]}],"verseLabel":"يونس: 9","question":"ما دلالة التعبير بالمضارع في قوله تعالى: ﴿يهديهم ربهم﴾؟","answer":"يدل المضارع على أن هداية الله لهم متجددة مستمرة، تثبتهم على الإيمان وترقيهم في مراتب الكمال، وليست هداية عابرة انتهت.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص728، تحت «بلاغة الإخبار بالجملة الفعلية المضارعية»","url":""}]},{"id":"s10-176","number":176,"surah":10,"verses":[9],"references":[{"surah":10,"verses":[9]}],"verseLabel":"يونس: 9","question":"ما معنى الباء في قوله تعالى: ﴿يهديهم ربهم بإيمانهم﴾؟","answer":"الباء للتعليل والسببية؛ فإيمانهم سبب لهداية الله المتتابعة لهم، وفي التعبير تأكيد لارتباط الجزاء بأصل الإيمان الصادق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص729، تحت «معنى الباء في: ﴿بإيمانهم﴾»","url":""}]},{"id":"s10-167","number":167,"surah":10,"verses":[9],"references":[{"surah":10,"verses":[9]}],"verseLabel":"يونس: 9","question":"لماذا قُدّم ﴿مِنْ تَحْتِهِمْ﴾ على ﴿الْأَنْهَارُ﴾ في قوله: ﴿تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهَارُ﴾؟","answer":"قُدّم اهتمامًا وتخصيصًا لإظهار النعمة على أهل الجنة؛ فجريان الأنهار من تحتهم يبرز أنها مهيأة لمنفعتهم وسقايتهم ولذتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص732، تحت «فائدة تقديم الجار والمجرور: ﴿من تحتهم﴾»","url":""}]},{"id":"s10-168","number":168,"surah":10,"verses":[10],"references":[{"surah":10,"verses":[10]}],"verseLabel":"يونس: 10","question":"ما دلالة التعبير بـ﴿دعواهم﴾ في قوله: ﴿دعواهم فيها سبحانك اللهم﴾، مع أن المذكور تسبيح وثناء؟","answer":"الدعوى هنا قولهم وثناؤهم على الله، لا مجرد طلب حاجة؛ فقد غمرهم النعيم، فكانت مناجاتهم تسبيحًا وتنزيهًا وتعظيمًا، وثناءً مقصودًا لذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص738، تحت «نكتة إيثار لفظ الدعوى»","url":""}]},{"id":"s10-169","number":169,"surah":10,"verses":[10],"references":[{"surah":10,"verses":[10]}],"verseLabel":"يونس: 10","question":"ما سرّ افتتاح كلام أهل الجنة بالتسبيح وختمه بالحمد؟","answer":"التسبيح تنزيه لله عن النقص، والحمد ثناء عليه لكماله ونعمه. فجمع التعبير بين تعظيم المنعم وشكر إنعامه، وجعل الحمد خاتمة تلائم ما يشاهدونه من تمام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص742، تحت «بلاغة الترتيب بين الجمل المتعاطفة»","url":""}]},{"id":"s10-170","number":170,"surah":10,"verses":[11],"references":[{"surah":10,"verses":[11]}],"verseLabel":"يونس: 11","question":"ما دلالة ذكر ﴿استعجالهم بالخير﴾ في سياق الحديث عن تعجيل الشر؟","answer":"اتخذت الآية حرص الإنسان على سرعة مجيء الخير مقياسًا يوضح خطورة طلب الشر: لو عُجّل له ما يدعو به من سوء بتلك السرعة لهلك. فالمقابلة تكشف رحمة الله في الإمهال، وإن استعجل الإنسان ما يضره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص753، تحت «بلاغة التشبيه: ﴿استعجالهم بالخير﴾»","url":""}]},{"id":"s10-171","number":171,"surah":10,"verses":[12],"references":[{"surah":10,"verses":[12]},{"surah":3,"verses":[191]}],"verseLabel":"يونس: 12؛ آل عمران: 191","question":"ما سرّ اختلاف ترتيب الأحوال بين ﴿لجنبه أو قاعدًا أو قائمًا﴾ في يونس، و﴿قيامًا وقعودًا وعلى جنوبهم﴾ في آل عمران؟","answer":"في يونس مشهد ضر ومرض، فبدأ بالمضطجع، وهو غالبًا أشد عجزًا، ثم القاعد فالقائم. وفي آل عمران مشهد ذكر في أحوال العافية، فبدأ بالقيام. فاختلاف الترتيب يراعي الحال التي يصورها كل سياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص767–768، تحت «توجيه المتشابه اللفظي في ترتيب أحوال الداعين في الصحة والمرض»","url":""}]},{"id":"s10-172","number":172,"surah":10,"verses":[12],"references":[{"surah":10,"verses":[12]}],"verseLabel":"يونس: 12","question":"ما دلالة التعبير بـ﴿مر﴾ في قوله تعالى: ﴿مر كأن لم يدعنا إلى ضر مسه﴾؟","answer":"يصوّر الفعل أنه مضى على عادته الأولى فور كشف الضر، فلم يقف للشكر ولم يلتفت إلى دعائه السابق؛ فكلمة ﴿مر﴾ ترسم سرعة الجحود والانصراف عن مقام الابتهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص771، تحت «براعة التعبير بالفعل ﴿مر﴾ جوابًا لـ﴿فلما﴾»","url":""}]},{"id":"s10-173","number":173,"surah":10,"verses":[13],"references":[{"surah":10,"verses":[13]}],"verseLabel":"يونس: 13","question":"ما دلالة استعمال ﴿كانوا﴾ في قوله تعالى: ﴿وما كانوا ليؤمنوا﴾؟","answer":"تفيد أن التكذيب والظلم تمكنا منهم وصارا عادة مستمرة؛ فجاء نفي الإيمان وصفًا لحال رسخت بأعمالهم واختيارهم، لا لموقف عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص787، تحت «دلالة استعمال: ﴿كانوا﴾»","url":""}]},{"id":"s10-177","number":177,"surah":10,"verses":[13],"references":[{"surah":10,"verses":[13]}],"verseLabel":"يونس: 13","question":"ما دلالة اللام في قوله تعالى: ﴿وما كانوا ليؤمنوا﴾؟","answer":"هي لام الجحود، تؤكد نفي الإيمان وتبالغ فيه؛ أي بلغ إصرارهم على الكفر حدًّا صار معه رجوعهم إلى الإيمان أمرًا ميؤوسًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص788، تحت «دلالة اللام في: ﴿ليؤمنوا﴾»","url":""}]},{"id":"s10-174","number":174,"surah":10,"verses":[14],"references":[{"surah":10,"verses":[14]}],"verseLabel":"يونس: 14","question":"ما دلالة قوله: ﴿لننظر كيف تعملون﴾ مع إحاطة علم الله بأعمال العباد قبل وقوعها؟","answer":"المقصود ظهور العمل في الواقع الذي يقع عليه الجزاء، لا اكتساب علم لم يكن. فالله يعلم ما سيعملون، ثم يُمهلون ويُمكَّنون حتى يصدر منهم العمل نفسه، فتقوم عليهم الحجة بما فعلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص796، تحت «سر التعبير بالنظر: ﴿لننظر﴾»","url":""}]},{"id":"s10-1","number":1,"surah":10,"verses":[15],"references":[{"surah":10,"verses":[15]}],"verseLabel":"يونس: 15","question":"لماذا طلبوا: ﴿ائت بقرآن غير هذا أو بدله﴾؟","answer":"أرادوا قرآنًا يوافق أهواءهم ولا يذم أصنامهم ولا ينذرهم بالبعث والجزاء؛ فكان طلبهم تغييرًا لمضمون الرسالة، وفيه تعنت ومحاولة للطعن في كون القرآن وحيًا من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص22، تحت «الغرض من طلبهم تغيير القرآن»","url":""}]},{"id":"s10-2","number":2,"surah":10,"verses":[15],"references":[{"surah":10,"verses":[15]}],"verseLabel":"يونس: 15","question":"ما دلالة قول النبي: ﴿ما يكون لي أن أبدله من تلقاء نفسي﴾؟","answer":"نفى أن يملك تبديله من عند نفسه لأن القرآن وحي يتبع فيه ما يوحى إليه؛ فليس الرسول ﷺ منشئًا للنص حتى يغيره استجابة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص27، تحت «دلالة النفي في ما يكون لي»","url":""}]},{"id":"s10-3","number":3,"surah":10,"verses":[15],"references":[{"surah":10,"verses":[15]}],"verseLabel":"يونس: 15","question":"لماذا ختم بقوله: ﴿إني أخاف إن عصيت ربي عذاب يوم عظيم﴾؟","answer":"ختم بالخوف من العذاب لبيان أن تبديل الوحي معصية عظيمة لا يقدم عليها الرسول ﷺ، وفيه رد عملي على طلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص32، تحت «الموقع البياني للجملة إني أخاف»","url":""}]},{"id":"s10-4","number":4,"surah":10,"verses":[16],"references":[{"surah":10,"verses":[16]}],"verseLabel":"يونس: 16","question":"لماذا احتج عليهم بقوله: ﴿فقد لبثت فيكم عمرًا من قبله﴾؟","answer":"عاش بينهم زمنًا طويلًا قبل الوحي يعرفون صدقه وأمانته ولم يقل شعرًا أو يتعاط تأليفًا؛ فكيف ينسبون إليه فجأة اختلاق القرآن؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص52، تحت «براعة الاستدلال فقد لبثت فيكم عمرا من قبله»","url":""}]},{"id":"s10-5","number":5,"surah":10,"verses":[16],"references":[{"surah":10,"verses":[16]}],"verseLabel":"يونس: 16","question":"لماذا ختم الحجة بقوله: ﴿أفلا تعقلون﴾؟","answer":"العقل كاف في وصل مقدمات الحجة بنتيجتها: من عرفوا سيرته وأميته وطول مكثه بينهم ينبغي أن يدركوا أن القرآن ليس من عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص53، تحت «دلالة التعبير بالاستفهام والفاء والنفي في أفلا تعقلون»","url":""}]},{"id":"s10-6","number":6,"surah":10,"verses":[17],"references":[{"surah":10,"verses":[17]}],"verseLabel":"يونس: 17","question":"لماذا جمع بين ﴿افترى على الله كذبًا﴾ و﴿كذب بآياته﴾؟","answer":"الأول إنشاء للكذب ونسبته إلى الله، والثاني رد للآيات الصادقة بعد مجيئها؛ فجمع طرفي الجريمة: اختلاق الباطل وإنكار الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص64، تحت «الفرق الدلالي بين كذبا وكذب»","url":""}]},{"id":"s10-7","number":7,"surah":10,"verses":[17],"references":[{"surah":10,"verses":[17]}],"verseLabel":"يونس: 17","question":"لماذا ختم بـ﴿إنه لا يفلح المجرمون﴾؟","answer":"المجرم لا يبلغ مطلوبه ولا ينجو من عاقبته؛ والخاتمة قاعدة تشمل المفترين والمكذبين وتقطع دعوى فلاحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص65، تحت «بلاغة التذييل في إنه لا يفلح المجرمون»","url":""}]},{"id":"s10-8","number":8,"surah":10,"verses":[18],"references":[{"surah":10,"verses":[18]}],"verseLabel":"يونس: 18","question":"كيف يكشف قول المشركين: ﴿هؤلاء شفعاؤنا عند الله﴾ تناقض عبادتهم للأصنام؟","answer":"زعموا للأصنام منزلة الشفاعة ليقربوها من مقام العبادة، مع أنها لا تملك ضرًا ولا نفعًا. فجمع النظم بين عجزها ودعواهم الشفاعة لها ليكشف بطلان حجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص73، تحت «المعنى الإجمالي»","url":""}]},{"id":"s10-9","number":9,"surah":10,"verses":[18],"references":[{"surah":10,"verses":[18]}],"verseLabel":"يونس: 18","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أتنبئون الله﴾؟","answer":"الاستفهام للإنكار والتهكم؛ إذ لا يصح أن يخبر المشركون الله بشفعاء مزعومين في ملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص82، تحت «دلالة أسلوب الاستفهام في أتنبئون»","url":""}]},{"id":"s10-178","number":178,"surah":10,"verses":[18],"references":[{"surah":10,"verses":[18]}],"verseLabel":"يونس: 18","question":"ما دلالة قوله تعالى: ﴿بما لا يعلم﴾؟","answer":"ما لا يعلمه الله مستحيل الوجود؛ فالعبارة تنفي وجود الشفعاء الذين زعموهم نفيًا قاطعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص84، تحت «دلالة النفي بما لا يعلم»","url":""}]},{"id":"s10-10","number":10,"surah":10,"verses":[19],"references":[{"surah":10,"verses":[19]}],"verseLabel":"يونس: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿كان الناس أمة واحدة فاختلفوا﴾؟","answer":"كان الناس على أصل التوحيد أو جماعة واحدة ثم طرأ الاختلاف؛ فالنظم يقرر أن التفرق في الدين عارض لا أصل في الفطرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص95، تحت «علة ذكر الاختلاف بعد الوحدة»","url":""}]},{"id":"s10-11","number":11,"surah":10,"verses":[19],"references":[{"surah":10,"verses":[19]}],"verseLabel":"يونس: 19","question":"لماذا أُخّر الفصل بينهم بسبب ﴿كلمة سبقت من ربك﴾؟","answer":"الكلمة السابقة هي تأخير الفصل التام إلى أجل القيامة؛ ولولا هذا القضاء لعوجلوا بالحكم والعقوبة عند اختلافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص97، تحت «دلالة التعبير بالجملة الشرطية في ولولا»","url":""}]},{"id":"s10-12","number":12,"surah":10,"verses":[20],"references":[{"surah":10,"verses":[20]}],"verseLabel":"يونس: 20","question":"ما دلالة قولهم: ﴿لولا أنزل عليه آية من ربه﴾ مع كثرة الآيات؟","answer":"أرادوا آية حسية مقترحة توافق تعنتهم، مع أن القرآن والآيات القائمة كافية؛ فليس طلبهم بحثًا عن دليل بل مراوغة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص110، تحت «توجيه لفظ آية»","url":""}]},{"id":"s10-13","number":13,"surah":10,"verses":[20],"references":[{"surah":10,"verses":[20]}],"verseLabel":"يونس: 20","question":"لماذا جاء الأمر في قوله تعالى: ﴿فانتظروا﴾؟","answer":"جاء الأمر للتهديد: انتظروا حكم الله وعاقبة التكذيب، فستظهر الحقيقة التي جحدتموها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص114، تحت «علة ورود فعل الأمر في فانتظروا»","url":""}]},{"id":"s10-179","number":179,"surah":10,"verses":[20],"references":[{"surah":10,"verses":[20]}],"verseLabel":"يونس: 20","question":"ما دلالة قوله تعالى: ﴿إني معكم من المنتظرين﴾؟","answer":"فيه تحدٍّ وطمأنينة إلى وعد الله؛ فالرسول ﷺ ينتظر معهم ما يقضي الله به، لكن العاقبة ستكون على المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص116، تحت «دلالة المعية في إني معكم»","url":""}]},{"id":"s10-14","number":14,"surah":10,"verses":[21],"references":[{"surah":10,"verses":[21]}],"verseLabel":"يونس: 21","question":"ما بلاغة التعبير بالإذاقة في قوله تعالى: ﴿وإذا أذقنا الناس رحمة﴾؟","answer":"تصوّر الإذاقة الرحمة أمرًا محسوس الأثر يباشرونه ويجدون نفعه، فكان الواجب أن يقابلوها بالشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص123، تحت «بلاغة الاستعارة في التعبير بالإذاقة في وإذا أذقنا»","url":""}]},{"id":"s10-180","number":180,"surah":10,"verses":[21],"references":[{"surah":10,"verses":[21]}],"verseLabel":"يونس: 21","question":"ما بلاغة التعبير بالمس في قوله تعالى: ﴿من بعد ضراء مستهم﴾؟","answer":"يصوّر المس الضر قد باشرهم وأصابهم إصابة محسوسة، ثم كشفه الله عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص126، تحت «بلاغة الاستعارة في التعبير بالمس في مستهم»","url":""}]},{"id":"s10-15","number":15,"surah":10,"verses":[21],"references":[{"surah":10,"verses":[21]}],"verseLabel":"يونس: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا لهم مكر في آياتنا﴾؟","answer":"﴿إذا﴾ الفجائية تصور مبادرتهم إلى الطعن والتكذيب فور الرحمة، بدل الشكر الذي يقتضيه المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص126، تحت «نكتة دخول إذا على جواب الشرط»","url":""}]},{"id":"s10-16","number":16,"surah":10,"verses":[21],"references":[{"surah":10,"verses":[21]}],"verseLabel":"يونس: 21","question":"لماذا سُمّيت مجازاة الله للمشركين على مكرهم مكرًا في قوله: ﴿الله أسرع مكرًا﴾؟","answer":"جاء اللفظ على المشاكلة؛ فمكر الله بهم هو إبطال تدبيرهم ومجازاتهم عليه من حيث لا يشعرون، لا المكر المذموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص130، تحت «بلاغة المشاكلة»","url":""}]},{"id":"s10-181","number":181,"surah":10,"verses":[21],"references":[{"surah":10,"verses":[21]}],"verseLabel":"يونس: 21","question":"ما دلالة اسم التفضيل ﴿أسرع﴾ في قوله تعالى: ﴿الله أسرع مكرًا﴾؟","answer":"يدل على أن تدبيرهم لا يسبق إحاطة الله ولا يفلت من مجازاته؛ فجزاء مكرهم أسرع نفاذًا من حيلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص130، تحت «فائدة اسم التفضيل في أسرع»","url":""}]},{"id":"s10-17","number":17,"surah":10,"verses":[22],"references":[{"surah":10,"verses":[22]}],"verseLabel":"يونس: 22","question":"ما سر الانتقال من الخطاب في ﴿كنتم في الفلك﴾ إلى الغيبة في ﴿وجرين بهم﴾؟","answer":"ينقل الالتفات حالهم من خطاب النعمة إلى حكاية مشهدهم للسامع؛ ليتعجب من تقلبهم بين الإخلاص عند الخوف والبغي بعد النجاة. وفي الغيبة هنا أيضًا إعراض عنهم وتبعيد لهم حين انكشف جحودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص141، تحت «فائدة الالتفات بالضمائر من الخطاب إلى الغيبة وجرين بهم»","url":""}]},{"id":"s10-18","number":18,"surah":10,"verses":[22],"references":[{"surah":10,"verses":[22]}],"verseLabel":"يونس: 22","question":"لماذا وُصفت الريح في قوله تعالى: ﴿بريح طيبة﴾ بأنها طيبة؟","answer":"لأنها توافق سير السفن برفق وتلائم حال الأمن والفرح الذي كان فيه ركابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص150، تحت «غرض وصف الريح بأنها طيبة»","url":""}]},{"id":"s10-182","number":182,"surah":10,"verses":[22],"references":[{"surah":10,"verses":[22]}],"verseLabel":"يونس: 22","question":"لماذا وُصفت الريح في قوله تعالى: ﴿جاءتها ريح عاصف﴾ بأنها عاصف؟","answer":"لتصوير شدتها وخطرها حين قلبت حال الركاب من الأمن والفرح إلى الخوف من الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص152، تحت «غرض وصف الريح بأنها عاصف»","url":""}]},{"id":"s10-19","number":19,"surah":10,"verses":[22],"references":[{"surah":10,"verses":[22]}],"verseLabel":"يونس: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿وظنوا أنهم أحيط بهم﴾؟","answer":"﴿أحيط بهم﴾ تصور الخطر محاصرًا من كل جانب حتى انقطعت أسباب النجاة، فعندها أخلصوا الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص156، تحت «بلاغة الاستعارة في التعبير بالإحاطة في أحيط بهم»","url":""}]},{"id":"s10-20","number":20,"surah":10,"verses":[23],"references":[{"surah":10,"verses":[23]}],"verseLabel":"يونس: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما أنجاهم إذا هم يبغون﴾؟","answer":"الفجاءة في ﴿إذا هم يبغون﴾ تكشف سرعة نقضهم عهد الإخلاص؛ فما إن تحققت النجاة حتى عادوا إلى الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص167، تحت «دلالة دخول إذا في جواب لما»","url":""}]},{"id":"s10-21","number":21,"surah":10,"verses":[23],"references":[{"surah":10,"verses":[23]}],"verseLabel":"يونس: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما بغيكم على أنفسكم﴾؟","answer":"قصر أثر البغي عليهم؛ فضرره وعقوبته راجعان إلى صاحبه، ولا يضر الله ولا يعجزه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص174، تحت «بلاغة أسلوب القصر بإنما»","url":""}]},{"id":"s10-22","number":22,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"لماذا شُبّهت الحياة الدنيا بمشهد الماء والنبات الذي يزدهر ثم يزول؟","answer":"التشبيه للمشهد كله: يبدأ النبات بالماء، ثم يزدهر وتتعلق به الآمال، ثم يزول سريعًا. وهكذا متاع الدنيا؛ يبهج صاحبه ويغره امتداده ثم ينقضي، فالصورة تكشف قصره وسرعة تحوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص189، تحت «بلاغة التشبيه المركب»","url":""}]},{"id":"s10-23","number":23,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿أخذت الأرض زخرفها وازينت﴾؟","answer":"صوّرت الأرض كأنها امرأة اكتست زينتها حتى بلغت غاية الحسن؛ فاشتد تعلق أهلها بها واغترارهم بنضرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص197، تحت «بلاغة الاستعارة في تزين الأرض»","url":""}]},{"id":"s10-183","number":183,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"ما دلالة الجملة الاسمية في قوله تعالى: ﴿وظن أهلها أنهم قادرون عليها﴾؟","answer":"تصوّر الجملة رسوخ ظنهم بالتمكن من ثمرها واستقرار اطمئنانهم إليها؛ فعند تمام الاغترار جاء أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص198، تحت «نكتة التعبير بالجملة الاسمية أنهم قادرون عليها»","url":""}]},{"id":"s10-24","number":24,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"ما بلاغة التعبير في قوله تعالى: ﴿فجعلناها حصيدًا﴾؟","answer":"صوّر النبات بعد هلاكه حصيدًا مقطوعًا مستأصلًا، بعد أن كان ناميًا مزدهرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص200، تحت «بلاغة المجاز والاستعارة في فجعلناها حصيدا»","url":""}]},{"id":"s10-184","number":184,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"ما فائدة التشبيه في قوله تعالى: ﴿كأن لم تغن﴾؟","answer":"يبالغ التشبيه في تصوير سرعة زوال بهجة الأرض حتى كأنها لم تعمر ولم تنعم من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص200، تحت «معنى كأن وفائدة التشبيه»","url":""}]},{"id":"s10-185","number":185,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"ما دلالة التعريف في قوله تعالى: ﴿بالأمس﴾؟","answer":"يشير إلى الماضي القريب المعلوم، فيبرز شدة سرعة التحول من النضرة إلى الفناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص201، تحت «معنى أل في بالأمس»","url":""}]},{"id":"s10-25","number":25,"surah":10,"verses":[25],"references":[{"surah":10,"verses":[25]}],"verseLabel":"يونس: 25","question":"لماذا جاءت ﴿والله يدعو إلى دار السلام﴾ بعد مثل الدنيا الزائلة؟","answer":"بعد صورة الدار الزائلة جاء النداء إلى دار السلام الباقية؛ فالمقابلة تنقل القلب من الاغترار بالدنيا إلى اختيار الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص207، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s10-26","number":26,"surah":10,"verses":[25],"references":[{"surah":10,"verses":[25]}],"verseLabel":"يونس: 25","question":"لماذا أضاف الجنة إلى ﴿السلام﴾؟","answer":"هي دار السلامة من الموت والحزن والآفات، أو دار الله السلام؛ فالإضافة تجمع الأمان وكرامة القرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص210، تحت «نكتة تخصيص اسم الله السلام»","url":""}]},{"id":"s10-27","number":27,"surah":10,"verses":[26],"references":[{"surah":10,"verses":[26]}],"verseLabel":"يونس: 26","question":"ما سرّ التعبير بـ﴿الحسنى﴾ في قوله تعالى: ﴿للذين أحسنوا الحسنى﴾؟","answer":"﴿الحسنى﴾ هي المثوبة البالغة غاية الحسن، وأعظمها الجنة؛ فجاء اللفظ مناسبًا لإحسانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص219، تحت «سر التعبير بالحسنى»","url":""}]},{"id":"s10-186","number":186,"surah":10,"verses":[26],"references":[{"surah":10,"verses":[26]}],"verseLabel":"يونس: 26","question":"ما معنى ﴿زيادة﴾ في قوله تعالى: ﴿وزيادة﴾، وما وجه التعبير بها؟","answer":"هي فضل زائد على الجزاء المستحق، وأعظمه النظر إلى وجه الله؛ فثواب المحسنين إحسان وزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص221، تحت «بيان معنى الزيادة في وزيادة ووجه التعبير بها»","url":""}]},{"id":"s10-28","number":28,"surah":10,"verses":[26],"references":[{"surah":10,"verses":[26]}],"verseLabel":"يونس: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يرهق وجوههم قتر ولا ذلة﴾؟","answer":"الرهق غشيان يغطي الوجوه، فنفى عنها سواد الكآبة والذل معًا؛ فظهر الأمن والكرامة على سيمائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص225، تحت «سر عطف الذلة على القتر»","url":""}]},{"id":"s10-29","number":29,"surah":10,"verses":[27],"references":[{"surah":10,"verses":[27]}],"verseLabel":"يونس: 27","question":"ما سرّ التعبير في قوله تعالى في السيئة: ﴿جزاء سيئة بمثلها﴾، دون أن يقال مثل ما قال في الحسنة: «وزيادة»؟","answer":"العدل يقتضي أن السيئة لا تضاعف بل تجازى بمثلها، أما الحسنة فتزاد فضلًا؛ فافترق مقام العدل عن مقام الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص242، تحت «وجه المقابلة بين ذكر عمال الحسنات وعمال السيئات»","url":""}]},{"id":"s10-30","number":30,"surah":10,"verses":[27],"references":[{"surah":10,"verses":[27]}],"verseLabel":"يونس: 27","question":"لماذا شُبهت وجوههم بقطع من الليل مظلمًا؟","answer":"صورت الظلمة تغطي وجوههم قطعًا متراكمة من ليل شديد الإظلام؛ فجمعت السواد والخوف والمهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص246، تحت «بلاغة التشبيه والاستعارة»","url":""}]},{"id":"s10-31","number":31,"surah":10,"verses":[28],"references":[{"surah":10,"verses":[28]}],"verseLabel":"يونس: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿مكانكم أنتم وشركاؤكم﴾ يوم الحشر؟","answer":"اسم الفعل ﴿مكانكم﴾ يأمرهم بالثبات في موضعهم هم وشركاؤهم للحساب، وفيه زجر يمنع الفرار واختلاط الصفوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص260، تحت «وجه التعبير بمكانكم وإضافته»","url":""}]},{"id":"s10-32","number":32,"surah":10,"verses":[28],"references":[{"surah":10,"verses":[28]}],"verseLabel":"يونس: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿فزيلنا بينهم﴾؟","answer":"﴿زيلنا﴾ أي فرقنا وميزنا بينهم بعد اجتماعهم في الدنيا على العبادة؛ فبانت براءة المعبودين وبطلان الصلة المزعومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص263، تحت «إيثار لفظ زيلنا»","url":""}]},{"id":"s10-33","number":33,"surah":10,"verses":[29],"references":[{"surah":10,"verses":[29]}],"verseLabel":"يونس: 29","question":"ما دلالة قول الشركاء: ﴿فكفى بالله شهيدًا بيننا وبينكم﴾؟","answer":"استشهدوا بالله لأنه المحيط بحقيقة الحال، وليكذبوا دعوى العابدين أن عبادتهم كانت بعلمهم ورضاهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص273، تحت «توجيه التعبير بلفظ كفى»","url":""}]},{"id":"s10-34","number":34,"surah":10,"verses":[29],"references":[{"surah":10,"verses":[29]}],"verseLabel":"يونس: 29","question":"ما دلالة قولهم: ﴿إن كنا عن عبادتكم لغافلين﴾؟","answer":"الغفلة هنا نفي العلم والرضا بعبادتهم؛ فالمعبودون الباطلون لم يشعروا بها أو لم يقروها، فلا تقوم شفاعة مزعومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص278، تحت «سر التعبير عن الغفلة باسم الفاعل مجموعا»","url":""}]},{"id":"s10-35","number":35,"surah":10,"verses":[30],"references":[{"surah":10,"verses":[30]}],"verseLabel":"يونس: 30","question":"ما دلالة اسم الإشارة ﴿هنالك﴾ في قوله: ﴿هنالك تبلو كل نفس ما أسلفت﴾؟","answer":"يشير ﴿هنالك﴾ إلى مقام الحساب المهول الذي تنكشف فيه حقائق الأعمال وعواقبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص284، تحت «وجه التعبير باسم الإشارة هنالك»","url":""}]},{"id":"s10-187","number":187,"surah":10,"verses":[30],"references":[{"surah":10,"verses":[30]}],"verseLabel":"يونس: 30","question":"ما بلاغة الكناية في قوله تعالى: ﴿تبلو كل نفس ما أسلفت﴾؟","answer":"كني بالفعل ﴿تبلو﴾ عن اختبار النفس لما قدمت ومعرفة حقيقته وعاقبته؛ فيتميز لها نفع عملها من ضرره.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص286، تحت «بلاغة الكناية»","url":""}]},{"id":"s10-36","number":36,"surah":10,"verses":[30],"references":[{"surah":10,"verses":[30]}],"verseLabel":"يونس: 30","question":"لماذا وصف الله بأنه ﴿مولاهم الحق﴾ عند رد الخلق إليه؟","answer":"لأنه الولي الحق الذي ظهرت ولايته وانفرادُه بالحكم بعد سقوط كل ولاية مدعاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص290، تحت «نكتة الوصف بمولاهم الحق»","url":""}]},{"id":"s10-188","number":188,"surah":10,"verses":[30],"references":[{"surah":10,"verses":[30]}],"verseLabel":"يونس: 30","question":"ما دلالة قوله تعالى: ﴿وضل عنهم ما كانوا يفترون﴾؟","answer":"صوّر ما افتروه من آلهة وشفاعة كشيء غاب عنهم وفقدوه عند الحاجة، فانقطعت الصلة المزعومة وبطل نفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص291، تحت «وجه تعدية الضلال بعن»","url":""}]},{"id":"s10-37","number":37,"surah":10,"verses":[31],"references":[{"surah":10,"verses":[31]}],"verseLabel":"يونس: 31","question":"لماذا تتابعت الأسئلة: من يرزق؟ ومن يملك السمع والأبصار؟ ومن يخرج الحي؟ ومن يدبر الأمر؟","answer":"جمعت الأسئلة أصول النعمة والقدرة: الرزق، والحواس، وإخراج الحي والميت، ثم عُمّم ذلك بتدبير الأمر كله؛ لتلزمهم بأن المدبر الواحد هو المستحق للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص299، تحت «بلاغة حشد الاستفهامات»","url":""}]},{"id":"s10-38","number":38,"surah":10,"verses":[31],"references":[{"surah":10,"verses":[31]}],"verseLabel":"يونس: 31","question":"لماذا أعقب إقرارهم بأن الله يدبر الأمر بقوله: ﴿فقل أفلا تتقون﴾؟","answer":"بعد إقرارهم بربوبيته جاء سؤال التقوى: إذا كان هو الفاعل وحده، أفلا تتقون الشرك وتفردونه بالعبادة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص315، تحت «توجيه التعبير بالاستفهام في أفلا»","url":""}]},{"id":"s10-39","number":39,"surah":10,"verses":[32],"references":[{"surah":10,"verses":[32]}],"verseLabel":"يونس: 32","question":"ما بلاغة اسم الإشارة في قوله تعالى: ﴿فذلكم الله ربكم الحق﴾؟","answer":"يعقب اسم الإشارة اعترافهم بأفعال الربوبية ليعين الله الموصوف بتلك الأفعال، ويقرر أنه ربهم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص321، تحت «بلاغة استخدام اسم الإشارة فذلكم»","url":""}]},{"id":"s10-189","number":189,"surah":10,"verses":[32],"references":[{"surah":10,"verses":[32]}],"verseLabel":"يونس: 32","question":"ما دلالة القصر في قوله تعالى: ﴿فماذا بعد الحق إلا الضلال﴾؟","answer":"يقصر ما يجاوز الحق على الضلال، فينفي وجود منزلة وسطى بين توحيد الله والانصراف عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص327، تحت «وجه القصر»","url":""}]},{"id":"s10-40","number":40,"surah":10,"verses":[32],"references":[{"surah":10,"verses":[32]}],"verseLabel":"يونس: 32","question":"لماذا ختم بقوله: ﴿فأنى تصرفون﴾؟","answer":"الاستفهام للتعجب والتوبيخ: من أي جهة يصرفون عن الحق الواضح بعد أن أقرت به ألسنتهم؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص328، تحت «بلاغة الاستفهام بأنى»","url":""}]},{"id":"s10-41","number":41,"surah":10,"verses":[33],"references":[{"surah":10,"verses":[33]}],"verseLabel":"يونس: 33","question":"ما بلاغة التشبيه في قوله تعالى: ﴿كذلك حقت كلمة ربك﴾؟","answer":"كما ثبت انصرافهم عن الحق ثبت عليهم قضاء الله بعدم الإيمان لإصرارهم، فجاء الجزاء موافقا لاختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص334، تحت «بلاغة التشبيه في كذلك حقت»","url":""}]},{"id":"s10-190","number":190,"surah":10,"verses":[33],"references":[{"surah":10,"verses":[33]}],"verseLabel":"يونس: 33","question":"لماذا وصف من حقت عليهم الكلمة بأنهم ﴿فسقوا﴾؟","answer":"لأن الفسق خروج متعمد عن طاعة الله وحدوده، فبيّن الوصف سبب استحقاقهم الحكم بعد إصرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص340، تحت «نكتة التعبير بالفسق»","url":""}]},{"id":"s10-42","number":42,"surah":10,"verses":[34],"references":[{"surah":10,"verses":[34]}],"verseLabel":"يونس: 34","question":"لماذا جُدّد سؤال بدء الخلق وإعادته في قوله تعالى: ﴿هل من شركائكم من يبدأ الخلق ثم يعيده﴾؟","answer":"جاء السؤال بعد محاجة المشركين في شركائهم ليطالبهم بدليل على أن واحدًا منها يقدر على بدء الخلق أو إعادته؛ فلما عجزوا ثبت أن الله وحده هو الفاعل المستحق للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص342، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s10-191","number":191,"surah":10,"verses":[34],"references":[{"surah":10,"verses":[34]}],"verseLabel":"يونس: 34","question":"ما دلالة استئناف قوله تعالى في أول سورة يونس: ﴿إنه يبدأ الخلق ثم يعيده﴾؟","answer":"استؤنفت الجملة لتقرير قدرة الله على بدء الخلق وإعادته أصلًا من أصول العقيدة، وتعليل الرجوع إليه والجزاء بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص674، تحت «دلالة جملة الاستئناف إنه يبدأ الخلق»","url":""}]},{"id":"s10-43","number":43,"surah":10,"verses":[34],"references":[{"surah":10,"verses":[34]}],"verseLabel":"يونس: 34","question":"لماذا ختم بـ﴿فأنى تؤفكون﴾؟","answer":"﴿تؤفكون﴾ أي تصرفون بالكذب عن الحق؛ والاستفهام يعجب من انقلابهم عن إقرارهم بعجز الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص348، تحت «الغرض من التعبير بالاستفهام المجازي في فأنى تؤفكون»","url":""}]},{"id":"s10-44","number":44,"surah":10,"verses":[35],"references":[{"surah":10,"verses":[35]}],"verseLabel":"يونس: 35","question":"لماذا سأل: ﴿هل من شركائكم من يهدي إلى الحق﴾ ثم قال: ﴿قل الله يهدي للحق﴾؟","answer":"السؤال يكشف عجز الشركاء حتى عن الهداية، ثم يثبت أن الله وحده يهدي إلى الحق؛ فكيف يعبد العاجز ويترك الهادي؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص352، تحت «الجواب الملقن ودلالته»","url":""}]},{"id":"s10-45","number":45,"surah":10,"verses":[35],"references":[{"surah":10,"verses":[35]}],"verseLabel":"يونس: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿أفمن يهدي إلى الحق أحق أن يتبع أمن لا يهدي إلا أن يهدى﴾؟","answer":"المقابلة تقيم برهان الأحقية بالاتباع: الله يهدي بذاته، والشريك لا يهتدي فضلا عن أن يهدي إلا إذا هداه غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص357، تحت «سر الفرق بين نفي الاهتداء مع أن السياق لنفي الهداية»","url":""}]},{"id":"s10-46","number":46,"surah":10,"verses":[36],"references":[{"surah":10,"verses":[36]}],"verseLabel":"يونس: 36","question":"ما دلالة القصر في قوله تعالى: ﴿وما يتبع أكثرهم إلا ظنا﴾؟","answer":"يقصر مستند أكثرهم على الظن والتقليد من غير علم، فيبطل بناء العقيدة على التوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص362، تحت «الغرض من التعبير بأسلوب القصر»","url":""}]},{"id":"s10-192","number":192,"surah":10,"verses":[36],"references":[{"surah":10,"verses":[36]}],"verseLabel":"يونس: 36","question":"لماذا قصر اتباع الظن على ﴿أكثرهم﴾ ولم يعمهم جميعا؟","answer":"لأن منهم من عرف الحق فعاند، ولأن بعضهم سيؤمن؛ فلا يستوي الجميع في حقيقة حالهم ومآلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص363، تحت «سر قصر الحكم على أكثرهم»","url":""}]},{"id":"s10-47","number":47,"surah":10,"verses":[36],"references":[{"surah":10,"verses":[36]}],"verseLabel":"يونس: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الظن لا يغني من الحق شيئا﴾؟","answer":"الظن لا يقوم مقام اليقين ولا يدفع شيئا من الحق الثابت؛ فبطل أن تبنى العقيدة على توهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص363، تحت «موقع جملة إن الظن ودلالته»","url":""}]},{"id":"s10-48","number":48,"surah":10,"verses":[37],"references":[{"surah":10,"verses":[37]}],"verseLabel":"يونس: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان هذا القرآن أن يفترى من دون الله﴾؟","answer":"﴿ما كان﴾ تنفي إمكان افترائه نفيا يناسب منزلته ونظمه وموافقته للوحي؛ فلا يليق أن يكون صادرا من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص369، تحت «سر استخدام أسلوب النفي على وجه الجحود»","url":""}]},{"id":"s10-49","number":49,"surah":10,"verses":[37],"references":[{"surah":10,"verses":[37]}],"verseLabel":"يونس: 37","question":"لماذا جمع بين ﴿تصديق الذي بين يديه﴾ و﴿تفصيل الكتاب﴾؟","answer":"تصديقه يثبت اتصال الوحي ووحدة أصله، وتفصيله يبين ما يحتاج إليه من العقائد والأحكام؛ فجمع الشهادة لما قبله والبيان لأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص374، تحت «دلالة عطف التفصيل على التصديق»","url":""}]},{"id":"s10-50","number":50,"surah":10,"verses":[38],"references":[{"surah":10,"verses":[38]}],"verseLabel":"يونس: 38","question":"لماذا تحداهم هنا بالإتيان ﴿بسورة مثله﴾؟","answer":"لما زعموا أن محمدا ﷺ افتراه تحداهم بأقل وحدة مستقلة من جنسه، سورة واحدة، مع دعوة كل من يستطيعون؛ فعجزهم حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص382، تحت «الغرض من التنكير في بسورة»","url":""}]},{"id":"s10-51","number":51,"surah":10,"verses":[39],"references":[{"surah":10,"verses":[39]}],"verseLabel":"يونس: 39","question":"ما دلالة قوله تعالى: ﴿بل كذبوا بما لم يحيطوا بعلمه﴾؟","answer":"ذمهم لأنهم بادروا إلى التكذيب قبل تدبر معاني القرآن ومعرفة حججه، فكان إنكارهم صادرا من غير علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص390، تحت «نكتة التعبير بما لم يحيطوا بعلمه»","url":""}]},{"id":"s10-193","number":193,"surah":10,"verses":[39],"references":[{"surah":10,"verses":[39]}],"verseLabel":"يونس: 39","question":"ما سر إيثار ﴿لما﴾ في قوله تعالى: ﴿ولما يأتهم تأويله﴾؟","answer":"تفيد أن تأويل ما أخبر به القرآن لم يأتهم إلى ذلك الوقت مع توقع مجيئه، وفيه إشعار بأن الوقائع ستصدق أخباره.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص391، تحت «سر التعبير بلما وإيثاره»","url":""}]},{"id":"s10-52","number":52,"surah":10,"verses":[40],"references":[{"surah":10,"verses":[40]}],"verseLabel":"يونس: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم من يؤمن به ومنهم من لا يؤمن به﴾؟","answer":"التقسيم يستوعب مآلهم: منهم من سيؤمن أو يصدق باطنا، ومنهم من يصر؛ والله يعلم حقيقة الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص400، تحت «دلالة الترتيب في تقسيم الناس»","url":""}]},{"id":"s10-53","number":53,"surah":10,"verses":[40],"references":[{"surah":10,"verses":[40]}],"verseLabel":"يونس: 40","question":"ما دلالة التذييل بقوله: ﴿وربك أعلم بالمفسدين﴾؟","answer":"فيه وعيد للمصرين على التكذيب، وتقرير أن الله يعلم حقيقة أحوالهم وما يستحقونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص400، تحت «الغرض البلاغي من التذييل بالاعتراض»","url":""}]},{"id":"s10-194","number":194,"surah":10,"verses":[40],"references":[{"surah":10,"verses":[40]}],"verseLabel":"يونس: 40","question":"ما دلالة التعريف في لفظ ﴿المفسدين﴾؟","answer":"يفيد جنس المفسدين ويشمل أصناف الإفساد، فلا يقتصر الوعيد على صورة واحدة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص401، تحت «معنى أل في المفسدين»","url":""}]},{"id":"s10-54","number":54,"surah":10,"verses":[41],"references":[{"surah":10,"verses":[41]}],"verseLabel":"يونس: 41","question":"ما دلالة اللام في قوله تعالى: ﴿لي عملي ولكم عملكم﴾؟","answer":"تختص اللام كل فريق بعمله وجزائه، فلا يحمل الرسول ﷺ عملهم ولا يحملون عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص405، تحت «نكتة التعبير باللام في لي ولكم»","url":""}]},{"id":"s10-195","number":195,"surah":10,"verses":[41],"references":[{"surah":10,"verses":[41]}],"verseLabel":"يونس: 41","question":"لماذا أتبع قوله: ﴿لي عملي ولكم عملكم﴾ بالتصريح بالبراءة؟","answer":"أكدت جملتا البراءة المفاصلة بعد قيام الحجة: لا يؤاخذون بعمل الرسول ﷺ ولا يؤاخذ بعملهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص406، تحت «نكتة فصل أنتم بريئون ودلالته»","url":""}]},{"id":"s10-55","number":55,"surah":10,"verses":[42],"references":[{"surah":10,"verses":[42]}],"verseLabel":"يونس: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم من يستمعون إليك أفأنت تسمع الصم ولو كانوا لا يعقلون﴾؟","answer":"سماع الصوت بلا عقل للحق بمنزلة الصمم؛ والاستفهام ينفي قدرة الرسول ﷺ على إسماع هداية لمن عطل أدوات الفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص412، تحت «الغرض من التعبير بالاستعارة الصم»","url":""}]},{"id":"s10-56","number":56,"surah":10,"verses":[43],"references":[{"surah":10,"verses":[43]}],"verseLabel":"يونس: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم من ينظر إليك أفأنت تهدي العمي ولو كانوا لا يبصرون﴾؟","answer":"النظر الظاهر لا ينفع مع عمى البصيرة؛ فلا يملك الرسول ﷺ أن يهدي من اختار ألا يبصر الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص421، تحت «بلاغة الاستعارة العمي»","url":""}]},{"id":"s10-57","number":57,"surah":10,"verses":[44],"references":[{"surah":10,"verses":[44]}],"verseLabel":"يونس: 44","question":"ما دلالة تنكير ﴿شيئا﴾ في قوله تعالى: ﴿إن الله لا يظلم الناس شيئا﴾؟","answer":"يفيد نفي أدنى قدر من الظلم عن الله نفيا شاملا، فلا ينقص أحدا شيئا من حقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص429، تحت «بلاغة تنكير شيئا»","url":""}]},{"id":"s10-196","number":196,"surah":10,"verses":[44],"references":[{"surah":10,"verses":[44]}],"verseLabel":"يونس: 44","question":"ما دلالة تقديم ﴿أنفسهم﴾ في قوله تعالى: ﴿ولكن الناس أنفسهم يظلمون﴾؟","answer":"يبين التقديم أن ضرر الكفر راجع إليهم وأنهم المتسببون في ظلم أنفسهم، لا أن الله ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص430، تحت «نكتة تقديم المفعول الأول أنفسهم»","url":""}]},{"id":"s10-58","number":58,"surah":10,"verses":[45],"references":[{"surah":10,"verses":[45]}],"verseLabel":"يونس: 45","question":"لماذا يبدو لهم يوم الحشر أنهم لم يلبثوا إلا ساعة من النهار؟","answer":"صوّر قصر مقامهم في الدنيا، أو في القبور على تفسير آخر، كأنه ساعة من النهار إذا قيس بما يستقبلونه من الآخرة. وفي تقليل المدة تحسير لهم على ما فرطوا فيه وإبطال لاغترارهم بطول اللبث.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص441، تحت «نكتة تنكير ساعة»","url":""}]},{"id":"s10-59","number":59,"surah":10,"verses":[46],"references":[{"surah":10,"verses":[46]}],"verseLabel":"يونس: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿وإما نرينك بعض الذي نعدهم أو نتوفينك فإلينا مرجعهم﴾؟","answer":"سواء رأى الرسول ﷺ بعض الوعيد في حياته أو توفاه الله قبله، فمرجعهم إليه والحساب واقع؛ فلا يتعلق صدق الوعد بمشاهدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص456، تحت «دلالة مجيء جواب واحد لجملتي الشرط»","url":""}]},{"id":"s10-60","number":60,"surah":10,"verses":[47],"references":[{"surah":10,"verses":[47]}],"verseLabel":"يونس: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكل أمة رسول فإذا جاء رسولهم قضي بينهم بالقسط﴾؟","answer":"لكل أمة رسول يقيم الحجة، فإذا جاء يوم الفصل قضى بينهم بالعدل؛ فلا عقوبة بلا رسالة ولا محاباة في الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص465، تحت «دلالة جملة الجواب قضي بينهم بالقسط»","url":""}]},{"id":"s10-61","number":61,"surah":10,"verses":[48,49],"references":[{"surah":10,"verses":[48,49]}],"verseLabel":"يونس: 48–49","question":"لماذا سألوا: ﴿متى هذا الوعد﴾ فأجيبوا بأن الرسول لا يملك لنفسه ضرًا ولا نفعًا؟","answer":"لأن سؤالهم كان استعجالًا للوعيد استهزاءً، فجاء الجواب بأن توقيت العذاب ليس إلى الرسول؛ فهو عبد لا يملك الضر والنفع حتى لنفسه، وإنما الأمر كله لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص475، تحت «علة الفصل قل لا أملك»","url":""}]},{"id":"s10-63","number":63,"surah":10,"verses":[50,51],"references":[{"surah":10,"verses":[50,51]}],"verseLabel":"يونس: 50–51","question":"ما علة فصل قوله تعالى: ﴿أثم إذا ما وقع آمنتم به﴾ عما قبله؟","answer":"جاءت الجملة مستأنفة جوابًا عن استعجالهم العذاب، تنكر عليهم تأخير الإيمان حتى وقوعه حين لا ينفع التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص494، تحت «علة الفصل أثم إذا ما وقع آمنتم به»","url":""}]},{"id":"s10-197","number":197,"surah":10,"verses":[50,51],"references":[{"surah":10,"verses":[50,51]}],"verseLabel":"يونس: 50–51","question":"ما غرض الاستفهام في قوله تعالى: ﴿آلآن﴾؟","answer":"هو استفهام إنكاري توبيخي يرد طلب قبول الإيمان بعد وقوع العذاب، لأن زمن الاختيار قد فات.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص496، تحت «غرض الاستفهام ونوعه»","url":""}]},{"id":"s10-64","number":64,"surah":10,"verses":[52],"references":[{"surah":10,"verses":[52]}],"verseLabel":"يونس: 52","question":"ما بلاغة التعبير عن الإحساس بالعذاب بقوله: ﴿ذوقوا﴾؟","answer":"استعير الذوق لمباشرة العذاب وإدراك ألمه إدراكًا محسوسًا، فصوّر شدة اتصاله بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص503، تحت «بلاغة المجاز في التعبير عن الإحساس بالعذاب بتذوقه»","url":""}]},{"id":"s10-198","number":198,"surah":10,"verses":[52],"references":[{"surah":10,"verses":[52]}],"verseLabel":"يونس: 52","question":"ما نكتة إضافة العذاب إلى الخلد في قوله: ﴿عذاب الخلد﴾؟","answer":"تدل الإضافة على أن العذاب ملازم للخلود دائم لا ينقطع، وليس تجربة عابرة تزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص503، تحت «نكتة إضافة العذاب إلى الخلد»","url":""}]},{"id":"s10-65","number":65,"surah":10,"verses":[53],"references":[{"surah":10,"verses":[53]}],"verseLabel":"يونس: 53","question":"لماذا أُمر النبي أن يقسم: ﴿إي وربي إنه لحق﴾؟","answer":"جاء الجواب مفصولًا مستأنفًا ومؤكدًا بالقسم لمواجهة إنكارهم للبعث، فقرر أن الوعد حق لا ريب فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص512، تحت «علة الفصل قل إي وربي»","url":""}]},{"id":"s10-66","number":66,"surah":10,"verses":[54],"references":[{"surah":10,"verses":[54]}],"verseLabel":"يونس: 54","question":"ما دلالة قوله تعالى: ﴿لافتدت به﴾ في تصوير موقف النفس الظالمة يوم القيامة؟","answer":"تصور المفردة أن النفس، لو ملكت جميع ما في الأرض، لبذلته كله فداءً من العذاب؛ وفي ذلك تهويل للموقف وإسقاط لقيمة الدنيا عند معاينة الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص526، تحت «دلالة مفردة الافتداء في لافتدت به»","url":""}]},{"id":"s10-67","number":67,"surah":10,"verses":[54],"references":[{"surah":10,"verses":[54]}],"verseLabel":"يونس: 54","question":"ما سرّ إيثار ﴿أسروا﴾ في قوله تعالى: ﴿وأسروا الندامة لما رأوا العذاب﴾؟","answer":"يصور اللفظ شدة الندم الذي استقر في نفوسهم عند معاينة العذاب؛ فقيل إنهم كتموه من شدة البهت، وقيل أظهروه، واللفظ يحتمل الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص527، تحت «نكتة إيثار فعل أسروا»","url":""}]},{"id":"s10-68","number":68,"surah":10,"verses":[55],"references":[{"surah":10,"verses":[55]}],"verseLabel":"يونس: 55","question":"لماذا كرر ﴿ألا﴾ في: ﴿ألا إن لله ما في السماوات والأرض ألا إن وعد الله حق﴾؟","answer":"أعيد حرف التنبيه لأن كل جملة تقرر حقيقة عظيمة مستقلة: ملك الله التام، وصدق وعده؛ فاستحق كل خبر تنبيهًا جديدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص542، تحت «نكتة إعادة حرف التنبيه»","url":""}]},{"id":"s10-69","number":69,"surah":10,"verses":[56],"references":[{"surah":10,"verses":[56]}],"verseLabel":"يونس: 56","question":"ما بلاغة ترتيب قوله تعالى: ﴿هو يحيي ويميت وإليه ترجعون﴾؟","answer":"رتبت الآية أطوار الخلق والمصير: الإحياء ثم الإماتة ثم الرجوع إلى الله، فجمعت بدء الحياة ونهايتها والبعث للحساب في نسق موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص549، تحت «بلاغة الترتيب»","url":""}]},{"id":"s10-70","number":70,"surah":10,"verses":[57],"references":[{"surah":10,"verses":[57]}],"verseLabel":"يونس: 57","question":"لماذا وصف القرآن بأنه ﴿موعظة﴾ و﴿شفاء﴾ و﴿هدى﴾ و﴿رحمة﴾ بهذا الترتيب؟","answer":"رتبت الأوصاف من إزالة الشر إلى تحصيل الخير: الموعظة تزجر، والشفاء يزيل أمراض القلب، والهدى يدل على الطريق، والرحمة ثمرة ذلك كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص561، تحت «العطف بالواو وسر ترتيب المعطوفات»","url":""}]},{"id":"s10-71","number":71,"surah":10,"verses":[57],"references":[{"surah":10,"verses":[57]}],"verseLabel":"يونس: 57","question":"ما الغرض من وصف القرآن بأنه ﴿شفاء﴾؟","answer":"استعير الشفاء لإزالة القرآن أمراض القلوب من الشك والاعتقاد الفاسد والخلق المذموم، كما يزيل الدواء مرض البدن.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص563، تحت «الغرض من التعبير بالاستعارة وشفاء»","url":""}]},{"id":"s10-199","number":199,"surah":10,"verses":[57],"references":[{"surah":10,"verses":[57]}],"verseLabel":"يونس: 57","question":"لماذا خُصت الصدور بالذكر في قوله: ﴿شفاء لما في الصدور﴾؟","answer":"خُصت لأنها موضع القلوب ومستودع الاعتقاد والخواطر؛ فالتعبير يصور تمكن الداء الباطن وكمال علاج القرآن له.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص565، تحت «فائدة تخصيص الصدور بالذكر»","url":""}]},{"id":"s10-72","number":72,"surah":10,"verses":[58],"references":[{"surah":10,"verses":[58]}],"verseLabel":"يونس: 58","question":"ما غرض تقديم ﴿بفضل الله وبرحمته﴾ في الآية؟","answer":"يفيد الاهتمام والحصر؛ فالفضل والرحمة هما السبب الحق الذي ينبغي أن يكون به الفرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص572، تحت «غرض تقديم الجار والمجرور»","url":""}]},{"id":"s10-200","number":200,"surah":10,"verses":[58],"references":[{"surah":10,"verses":[58]}],"verseLabel":"يونس: 58","question":"ما معنى الفاء في قوله: ﴿فبذلك فليفرحوا﴾؟","answer":"الأولى تفريع للفرح على فضل الله ورحمته، والثانية رابطة لجواب الأمر، فتؤكد اتصال الفرح بسببه الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص574، تحت «معنى الفاء في فبذلك وفليفرحوا»","url":""}]},{"id":"s10-201","number":201,"surah":10,"verses":[58],"references":[{"surah":10,"verses":[58]}],"verseLabel":"يونس: 58","question":"لماذا أشير إلى فضل الله ورحمته باسم الإشارة للبعيد في قوله: ﴿فبذلك﴾؟","answer":"استعمل اسم الإشارة للبعيد لتعظيم المشار إليه ورفع منزلته، أي بهذا الفضل العظيم والرحمة الجليلة فليفرحوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص575، تحت «الغرض من التعبير باسم الإشارة للبعيد»","url":""}]},{"id":"s10-73","number":73,"surah":10,"verses":[58],"references":[{"surah":10,"verses":[58]}],"verseLabel":"يونس: 58","question":"لماذا قيل: ﴿هو خير مما يجمعون﴾ لا «مما يملكون»؟","answer":"الفعل المضارع يصور تجدد جمع متاع الدنيا واستمرار الحرص عليه، ثم يقرر أن فضل الله ورحمته خير من كل ما يتجدد جمعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص580، تحت «بلاغة التعبير بالفعل المضارع في مما يجمعون»","url":""}]},{"id":"s10-74","number":74,"surah":10,"verses":[59],"references":[{"surah":10,"verses":[59]}],"verseLabel":"يونس: 59","question":"ما نكتة التعبير بالإنزال في قوله: ﴿ما أنزل الله لكم من رزق﴾؟","answer":"يفيد أن الرزق عطاء نازل من عند الله وتقدير منه، فلا يملك البشر أن يحللوا أو يحرموا منه بغير إذنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص589، تحت «نكتة التعبير بالإنزال أنزل»","url":""}]},{"id":"s10-202","number":202,"surah":10,"verses":[59],"references":[{"surah":10,"verses":[59]}],"verseLabel":"يونس: 59","question":"ما دلالة الفاء في قوله: ﴿فجعلتم منه حرامًا وحلالًا﴾؟","answer":"تفيد ترتب تصرفهم الباطل مباشرة على رزق الله، فتفضح سرعة مقابلتهم النعمة بالتحكم والتحريم بلا إذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص592، تحت «دلالة الفاء في فجعلتم»","url":""}]},{"id":"s10-75","number":75,"surah":10,"verses":[59],"references":[{"surah":10,"verses":[59]}],"verseLabel":"يونس: 59","question":"لماذا خُتم السؤال بـ﴿آلله أذن لكم أم على الله تفترون﴾؟","answer":"الاستفهام إنكاري حجاجي يحصر الأمر في إذن من الله أو افتراء عليه؛ ولما لم يكن لهم إذن ثبت بطلان تحريمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص594، تحت «غرض الاستفهام في قل آلله أذن لكم»","url":""}]},{"id":"s10-76","number":76,"surah":10,"verses":[60],"references":[{"surah":10,"verses":[60]}],"verseLabel":"يونس: 60","question":"ما غرض الاستفهام في قوله تعالى: ﴿وما ظن الذين يفترون على الله الكذب يوم القيامة﴾؟","answer":"يفيد التهويل والوعيد: أيّ ظنّ لهم بمصيرهم وعقابهم حين يقفون بين يدي الله وينكشف افتراؤهم؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص603، تحت «الغرض من التعبير بالاستفهام في وما»","url":""}]},{"id":"s10-77","number":77,"surah":10,"verses":[61],"references":[{"surah":10,"verses":[61]}],"verseLabel":"يونس: 61","question":"ما فائدة عطف قوله: ﴿وما تتلو منه من قرآن﴾ على قوله: ﴿وما تكون في شأن﴾؟","answer":"خُصت تلاوة القرآن بعد عموم شؤون النبي ﷺ تشريفًا لها وتنبيهًا إلى عظم منزلتها مع دخولها في علم الله وشهوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص621، تحت «فائدة عطف وما تتلو منه من قرآن»","url":""}]},{"id":"s10-203","number":203,"surah":10,"verses":[61],"references":[{"surah":10,"verses":[61]}],"verseLabel":"يونس: 61","question":"ما بلاغة الالتفات من خطاب النبي ﷺ إلى الجمع في قوله: ﴿ولا تعملون من عمل﴾؟","answer":"انتقل الخطاب من النبي ﷺ إلى الأمة لتعميم إحاطة العلم والشهادة بكل أعمال المكلفين، فلا يختص المعنى بحال الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص625، تحت «بلاغة الالتفات»","url":""}]},{"id":"s10-204","number":204,"surah":10,"verses":[61],"references":[{"surah":10,"verses":[61]}],"verseLabel":"يونس: 61","question":"ما نكتة التعبير بـ﴿شهودًا﴾ في قوله: ﴿إلا كنا عليكم شهودًا﴾؟","answer":"صيغة الجمع تفيد تعدد جهات الشهادة والإحاطة بكل عمل حال مباشرته، فلا يغيب عن علم الله شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص630، تحت «نكتة استعمال جمع فعول شهودا»","url":""}]},{"id":"s10-78","number":78,"surah":10,"verses":[61],"references":[{"surah":10,"verses":[61]},{"surah":34,"verses":[3]}],"verseLabel":"يونس: 61؛ سبأ: 3","question":"ما وجه التشابه واختلاف السياق بين نفي عزوب مثقال الذرة عن علم الله في سورتي يونس وسبأ؟","answer":"تقرر الآيتان إحاطة علم الله بأدق الموجودات. جاءت آية يونس في سياق مراقبة أعمال العباد والشهادة عليها، وجاءت آية سبأ في سياق إثبات البعث والجزاء؛ فلا تغيب الأعمال عن علمه، ولا تضيع أجزاء الخلق عند الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص636، تحت «توجيه التشابه اللفظي بين آيتي سورة يونس وسبأ»","url":""}]},{"id":"s10-79","number":79,"surah":10,"verses":[62,63],"references":[{"surah":10,"verses":[62,63]}],"verseLabel":"يونس: 62–63","question":"لماذا عُبّر عن إيمان أولياء الله بالماضي وعن تقواهم بالمضارع في قوله: ﴿الذين آمنوا وكانوا يتقون﴾؟","answer":"الماضي يدل على تحقق أصل الإيمان وثباته، والمضارع يصور تجدد التقوى واستمرارها؛ فالولاية تقوم على إيمان راسخ وطاعة متواصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص653، تحت «سر التعبير عن الإيمان بالماضي وعن التقوى بالمضارع»","url":""}]},{"id":"s10-81","number":81,"surah":10,"verses":[64],"references":[{"surah":10,"verses":[64]}],"verseLabel":"يونس: 64","question":"ما المقصود بالبشرى لأولياء الله في الحياة الدنيا وفي الآخرة؟","answer":"تشمل في الدنيا ما يثبتهم من الرؤيا الصالحة والبشارة والذكر الحسن، وفي الآخرة بشارة الملائكة والجنة والرضوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص660، تحت «المعنى الإجمالي»","url":""}]},{"id":"s10-82","number":82,"surah":10,"verses":[65],"references":[{"surah":10,"verses":[65]}],"verseLabel":"يونس: 65","question":"لماذا قيل للنبي ﷺ: ﴿ولا يحزنك قولهم إن العزة لله جميعًا﴾؟","answer":"جاءت جملة ﴿إن العزة لله جميعًا﴾ مستأنفة تعليلًا للنهي عن الحزن؛ فأقوالهم لا تنقص الحق، لأن الغلبة والقوة كلها لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص676، تحت «سر الفصل في إن العزة»","url":""}]},{"id":"s10-84","number":84,"surah":10,"verses":[66],"references":[{"surah":10,"verses":[66]}],"verseLabel":"يونس: 66","question":"ما دلالة التعبير بالظن في قوله: ﴿إن يتبعون إلا الظن﴾؟","answer":"يدل على أن شركهم لا يقوم على علم أو حجة، وإنما غايته توهم غير موثوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص695، تحت «دلالة التعبير بالظن ووقوع مفعوليته»","url":""}]},{"id":"s10-205","number":205,"surah":10,"verses":[66],"references":[{"surah":10,"verses":[66]}],"verseLabel":"يونس: 66","question":"ما دلالة قوله تعالى: ﴿وإن هم إلا يخرصون﴾؟","answer":"الخرص قول بالتخمين الذي لا يستند إلى علم، وقد يفضي إلى الكذب؛ فالتعبير يبطل دعاواهم من أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص696، تحت «دلالة استعمال يخرصون»","url":""}]},{"id":"s10-85","number":85,"surah":10,"verses":[67],"references":[{"surah":10,"verses":[67]}],"verseLabel":"يونس: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿جعل لكم الليل لتسكنوا فيه والنهار مبصرًا﴾؟","answer":"في الآية احتباك: دل ذكر السكون مع الليل على حذف الحركة في النهار، ودل وصف النهار بالإبصار على حذف ظلمة الليل؛ فجمع التعبير نعمتَي الراحة والعمل بإيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص702، تحت «دلالة الاحتباك»","url":""}]},{"id":"s10-86","number":86,"surah":10,"verses":[67],"references":[{"surah":10,"verses":[67]}],"verseLabel":"يونس: 67","question":"لماذا خُتمت الآية بقوله: ﴿لقوم يسمعون﴾؟","answer":"خُص السمع لأن هذه الدلائل يبلّغها الوحي والموعظة، وإنما ينتفع بها من يسمع سماع تدبر وقبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص706، تحت «دلالة السمع وغرض تخصيصه»","url":""}]},{"id":"s10-87","number":87,"surah":10,"verses":[68],"references":[{"surah":10,"verses":[68]}],"verseLabel":"يونس: 68","question":"لماذا رد على قولهم: ﴿اتخذ الله ولدًا﴾ بقوله: ﴿سبحانه هو الغني﴾؟","answer":"نزّه الله نفسه عن قولهم، ثم أبطل دعواهم بغناه المطلق؛ فالولد إنما يُطلب لحاجة أو معونة أو بقاء نسل، والله غني عن ذلك كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص718، تحت «دلائل استحالة أن يكون لله تعالى ولد»","url":""}]},{"id":"s10-88","number":88,"surah":10,"verses":[68],"references":[{"surah":10,"verses":[68]}],"verseLabel":"يونس: 68","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أتقولون على الله ما لا تعلمون﴾؟","answer":"الاستفهام للإنكار والتوبيخ على نسبة أعظم الدعوى إلى الله بلا علم ولا سلطان؛ فهو يفضح افتراءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص723، تحت «دلالة الاستفهام في الآية»","url":""}]},{"id":"s10-89","number":89,"surah":10,"verses":[69,70],"references":[{"surah":10,"verses":[69,70]}],"verseLabel":"يونس: 69–70","question":"ما دلالة ترتيب مصير المفترين: متاع في الدنيا، ثم الرجوع إلى الله، ثم العذاب؟","answer":"يرتقي السياق من متاع قصير إلى الرجوع المحتوم ثم الجزاء الأليم؛ فيبين أن ظاهر النعمة العاجلة لا يناقض خسرانهم النهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص735، تحت «دلالة الترقي في الترتيب الزمني: المتاع، المرجع، الجزاء»","url":""}]},{"id":"s10-90","number":90,"surah":10,"verses":[71],"references":[{"surah":10,"verses":[71]}],"verseLabel":"يونس: 71","question":"ما دلالة قول نوح: ﴿إن كان كبر عليكم مقامي وتذكيري بآيات الله﴾؟","answer":"جعل المقام والتذكير مما يكبر ويثقل مجازًا، تصويرًا لشدة مشقة بقائه بينهم ودوام دعوته عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص751، تحت «بلاغة المجاز في كبر عليكم مقامي»","url":""}]},{"id":"s10-91","number":91,"surah":10,"verses":[71],"references":[{"surah":10,"verses":[71]}],"verseLabel":"يونس: 71","question":"ما دلالة أمر نوح قومه بقوله: ﴿فأجمعوا أمركم﴾؟","answer":"الأمر للتحدي والتعجيز: أحكموا تدبيركم واعزموا عليه مجتمعين، فلن تستطيعوا الإضرار به مع توكله على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص756، تحت «دلالة لفظ فأجمعوا»","url":""}]},{"id":"s10-206","number":206,"surah":10,"verses":[71],"references":[{"surah":10,"verses":[71]}],"verseLabel":"يونس: 71","question":"ما بلاغة قوله: ﴿ثم لا يكن أمركم عليكم غمة﴾؟","answer":"استعيرت الغمة للأمر الخفي الملتبس؛ أي اجعلوا تدبيركم واضحًا محكمًا لا خفاء فيه، مبالغة في تحديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص760، تحت «الغرض من الاستعارة التصريحية في الآية»","url":""}]},{"id":"s10-207","number":207,"surah":10,"verses":[71],"references":[{"surah":10,"verses":[71]}],"verseLabel":"يونس: 71","question":"ما دلالة قوله: ﴿ولا تنظرون﴾ في تحدي نوح لقومه؟","answer":"طلب منهم ألا يمهلوه، زيادة في إظهار ثقته بالله وتعجيزهم عن تنفيذ تهديدهم ولو اجتمعوا وعجلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص761، تحت «دلالة النهي في ولا تنظرون»","url":""}]},{"id":"s10-92","number":92,"surah":10,"verses":[72],"references":[{"surah":10,"verses":[72]}],"verseLabel":"يونس: 72","question":"ما دلالة النفي في قول نوح: ﴿فما سألتكم من أجر﴾؟","answer":"نفى أن يكون قد طلب منهم أي أجر، ليقطع تهمة المنفعة الشخصية ويثبت إخلاص دعوته لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص768، تحت «دلالة النفي بلفظ ما»","url":""}]},{"id":"s10-93","number":93,"surah":10,"verses":[73],"references":[{"surah":10,"verses":[73]}],"verseLabel":"يونس: 73","question":"ما دلالة الفاء في قوله: ﴿فكذبوه فنجيناه﴾؟","answer":"تفيد ترتيب استمرارهم على التكذيب على دعوة نوح، ثم ترتيب نجاته والمؤمنين على بلوغ التكذيب غايته وحلول الإغراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص778، تحت «دلالة الفاء في فكذبوه وفنجيناه»","url":""}]},{"id":"s10-208","number":208,"surah":10,"verses":[73],"references":[{"surah":10,"verses":[73]}],"verseLabel":"يونس: 73","question":"لماذا لم يكتف بذكر نجاة نوح ومن معه، بل قال: ﴿وجعلناهم خلائف﴾؟","answer":"زيادة جعلهم خلائف تتميم للنعمة؛ فلم ينجوا فحسب، بل أورثهم الله الأرض بعد هلاك المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص781، تحت «بلاغة الإطناب بجعلهم خلائف وعدم الاكتفاء بالنجاة»","url":""}]},{"id":"s10-94","number":94,"surah":10,"verses":[74],"references":[{"surah":10,"verses":[74]}],"verseLabel":"يونس: 74","question":"ما دلالة قوله تعالى عن الأمم بعد نوح: ﴿فما كانوا ليؤمنوا بما كذبوا به من قبل﴾؟","answer":"يدل على رسوخ تكذيبهم واستمرارهم عليه؛ فقد سبق منهم التكذيب ثم أصروا عليه بعد مجيء البينات حتى صار مانعًا من الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص790، تحت «دلالة تأصل الكفر قبل مجيء الرسل وبعده»","url":""}]},{"id":"s10-95","number":95,"surah":10,"verses":[75],"references":[{"surah":10,"verses":[75]}],"verseLabel":"يونس: 75","question":"ما دلالة العطف بـ﴿ثم﴾ في قوله: ﴿ثم بعثنا من بعدهم موسى وهارون﴾؟","answer":"تفيد التراخي الزمني بعد الرسل السابقين، وتوحي كذلك بالتراخي الرتبي لعظم شأن بعثة موسى وهارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص796، تحت «دلالة العطف بالحرف ثم»","url":""}]},{"id":"s10-209","number":209,"surah":10,"verses":[75],"references":[{"surah":10,"verses":[75]}],"verseLabel":"يونس: 75","question":"لماذا قُدّم موسى على هارون في قوله: ﴿موسى وهارون﴾؟","answer":"قُدم موسى لأنه المبعوث أصالة والمتولي مواجهة فرعون، وكان هارون وزيرًا مؤازرًا له في الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص797، تحت «علة التقديم في موسى وهارون»","url":""}]},{"id":"s10-210","number":210,"surah":10,"verses":[75],"references":[{"surah":10,"verses":[75]}],"verseLabel":"يونس: 75","question":"لماذا خُص فرعون وملؤه بالذكر في بعثة موسى وهارون؟","answer":"لأنهم رؤوس القوم وأصحاب السلطان والتأثير، وباستجابتهم أو استكبارهم يتبعهم عامة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص799، تحت «دلالة اختصاص ذكر فئة الملأ»","url":""}]},{"id":"s11-1","number":1,"surah":11,"verses":[1],"references":[{"surah":11,"verses":[1]}],"verseLabel":"هود: 1","question":"ما دلالة الجمع بين إحكام آيات الكتاب وتفصيلها في قوله تعالى: ﴿أحكمت آياته ثم فصلت﴾؟","answer":"لأن الإحكام يدل على كمال نظمه ومنعه من الخلل، والتفصيل يدل على بيان معانيه وأحكامه وتنوع مقاصده؛ فجمع له كمال البناء وكمال البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص381، تحت «جمالية الاستعارة في «أحكمت آياته ثم فصلت»»","url":""}]},{"id":"s11-2","number":2,"surah":11,"verses":[1],"references":[{"surah":11,"verses":[1]}],"verseLabel":"هود: 1","question":"ما سرّ ختم وصف الكتاب بقوله تعالى: ﴿من لدن حكيم خبير﴾؟","answer":"لأن إحكام الآيات يناسب اسم ﴿الحكيم﴾، وتفصيلها على وفق مصالح الخلق يناسب ﴿الخبير﴾؛ فالخاتمة دليل على ما سبقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص381–382، تحت «علة ختم الآية بهذين الوصفين الجليلين»","url":""}]},{"id":"s11-3","number":3,"surah":11,"verses":[2],"references":[{"surah":11,"verses":[2]}],"verseLabel":"هود: 2","question":"ما سرّ تقديم ﴿ألا تعبدوا إلا الله﴾ على ﴿إنني لكم منه نذير وبشير﴾؟","answer":"بدأ بأصل التكاليف، وهو إفراد الله بالعبادة، ثم ذكر الرسول بصفتي الإنذار والبشارة إيماءً إلى اتباعه وطاعته، ثم جاء الأمر بالاستغفار والتوبة؛ فانتظم الخطاب في التوحيد ثم الإيمان بالرسول ثم العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص388، تحت «بلاغة تعاقب الجمل الثلاث على هذا الترتيب»","url":""}]},{"id":"s11-5","number":5,"surah":11,"verses":[3],"references":[{"surah":11,"verses":[3]}],"verseLabel":"هود: 3","question":"ما سرّ تقديم الاستغفار على التوبة في قوله تعالى: ﴿استغفروا ربكم ثم توبوا إليه﴾؟","answer":"يتعلق الاستغفار بطلب المغفرة لما مضى، وتتعلق التوبة بإصلاح الحال والعزم على عدم العودة إلى الذنب؛ فناسب سبق الماضي أن يتقدم الاستغفار في الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص395، تحت «نكتة تقديم الأمر بالاستغفار على الأمر بالتوبة»","url":""}]},{"id":"s11-6","number":6,"surah":11,"verses":[3],"references":[{"surah":11,"verses":[3]}],"verseLabel":"هود: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿يمتعكم متاعًا حسنًا إلى أجل مسمى﴾؟","answer":"قيد المتاع بالحسن لأنه ثمرة الإيمان والطاعة، وقيده بالأجل حتى لا يُفهم الوعد خلودًا في الدنيا؛ فهي نعمة موقوتة تتصل بعدها بالجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص397–398، تحت «فائدة وصف المتاع بـ«حسنًا»؛ دلالة «إلى»»","url":""}]},{"id":"s11-7","number":7,"surah":11,"verses":[3],"references":[{"surah":11,"verses":[3]}],"verseLabel":"هود: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿ويؤت كل ذي فضل فضله﴾؟","answer":"الفضل الأول عمل الإنسان الصالح، والفضل الثاني ما يعطيه الله من الجزاء؛ فالمعنى أن كل صاحب عمل صالح ينال جزاء عمله من فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص400، تحت «مدلول الفضلين في «ويؤت كل ذي فضل فضله»»","url":""}]},{"id":"s11-8","number":8,"surah":11,"verses":[4],"references":[{"surah":11,"verses":[4]}],"verseLabel":"هود: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى الله مرجعكم﴾ بتقديم الجار والمجرور؟","answer":"لقصر المرجع عليه وحده؛ فلا مهرب إلى قوة أخرى، ثم جاء ﴿وهو على كل شيء قدير﴾ لإثبات قدرته على البعث والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص410، 413، تحت «فائدة تقديم شبه الجملة «إلى الله»؛ نكتة تذييل الآية بصفة القدرة»","url":""}]},{"id":"s11-9","number":9,"surah":11,"verses":[5],"references":[{"surah":11,"verses":[5]}],"verseLabel":"هود: 5","question":"ما دلالة تصوير الإعراض والإخفاء بقوله تعالى: ﴿يثنون صدورهم﴾؟","answer":"صوّر شدة إعراضهم ومحاولتهم كتمان ما فيها بمن يطوي صدره وينحنيه؛ وهي هيئة جسدية تكشف انغلاقًا نفسيًا لا يخفى على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص418، تحت «بلاغة الحقيقة والاستعارة في ثني الصدور»","url":""}]},{"id":"s11-10","number":10,"surah":11,"verses":[5],"references":[{"surah":11,"verses":[5]}],"verseLabel":"هود: 5","question":"ما سرّ التعبير عن التستر بقوله تعالى: ﴿يستغشون ثيابهم﴾؟","answer":"يدل اللفظ على إحكام الغطاء والمبالغة في التستر؛ فليس غرضهم مجرد التغطية، بل التستر الكامل الذي يحجبهم عن رؤية الرسول وسماعه، ومع ذلك لا يخفى على الله ما يسرون وما يعلنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص421، تحت «سر التعبير بـ«يستغشون»»","url":""}]},{"id":"s11-11","number":11,"surah":11,"verses":[5],"references":[{"surah":11,"verses":[5]}],"verseLabel":"هود: 5","question":"ما دلالة التعبير عن الأسرار بقوله تعالى: ﴿بذات الصدور﴾؟","answer":"صوّر الأسرار والخواطر كأنها صاحبة للصدور، تلابسها وتساكنها ملازمة الصاحب لصاحبه؛ فالمقصود إحاطة علم الله بما يستكن في القلوب، لا مجرد العلم بظاهر الصدور.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص425، تحت «لطافة الإيجاز بالحذف في «بذات الصدور»؛ بلاغة المجاز في «بذات الصدور»»","url":""}]},{"id":"s11-12","number":12,"surah":11,"verses":[6],"references":[{"surah":11,"verses":[6]}],"verseLabel":"هود: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وما من دابة في الأرض إلا على الله رزقها﴾ بصيغة الاستغراق؟","answer":"أكد النفي بـ«من» ليستغرق كل دابة، صغيرة أو كبيرة؛ فجعل عموم رزقها دليلًا على إحاطة علم الله بجميع أحوالها، ومنها حاجتها وما يصلحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص430، تحت «بلاغة التعبير بأسلوب النفي الدال على الاستغراق والعموم»","url":""}]},{"id":"s11-13","number":13,"surah":11,"verses":[6],"references":[{"surah":11,"verses":[6]}],"verseLabel":"هود: 6","question":"ما دلالة الجمع بين ﴿مستقرها﴾ و﴿مستودعها﴾ في بيان علم الله بالدابة؟","answer":"يشمل التعبير مواضع استقرار الدابة وإيداعها، ويكني عن إحاطة علم الله بها في كل حال، في سكونها وحركتها؛ فلا يخفى عليه موضعها ولا تحولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص435–436، تحت «دلالة التعبير بصيغة «مفعل» في لفظي «مستقرها» و«مستودعها»؛ الغرض من التعبير بالكناية»","url":""}]},{"id":"s11-14","number":14,"surah":11,"verses":[7],"references":[{"surah":11,"verses":[7]}],"verseLabel":"هود: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿وكان عرشه على الماء﴾ في سياق خلق السماوات والأرض؟","answer":"تدل «كان» على سبق وجود العرش والماء لخلق السماوات والأرض. وذكر العرش على الماء يبين عظم قدرة الله على إمساك مخلوقاته؛ فكلها محتاجة إلى قدرته وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص442، تحت «دلالة العطف بالواو في «وكان عرشه على الماء»»","url":""}]},{"id":"s11-15","number":15,"surah":11,"verses":[7],"references":[{"surah":11,"verses":[7]}],"verseLabel":"هود: 7","question":"ما سرّ التعبير بـ﴿أحسن عملًا﴾ في غاية الابتلاء، دون «أكثر عملًا»؟","answer":"للدلالة على أن العبرة بحسن العمل لا بكثرته؛ فاللفظ يحث على إحسان العمل والترقي في مراتبه، ولا يجعل العدد وحده معيارًا للتفاضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص444، تحت «نكتة التعبير بلفظ «أحسن»»","url":""}]},{"id":"s11-16","number":16,"surah":11,"verses":[7],"references":[{"surah":11,"verses":[7]}],"verseLabel":"هود: 7","question":"ما الغرض من التعبير بالكناية في قول الكافرين عن خبر البعث: ﴿إن هذا إلا سحر مبين﴾؟","answer":"كنوا بوصف خبر البعث بالسحر عن تكذيبهم الرسول وإنكارهم البعث؛ لأن مجرد الإخبار عن أمر مستقبل لا يكون سحرًا في حقيقته، وإنما أرادوا تهويل رفضهم للخبر والطعن في قائله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص451، تحت «الغرض من التعبير بالكناية»","url":""}]},{"id":"s11-203","number":203,"surah":11,"verses":[7],"references":[{"surah":11,"verses":[7]}],"verseLabel":"هود: 7","question":"لماذا صيغ رد الكافرين على خبر البعث بطريق القصر: ﴿إن هذا إلا سحر مبين﴾؟","answer":"جاء النفي والاستثناء ليحصروا الخبر في السحر حصرًا مؤكدًا، مبالغةً في إنكاره وقطعًا منهم لكل احتمال يدل على صدقه، ففضحت الصياغة شدة عنادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص452، تحت «سر اصطفاء النفي والاستثناء طريقًا للقصر»","url":""}]},{"id":"s11-17","number":17,"surah":11,"verses":[8],"references":[{"surah":11,"verses":[8]}],"verseLabel":"هود: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿ولئن أخرنا عنهم العذاب إلى أمة معدودة﴾؟","answer":"تشير «أمة» إلى أمد مرتبط بانقضاء جيل واجتماع الوقت المحدد للعذاب بعد الإنذار والإعذار. ووصفها بـ«معدودة» يبين أنها محصورة الأيام، قصيرة معلومة عند الله، وإن طالت في نظر الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص458، تحت «سر التعبير بـ«أمة معدودة»؛ نكتة الوصف في «معدودة»»","url":""}]},{"id":"s11-18","number":18,"surah":11,"verses":[8],"references":[{"surah":11,"verses":[8]}],"verseLabel":"هود: 8","question":"ما دلالة التنبيه ونفي الصرف في قوله تعالى: ﴿ألا يوم يأتيهم ليس مصروفًا عنهم﴾؟","answer":"افتتح بـ﴿ألا﴾ للتنبيه، ونفى صرف العذاب لا مجرد تأخره؛ فما اتخذوه مادة للسخرية سيحيط بهم ولا يستطيعون دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص461–462، تحت «فائدة التعبير بأداة التنبيه «ألا»؛ نكتة التعبير بلفظ الخبر «مصروفًا»»","url":""}]},{"id":"s11-19","number":19,"surah":11,"verses":[9],"references":[{"surah":11,"verses":[9]}],"verseLabel":"هود: 9","question":"ما سرّ التعبير في قوله تعالى في الرحمة: ﴿أذقنا الإنسان منا رحمة﴾؟","answer":"الإذاقة تدل على أقل قدر من النعمة؛ فإذا كان الإنسان ييأس بزوال لمحة منها ظهر اضطرابه وقلة صبره. وإضافة الرحمة إلى الله تذكر بمصدرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص470–471، تحت «نكتة التعبير بـ«أذقنا»؛ سر القيد بشبه الجملة في «منا»»","url":""}]},{"id":"s11-20","number":20,"surah":11,"verses":[9],"references":[{"surah":11,"verses":[9]}],"verseLabel":"هود: 9","question":"ما دلالة الجمع بين الوصفين ﴿ليئوس كفور﴾؟","answer":"جمع بين شدة اليأس من عودة ما نزع منه، وكفران ما سبق له من النعمة وما بقي منها؛ فالصيغتان تبرزان حرمانه من الصبر والشكر، وفي الجمع بينهما توبيخ شديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص474–475، تحت «براعة التعبير بالوصفين «ليئوس كفور»»","url":""}]},{"id":"s11-21","number":21,"surah":11,"verses":[10],"references":[{"surah":11,"verses":[10]}],"verseLabel":"هود: 10","question":"ما سرّ التعبير عند عودة النعمة بقوله: ﴿ليقولن ذهب السيئات عني﴾؟","answer":"لا يرى النعمة فضلًا يستوجب الشكر، بل مجرد انتهاء لما كان يؤلمه؛ ثم يبني على زواله أمنًا مغرورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص485–486، تحت «الغرض من الكناية في «ذهبت السيئات عني»؛ سر مجيء تأكيدين في «إنه لفرح فخور»»","url":""}]},{"id":"s11-22","number":22,"surah":11,"verses":[10],"references":[{"surah":11,"verses":[10]}],"verseLabel":"هود: 10","question":"ما دلالة وصف الإنسان بعد زوال الضر بقوله تعالى: ﴿إنه لفرح فخور﴾؟","answer":"يعلل الوصفان قوله المتباهي ﴿ذهب السيئات عني﴾؛ فقد حمله شدة الفرح بالنعمة والفخر بها على الإعجاب بما ناله، بدل أن يشكر الله عليها، فورد الوصفان في مقام الذم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص486، تحت «شبه كمال الاتصال في الجملة المؤكدة بالأداة «إن»»","url":""}]},{"id":"s11-23","number":23,"surah":11,"verses":[11],"references":[{"surah":11,"verses":[11]}],"verseLabel":"هود: 11","question":"ما سرّ استثناء ﴿الذين صبروا وعملوا الصالحات﴾ من تقلّب الإنسان بين اليأس والفخر؟","answer":"لأن الصبر يضبطه عند الضر، والعمل الصالح يضبطه عند النعمة؛ فبهما ينجو من اليأس والكفر والبطر والفخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص487–488، تحت «الغرض من التعبير بالموصول «الذين» وصلته «صبروا»؛ دلالة العطف في سياق جملتي الصبر والعمل الصالح»","url":""}]},{"id":"s11-24","number":24,"surah":11,"verses":[12],"references":[{"surah":11,"verses":[12]}],"verseLabel":"هود: 12","question":"ما أثر الاستعارة في قوله تعالى: ﴿وضائق به صدرك﴾؟","answer":"صورت الاستعارة ما يجده النبي من شدة وقع اقتراحات المعاندين كأن الصدر يضيق عن احتمالها، فقرّبت أثر أذاهم في النفس، وجاء السياق تسليةً له وتثبيتًا على البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص494، تحت «الغرض من التعبير بالاستعارة»","url":""}]},{"id":"s11-204","number":204,"surah":11,"verses":[12],"references":[{"surah":11,"verses":[12]}],"verseLabel":"هود: 12","question":"ما دلالة التعبير باسمي الفاعل ﴿تارك﴾ و﴿ضائق﴾ في قوله تعالى: ﴿فلعلك تارك بعض ما يوحى إليك وضائق به صدرك﴾؟","answer":"استحضرت صيغة اسم الفاعل الحالة التي كاد ضغط المعاندين يوقعها، من غير أن تثبت وقوع ترك الوحي؛ فصورت قرب الضيق وقوته، وجاءت تسليةً وتحذيرًا من أن تصرفه مطالبهم عن البلاغ الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص495، تحت «دلالة التعبير باسم الفاعل «تارك» و«ضائق»»","url":""}]},{"id":"s11-25","number":25,"surah":11,"verses":[12],"references":[{"surah":11,"verses":[12]}],"verseLabel":"هود: 12","question":"ما دلالة اقتران طلب الكنز بطلب الملك في قولهم: ﴿لولا أنزل عليه كنز أو جاء معه ملك﴾؟","answer":"يكشف الطلبان موازينهم المضطربة؛ فقد عظموا المال وربطوا به السيادة، واستبعدوا اجتماع البشرية والرسالة، فطلبوا ملكًا يؤيد الرسول. وغفلوا عن قدر القرآن وعن دلالة الرسالة التي جاء بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص500–501، تحت «دلالة التعبير بـ«عليه كنز»؛ دلالة العطف في قوله «أو جاء معه ملك»»","url":""}]},{"id":"s11-26","number":26,"surah":11,"verses":[12],"references":[{"surah":11,"verses":[12]}],"verseLabel":"هود: 12","question":"ما سرّ ختم الآية بقوله تعالى: ﴿والله على كل شيء وكيل﴾؟","answer":"فيها تسلية للرسول بأن الله يتولى شؤون الخلق، وتعريض بأن الرسول ليس موكلًا بإجبارهم على الإيمان؛ فعليه الإنذار والبلاغ، ولا ينبغي أن يحمله إعراضهم على ترك الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص503، تحت «بلاغة الجملة التذييلية»","url":""}]},{"id":"s11-27","number":27,"surah":11,"verses":[13],"references":[{"surah":11,"verses":[13]}],"verseLabel":"هود: 13","question":"ما سرّ التحدي بعشر سور في هود، وبسورة واحدة في يونس؟","answer":"في هود قوبلت دعوى الافتراء بقوله ﴿مفتريات﴾، فوسع عليهم في مضمون الكلام المطلوب، وناسب هذه التوسعة طلب عشر سور. أما في يونس فلم يذكر هذا القيد، بل طلب المماثلة مطلقًا، وهي أشق، فناسبها الاكتفاء بسورة واحدة؛ والغاية إظهار عجزهم في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص518، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s11-28","number":28,"surah":11,"verses":[13],"references":[{"surah":11,"verses":[13]}],"verseLabel":"هود: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿مفتريات﴾ مع أن الافتراء باطل؟","answer":"جاراهم في فرضهم: إن كان القرآن مفترى كما تزعمون فاختلقوا أنتم عشر سور تشبهه؛ فحتى مع إسقاط قيد الصدق عجزوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص511–512، تحت «نكتة مجيء «مفتريات»؛ براعة التعبير بوصف «مفتريات»»","url":""}]},{"id":"s11-29","number":29,"surah":11,"verses":[14],"references":[{"surah":11,"verses":[14]}],"verseLabel":"هود: 14","question":"ما دلالة توجيه الخطاب في قوله تعالى: ﴿فإن لم يستجيبوا لكم﴾؟","answer":"يحتمل أن يكون الخطاب للمشركين: فإن لم يجبكم من تستعينون بهم إلى المعارضة، فاعلموا أن القرآن من عند الله. ويحتمل أن يكون للرسول والمؤمنين: فإن لم يستجب الكفار لتحديكم، ظهر عجزهم. وعلى الوجه الثاني تُدخل صيغة الجمع المؤمنين مع الرسول في التحدي ونصرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص522–523، تحت «دلالة الخطاب في «فإن لم يستجيبوا»»","url":""}]},{"id":"s11-30","number":30,"surah":11,"verses":[14],"references":[{"surah":11,"verses":[14]}],"verseLabel":"هود: 14","question":"ما سرّ ختم التحدي بقوله تعالى: ﴿فهل أنتم مسلمون﴾؟","answer":"لأن العجز ليس نهاية مناظرة لغوية فقط، بل حجة تستدعي قرارًا: هل تنقادون بعد أن ثبت أن القرآن من عند الله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص529، تحت «بلاغة الاستفهام في «فهل»»","url":""}]},{"id":"s11-31","number":31,"surah":11,"verses":[15],"references":[{"surah":11,"verses":[15]}],"verseLabel":"هود: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿من كان يريد الحياة الدنيا وزينتها﴾ ولم يكتفِ بالدنيا؟","answer":"فرق بين أصل الحياة وما يلتصق بها من زخارف؛ ليشمل من جعل غايته البقاء واللذة والجاه جميعًا دون نظر إلى الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص534–535، تحت «مناسبة العطف في «وزينتها»؛ فائدة الإضافة في «وزينتها»»","url":""}]},{"id":"s11-32","number":32,"surah":11,"verses":[15],"references":[{"surah":11,"verses":[15]}],"verseLabel":"هود: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿نوف إليهم أعمالهم فيها وهم فيها لا يبخسون﴾؟","answer":"قد ينال صاحب العمل الدنيوي ثمرته العاجلة كاملة، لكن وفاء الأجر في الدنيا لا يعني قبول العمل في الآخرة إذا خلا من قصدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص535، 537، تحت «بلاغة التضمين في «نوف»؛ دلالة «فيها»»","url":""}]},{"id":"s11-33","number":33,"surah":11,"verses":[16],"references":[{"surah":11,"verses":[16]}],"verseLabel":"هود: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿وحبط ما صنعوا فيها وباطل ما كانوا يعملون﴾؟","answer":"الحبوط يدل على سقوط ثواب ما صنعوه من أعمال البر حين لم تقترن بالإيمان والنية الصحيحة، أما البطلان فيصف ما لا جهة صلاح له أصلًا؛ ففرّق التعبير بين عمل فقد ثمرته الأخروية وعمل لا طائل تحته.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص545، تحت «براعة التعبير بـ«وحبط» و«وباطل»»","url":""}]},{"id":"s11-34","number":34,"surah":11,"verses":[17],"references":[{"surah":11,"verses":[17]}],"verseLabel":"هود: 17","question":"ما دلالة التعبير عن المؤمن بأنه ﴿على بينة من ربه﴾؟","answer":"﴿على﴾ تشعر بالتمكن والثبات، والبينة نور واضح من الله؛ فالمؤمن قائم على حجة لا على تقليد أو هوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص550–551، تحت «فائدة حرف الاستعلاء «على»؛ نكتة التعبير «بينة» ودلالته؛ دلالة التعبير «من ربه»»","url":""}]},{"id":"s11-35","number":35,"surah":11,"verses":[17],"references":[{"surah":11,"verses":[17]}],"verseLabel":"هود: 17","question":"ما دلالة تتابع البينة والشاهد وكتاب موسى في قوله تعالى: ﴿أفمن كان على بينة من ربه ويتلوه شاهد منه ومن قبله كتاب موسى﴾؟","answer":"يبين السياق تعاضد أدلة الإيمان؛ فالبينة أساس، ويتبعها شاهد مؤيد، ويسبق ذلك كتاب موسى شاهدًا على صدق القرآن ونبوة محمد ﷺ. وذكر كتاب موسى يقيم الحجة بكتاب اتفق أهل الكتاب على أنه من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص551–552، تحت «دلالة الضمير في «ويتلوه»؛ دلالة الواو في «ومن قبله»»","url":""}]},{"id":"s11-36","number":36,"surah":11,"verses":[17],"references":[{"surah":11,"verses":[17]}],"verseLabel":"هود: 17","question":"ما سرّ وصف كتاب موسى بأنه ﴿إمامًا ورحمة﴾؟","answer":"لأنها كانت كتابًا يُقتدى به في الهداية، ورحمة لمن اتبعها، فشهادتها للوحي الجديد امتداد لسلسلة الكتب لا أمر منقطع عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص552–553، تحت «بلاغة الاستعارة في «إمامًا»؛ بلاغة المجاز المرسل في «ورحمة»»","url":""}]},{"id":"s11-37","number":37,"surah":11,"verses":[17],"references":[{"surah":11,"verses":[17]}],"verseLabel":"هود: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تك في مرية منه﴾ مع يقين النبي؟","answer":"تثبيت له، وتعريض بمن يشك، وتعليم للأمة أن اجتماع البينة والشاهد والكتاب السابق يقطع أسباب الارتياب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص556–557، تحت «براعة التعبير بالخطاب في النهي عن المرية منه»","url":""}]},{"id":"s11-38","number":38,"surah":11,"verses":[18],"references":[{"surah":11,"verses":[18]}],"verseLabel":"هود: 18","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ومن أظلم ممن افترى على الله كذبًا﴾؟","answer":"الاستفهام إنكاري يفيد التقرير: لا أحد أظلم ممن افترى على الله، وفيه تهويل لجريمته وتعريض بمن نسبوا القرآن إلى غير منزله وزعموا أن الرسول افتراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص564، تحت «بلاغة الاستفهام بين الإنكار والتقرير»","url":""}]},{"id":"s11-205","number":205,"surah":11,"verses":[18],"references":[{"surah":11,"verses":[18]}],"verseLabel":"هود: 18","question":"ما سرّ التعبير باسم التفضيل ﴿أظلم﴾ في قوله تعالى: ﴿ومن أظلم ممن افترى على الله كذبًا﴾؟","answer":"اختير اسم التفضيل لبيان أن الافتراء على الله قد بلغ الغاية في الظلم؛ إذ يجمع الكذب والتلبيس والصد عن الحق، فلا يتصور ظلم أشد منه في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص565، تحت «بلاغة التعبير باسم التفضيل «أظلم»»","url":""}]},{"id":"s11-39","number":39,"surah":11,"verses":[18],"references":[{"surah":11,"verses":[18]}],"verseLabel":"هود: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿هؤلاء الذين كذبوا على ربهم﴾ أمام الأشهاد؟","answer":"يحدد اسم الإشارة أصحاب الجريمة أمام الحاضرين، ويشهرهم بما كذبوا به على ربهم. ثم جاءت صلة الموصول كأن كذبهم أمر معروف لا يحتاج إلى تفصيل؛ فاجتمع التعيين والتشهير والتوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص568–569، تحت «مناسبة التعبير باسم الإشارة «هؤلاء»؛ فائدة مجيء الموصول مع صلته»","url":""}]},{"id":"s11-41","number":41,"surah":11,"verses":[20],"references":[{"surah":11,"verses":[20]}],"verseLabel":"هود: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿لم يكونوا معجزين في الأرض﴾؟","answer":"ينفي قدرتهم على الإفلات من سلطان الله في أي مكان، ثم ينفي وجود أولياء ينصرونهم؛ فسد عليهم طريق الهرب وطريق الحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص581، 583، تحت «دلالة التعبير بقوله «معجزين»؛ دلالة الحال في قوله «في الأرض»؛ دلالة العطف في «وما كان»»","url":""}]},{"id":"s11-42","number":42,"surah":11,"verses":[20],"references":[{"surah":11,"verses":[20]}],"verseLabel":"هود: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿يضاعف لهم العذاب ما كانوا يستطيعون السمع وما كانوا يبصرون﴾؟","answer":"لأنهم عطلوا أدوات الهداية عمدًا؛ فصار الإعراض المتكرر سببًا لمضاعفة الجزاء، لا عجزًا خَلقيًا عن السمع والبصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص591–592، تحت «سر التعليل بجملة «ما كانوا يستطيعون»؛ بلاغة الكناية في الآية»","url":""}]},{"id":"s11-43","number":43,"surah":11,"verses":[21],"references":[{"surah":11,"verses":[21]}],"verseLabel":"هود: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وضل عنهم ما كانوا يفترون﴾؟","answer":"يصور غياب نفع المعبودات الباطلة حين يطلبونها، كأنها ضلت طريقها إليهم. وفي إسناد الضلال إلى الأصنام تهكم بهم، وفي ﴿عنهم﴾ تصوير لبعدها عنهم؛ فلا تنفعهم دعاوى الألوهية والشفاعة التي افتروها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص600–602، تحت «دلالة التعبير بالماضي في «ضل»؛ معنى حرف الجر «عنهم» ودلالته؛ سر إسناد الضلال إلى الأصنام»","url":""}]},{"id":"s11-44","number":44,"surah":11,"verses":[22],"references":[{"surah":11,"verses":[22]}],"verseLabel":"هود: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿لا جرم أنهم في الآخرة هم الأخسرون﴾؟","answer":"تفيد ﴿لا جرم﴾ تأكيد الحكم وتحققه، ويؤكد ضمير الفصل اختصاصهم بأقصى الخسران. وجاء ﴿الأخسرون﴾ لأنهم جمعوا خسارة الدنيا والآخرة وخسارة أنفسهم؛ فهي خسارة عظيمة لا تنقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص607، 609–610، تحت «معنى «لا» في «لا جرم» ودلالتها؛ سر التوكيد بضمير الفصل «هم»؛ دلالة التعبير بصيغة التفضيل «الأخسرون»»","url":""}]},{"id":"s11-45","number":45,"surah":11,"verses":[23],"references":[{"surah":11,"verses":[23]}],"verseLabel":"هود: 23","question":"ما سرّ تعدية الإخبات بـ﴿إلى﴾ في قوله تعالى: ﴿وأخبتوا إلى ربهم﴾؟","answer":"لأن الإخبات ليس خشوعًا ساكنًا فقط، بل توجه وطمأنينة وانقياد ينتهي إلى الله؛ فالحرف يرسم جهة القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص617–618، تحت «معنى «إلى» ودلالته في «إلى ربهم»»","url":""}]},{"id":"s11-46","number":46,"surah":11,"verses":[24],"references":[{"surah":11,"verses":[24]}],"verseLabel":"هود: 24","question":"ما دلالة تشبيه الفريقين بالأعمى والأصم، والبصير والسميع؟","answer":"الكافر لا يرى الدليل ولا يسمع داعيه سماع قبول، والمؤمن يجمع الإدراكين؛ فالصورة تحول الفرق المعنوي إلى مشهد محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص625–626، تحت «الغرض من التشبيه في «مثل الفريقين»»","url":""}]},{"id":"s11-47","number":47,"surah":11,"verses":[24],"references":[{"surah":11,"verses":[24]}],"verseLabel":"هود: 24","question":"ما سرّ ختم المثل بقوله تعالى: ﴿هل يستويان مثلًا أفلا تذكرون﴾؟","answer":"الاستفهام يحمل السامع على إصدار الحكم بنفسه، ثم يوبخه على ترك أبسط تذكر يميز بين النور والعمى.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص628، 630، تحت «الغرض من الاستفهام في «هل يستويان مثلًا»؛ الغرض من الاستفهام في «أفلا تذكرون»»","url":""}]},{"id":"s11-48","number":48,"surah":11,"verses":[25],"references":[{"surah":11,"verses":[25]}],"verseLabel":"هود: 25","question":"ما دلالة تقديم ﴿لكم﴾ ووصف الإنذار بالبيان في قول نوح: ﴿إني لكم نذير مبين﴾؟","answer":"تقديم ﴿لكم﴾ يخصص قومه بهذا الإنذار، وفيه رفق بالنصح وإشفاق في البلاغ. ووصفه بـ﴿مبين﴾ يدل على أنه بيّن موجب العذاب وطريق الخلاص منه بيانًا واضحًا تزول به الشبهة وتقوم به الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص638، تحت «الغرض من تقديم «لكم» على خبر إن؛ الغرض من وصف الخبر بـ«مبين»»","url":""}]},{"id":"s11-49","number":49,"surah":11,"verses":[26],"references":[{"surah":11,"verses":[26]}],"verseLabel":"هود: 26","question":"ما دلالة حصر العبادة بقوله تعالى: ﴿أن لا تعبدوا إلا الله﴾؟","answer":"لأن أصل فسادهم توزيع العبادة بين الله وغيره، فجاء النفي والاستثناء ليهدما كل شريك ويثبتا العبادة له وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص643–644، تحت «الغرض من القصر في «لا تعبدوا إلا الله»»","url":""}]},{"id":"s11-50","number":50,"surah":11,"verses":[27],"references":[{"surah":11,"verses":[27]}],"verseLabel":"هود: 27","question":"ما سرّ إيثار وصف نوح بالبشرية في قول الملأ: ﴿ما نراك إلا بشرًا﴾؟","answer":"وقفوا عند ظاهر البشرية، فتوهموا أن مشاركة الرسول لهم في الخِلقة تمنع اختصاصه بالوحي، وكشف التعبير قصور تصورهم لحقيقة النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص655، تحت «سر إيثار التعبير بالبشرية»","url":""}]},{"id":"s11-206","number":206,"surah":11,"verses":[27],"references":[{"surah":11,"verses":[27]}],"verseLabel":"هود: 27","question":"ما دلالة قول الملأ لنوح: ﴿بشرًا مثلنا﴾؟","answer":"أرادوا بالمماثلة نفي كل مزية تؤهله للرسالة، وفي قولهم استهانة وادعاء للتفوق يكشفان نظرهم إلى الظاهر دون حقيقة الاصطفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص656، تحت «دلالة وصف المقصور بـ﴿مثلنا﴾»","url":""}]},{"id":"s11-51","number":51,"surah":11,"verses":[27],"references":[{"surah":11,"verses":[27]}],"verseLabel":"هود: 27","question":"ما دلالة وصف أتباع نوح بقولهم: ﴿أراذلنا بادي الرأي﴾؟","answer":"احتقروا ضعفهم الاجتماعي وزعموا أنهم آمنوا لأول خاطر بلا تدبر، فاستبدلوا وزن الدليل بميزان الطبقة والمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص660–661، تحت «سر العدول في «أراذلنا»؛ دلالة وصف المقصور عليه بـ«بادي الرأي»»","url":""}]},{"id":"s11-52","number":52,"surah":11,"verses":[27],"references":[{"surah":11,"verses":[27]}],"verseLabel":"هود: 27","question":"ما دلالة قول الملأ: ﴿وما نرى لكم علينا من فضل﴾؟","answer":"نفوا عن نوح وأتباعه أي فضل يوجب اتباعهم، ونظروا إلى مقاييس القوة والكثرة والمال. وتؤكد ﴿من﴾ استغراق النفي حتى لأدنى فضل، فتكشف العبارة كبرهم واعتمادهم على المظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص664–665، تحت «الغرض من تقديم «لكم»؛ دلالة «من» ومعناها في «من فضل»»","url":""}]},{"id":"s11-53","number":53,"surah":11,"verses":[28],"references":[{"surah":11,"verses":[28]}],"verseLabel":"هود: 28","question":"ما سرّ التعبير في قول نوح: ﴿إن كنت على بينة من ربي وآتاني رحمة من عنده فعميت عليكم﴾؟","answer":"قابل ظنهم الظاهر ببصيرته القائمة على البينة، وبيّن أن خفاء الرحمة عنهم ناشئ من إعراضهم لا من ضعفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص677–678، 680، 682، تحت «الغرض من الاستعارة في «على»؛ الغرض من تنكير «رحمة»؛ سر إيثار التعبير بالعمى دون الخفاء؛ معنى حرف الجر «عليكم» ودلالته»","url":""}]},{"id":"s11-54","number":54,"surah":11,"verses":[28],"references":[{"surah":11,"verses":[28]}],"verseLabel":"هود: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿أنلزمكموها وأنتم لها كارهون﴾؟","answer":"الإيمان لا يتحقق بإكراه القلب، والعبارة الطويلة في ﴿أنلزمكموها﴾ تشعر بثقل الإلزام الذي أنكروه؛ ومهمة الرسول البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص683–684، تحت «بلاغة التعبير بلفظ «أنلزمكموها»؛ الغرض من الاستفهام في «أنلزمكموها»»","url":""}]},{"id":"s11-55","number":55,"surah":11,"verses":[29],"references":[{"surah":11,"verses":[29]}],"verseLabel":"هود: 29","question":"ما سرّ تكرار نوح نداء قومه بقوله: ﴿يا قوم﴾؟","answer":"التكرار يستعطفهم ويؤكد بقاء رابطة النصح رغم أذاهم؛ فهو لا يخاطب أعداء غرباء بل قومًا يريد نجاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص691، تحت «سر إعادة النداء بـ«ويا قوم» وسر عطفه بالواو»","url":""}]},{"id":"s11-56","number":56,"surah":11,"verses":[29],"references":[{"surah":11,"verses":[29]}],"verseLabel":"هود: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿لا أسألكم عليه مالًا إن أجري إلا على الله﴾؟","answer":"نفى التهمة التي قد تحجبهم عن مضمون الدعوة؛ فاستغناؤه عن مالهم دليل إخلاصه، وحصر أجره في الله يحرره من ضغطهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص693، تحت «بلاغة الاحتراس في قوله «إن أجري إلا على الله»؛ الغرض من التعبير بأسلوب القصر في السياق»","url":""}]},{"id":"s11-57","number":57,"surah":11,"verses":[29],"references":[{"surah":11,"verses":[29]}],"verseLabel":"هود: 29","question":"ما دلالة تعليل رفض طرد المؤمنين بقوله تعالى: ﴿إنهم ملاقو ربهم﴾؟","answer":"يذكر نوح بحق المؤمنين وكرامتهم، وأنهم راجعون إلى ربهم؛ فطردهم ظلم يخاصمونه به عند الله. وفي التعليل ردّ على احتقار الملأ لهم، وإحالة إلى حكم الله بدل الحكم عليهم بالمكانة والمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص695، 697، تحت «لطيفة ارتباط نفي الطرد بجملة «وما نراك اتبعك»؛ موقع جملة «إنهم ملاقو ربهم» مما قبلها ودلالتها»","url":""}]},{"id":"s11-58","number":58,"surah":11,"verses":[30],"references":[{"surah":11,"verses":[30]}],"verseLabel":"هود: 30","question":"ما سرّ الاستفهام في قول نوح: ﴿من ينصرني من الله إن طردتهم﴾؟","answer":"نقل نوح القضية من طلب رضا الزعماء إلى حساب الله: فمن يحميه إن ظلم المؤمنين وطردهم؟ وفي ذلك إنكار لاقتراحهم وكشف لما يجر إليه من معصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص704، تحت «الغرض من الاستفهام في سياق الآية»","url":""}]},{"id":"s11-59","number":59,"surah":11,"verses":[31],"references":[{"surah":11,"verses":[31]}],"verseLabel":"هود: 31","question":"ما دلالة نفي نوح امتلاك خزائن الله وعلم الغيب وكونه ملكًا؟","answer":"صحح تصور النبوة: الرسول بشر يوحى إليه، لا يملك الرزق ولا الغيب ولا يتكلف طبيعة الملك؛ فقيمة دعوته في الوحي لا الخوارق المقترحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص710–712، 714، تحت «دلالة التعبير بالظرف «عندي» مقدمًا في السياق؛ لطيفة في علاقة جملة نفي الملائكية بتأكيد البشرية؛ لطيفة في تكرار الفعل «أقول» ثلاث مرات»","url":""}]},{"id":"s11-60","number":60,"surah":11,"verses":[31],"references":[{"surah":11,"verses":[31]}],"verseLabel":"هود: 31","question":"ما سرّ التعبير في قوله تعالى عن الضعفاء: ﴿الله أعلم بما في أنفسهم﴾؟","answer":"لم يزكِّ باطنهم من عند نفسه، لكنه رفض احتقارهم؛ فحساب السرائر لله، والواجب قبول ظاهر الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص717–718، تحت «دلالة وقوع المسند «أعلم» على صيغة «أفعل»؛ دلالة «ما» الموصولة وسر إيثارها على غيرها»","url":""}]},{"id":"s11-61","number":61,"surah":11,"verses":[32],"references":[{"surah":11,"verses":[32]}],"verseLabel":"هود: 32","question":"ما دلالة قول قوم نوح: ﴿قد جادلتنا فأكثرت جدالنا﴾؟","answer":"حولوا طول البيان والحجة إلى تهمة، ثم طلبوا العذاب استعجالًا؛ وهو انتقال من عجز المناظرة إلى المكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص724–725، تحت «دلالة التعبير بالماضي «أكثرت» في السياق؛ سر تقييد الفعل «جدالنا» بالمفعول به؛ الغرض من التعبير بفعل الأمر «فأتنا»»","url":""}]},{"id":"s11-62","number":62,"surah":11,"verses":[33],"references":[{"surah":11,"verses":[33]}],"verseLabel":"هود: 33","question":"ما سرّ القصر في قول نوح: ﴿إنما يأتيكم به الله﴾؟","answer":"قصر الإتيان بالعذاب على الله وحده؛ فالرسول منذر لا يملك إنزال العقوبة ولا تحديد وقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص730، تحت «السر في تعبيره بأسلوب القصر»","url":""}]},{"id":"s11-207","number":207,"surah":11,"verses":[33],"references":[{"surah":11,"verses":[33]}],"verseLabel":"هود: 33","question":"ما دلالة تقييد إتيان العذاب بالمشيئة في قوله: ﴿إن شاء﴾؟","answer":"يبين أن وقوع العذاب ووقته تابعان لمشيئة الله وحكمته، لا لاستعجال المكذبين ولا لقدرة الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص731، تحت «الغرض من ذكر جملة الشرط ﴿إن شاء﴾»","url":""}]},{"id":"s11-63","number":63,"surah":11,"verses":[34],"references":[{"surah":11,"verses":[34]}],"verseLabel":"هود: 34","question":"ما دلالة تعليق نفع نصح نوح بشرط إرادة الله في قوله: ﴿ولا ينفعكم نصحي إن أردت أن أنصح لكم إن كان الله يريد أن يغويكم﴾؟","answer":"يبين أن النصح لا ينفع من أصر على التكذيب حتى استحق الخذلان؛ فانتفاعه بالهداية تابع لحكمة الله مع بقاء مسؤوليته عن اختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص738، تحت «الغرض من التعبير بأسلوب الشرط في سياق الآية الكريمة»","url":""}]},{"id":"s11-208","number":208,"surah":11,"verses":[34],"references":[{"surah":11,"verses":[34]}],"verseLabel":"هود: 34","question":"ما دلالة التصريح باسم الجلالة في قوله: ﴿إن كان الله يريد أن يغويكم﴾؟","answer":"يصرح بأن الأمر كله لله ويستحضر جلاله وقدرته، فلا يملك الرسول هداية من أعرض واستحق الخذلان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص739، تحت «الغرض من التعبير باسم الجلالة ﴿الله﴾»","url":""}]},{"id":"s11-64","number":64,"surah":11,"verses":[35],"references":[{"surah":11,"verses":[35]}],"verseLabel":"هود: 35","question":"ما دلالة ورود ﴿أم يقولون افتراه﴾ في أثناء قصة نوح؟","answer":"على تفسيرها اعتراضًا في القصة، تنتقل الآية إلى مكذبي محمد ﷺ، وتبين أن إخباره بهذه التفاصيل الغيبية دليل على الوحي؛ فاتهامهم له بالافتراء مردود عليهم. وذكر المصدر وجهًا آخر يجعل الكلام من قصة نوح نفسها وردّه على قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص744–745، تحت «الآية الكريمة بين الاعتراض وعدمه»","url":""}]},{"id":"s11-65","number":65,"surah":11,"verses":[36],"references":[{"surah":11,"verses":[36]}],"verseLabel":"هود: 36","question":"ما دلالة القصر في قوله تعالى لنوح: ﴿لن يؤمن من قومك إلا من قد آمن﴾؟","answer":"أعلن انتهاء زمن الاستجابة بعد استنفاد البلاغ، وقصر المؤمنين على من سبق إيمانه؛ فأراح نوحًا من انتظار إيمان جديد ونهاه عن الحزن على اختيار قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص751، تحت «الغرض من التعبير بأسلوب القصر في السياق»","url":""}]},{"id":"s11-66","number":66,"surah":11,"verses":[37],"references":[{"surah":11,"verses":[37]}],"verseLabel":"هود: 37","question":"ما دلالة الجمع بين ﴿بأعيننا﴾ و﴿وحينا﴾ في الأمر بصنع الفلك؟","answer":"يجمع التعبير الحفظ والتعليم؛ فـ﴿بأعيننا﴾ كناية عن الرعاية والحراسة، و﴿وحينا﴾ يدل على أن صنع الفلك جرى بتعليم الله وتوجيهه. وبذلك يطمئن نوح إلى الحماية من أعدائه وإلى معرفة كيفية الصنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص758–759، تحت «التعبير بالجار والمجرور «بأعيننا» وما فيه من الكناية؛ دلالة عطف الوحي على الأعين في «ووحينا»»","url":""}]},{"id":"s11-67","number":67,"surah":11,"verses":[37],"references":[{"surah":11,"verses":[37]}],"verseLabel":"هود: 37","question":"ما دلالة النهي في قوله تعالى: ﴿ولا تخاطبني في الذين ظلموا إنهم مغرقون﴾؟","answer":"النهي عن طلب رفع العذاب عنهم أو تخفيفه أو تأخيره؛ فقد صدر الحكم بإغراقهم. وجاءت ﴿إنهم مغرقون﴾ تعليلًا للنهي وإخبارًا بأمر محتوم، فحسمت رجاء الشفاعة في إنجائهم من ذلك العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص759–761، تحت «الغرض من أسلوب النهي في «ولا تخاطبني»؛ موقع جملة «إنهم مغرقون» ودلالته»","url":""}]},{"id":"s11-68","number":68,"surah":11,"verses":[38],"references":[{"surah":11,"verses":[38]}],"verseLabel":"هود: 38","question":"ما سرّ التعبير بالمضارع في قوله تعالى: ﴿ويصنع الفلك﴾؟","answer":"يستحضر مشهد البناء المتجدد أمام الساخرين، وكل مرور للملأ يفتح جولة استهزاء؛ فكأن القارئ يرى الحدث.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص766–767، تحت «سر التعبير بالمضارع «ويصنع»»","url":""}]},{"id":"s11-69","number":69,"surah":11,"verses":[38],"references":[{"surah":11,"verses":[38]}],"verseLabel":"هود: 38","question":"ما سرّ التعبير في قول نوح: ﴿إن تسخروا منا فإنا نسخر منكم﴾؟","answer":"ليس مقابلة سباب، بل وعد بانكشاف موضع السخرية الحقيقي عند حلول العذاب؛ ستتحول سخريتهم القصيرة إلى حسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص777–778، تحت «التعبير بالسخرية بين المشاكلة والمجاز»","url":""}]},{"id":"s11-71","number":71,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]}],"verseLabel":"هود: 40","question":"ما دلالة ﴿فار التنور﴾ علامةً لبدء الطوفان؟","answer":"على تفسير التنور بأنه موقد الخبز، كان خروج الماء منه علامة على بدء الطوفان؛ فإذا فار الماء من موضع يابس محفوظ من الرطوبة، كان فورانه من غيره أشد. فجعل الله هذه العلامة إيذانًا لنوح ومن معه بالاستعداد والركوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص798–799، تحت «لفظ «التنور» بين الحقيقة والمجاز»","url":""}]},{"id":"s11-72","number":72,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]},{"surah":23,"verses":[27]}],"verseLabel":"هود: 40؛ المؤمنون: 27","question":"ما سرّ اختيار لفظ ﴿زوج﴾ في قوله: ﴿من كل زوجين اثنين﴾؟","answer":"يدل لفظ الزوج على اقتران الذكر بالأنثى، وهو الملائم لحفظ الأنواع واستمرار نسلها بعد الطوفان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص803، تحت «نكتة اختيار لفظ ﴿زوج﴾»","url":""}]},{"id":"s11-209","number":209,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]},{"surah":23,"verses":[27]}],"verseLabel":"هود: 40؛ المؤمنون: 27","question":"ما دلالة الاحتراس بلفظ ﴿اثنين﴾ بعد ﴿زوجين﴾؟","answer":"يزيل احتمال إرادة فرد واحد أو أكثر من اثنين، ويحدد المطلوب بذكر وأنثى من كل نوع لحفظ النسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص803، تحت «دلالة الاحتراس في ﴿اثنين﴾»","url":""}]},{"id":"s11-210","number":210,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]},{"surah":23,"verses":[27]}],"verseLabel":"هود: 40؛ المؤمنون: 27","question":"ما دلالة تنكير ﴿زوجين﴾ في قوله تعالى في المؤمنون: ﴿من كل زوجين اثنين﴾؟","answer":"يفيد عدم تعيين فردين بأعيانهما؛ فالمقصود حمل ذكر وأنثى صالحين من كل نوع ليبقى النسل، لا زوجين معلومين مخصوصين.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص590، تحت «نكتة تنكير لفظ ﴿زوجين﴾»","url":""}]},{"id":"s11-73","number":73,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]}],"verseLabel":"هود: 40","question":"ما دلالة استثناء ﴿من سبق عليه القول﴾ من أهل نوح؟","answer":"يبين أن القرابة لا تنقض حكم الإيمان والكفر؛ فالنجاة متصلة بالاستجابة لا بالنسب، وقد سبق الحكم على من اختار التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص804، تحت «دلالة الاستثناء»","url":""}]},{"id":"s11-74","number":74,"surah":11,"verses":[41],"references":[{"surah":11,"verses":[41]}],"verseLabel":"هود: 41","question":"ما سرّ التعبير في قول نوح: ﴿بسم الله مجراها ومرساها﴾؟","answer":"نسب بدء السفينة وسيرها ووقوفها إلى اسم الله، ليعلن أن الأسباب المادية وحدها لا تنجي، وإنما تجري برعايته وتقف بأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص14–16، تحت «الباء في «بسم» بين الحقيقة والمجاز؛ سر تقديم «بسم الله»»","url":""}]},{"id":"s11-75","number":75,"surah":11,"verses":[41],"references":[{"surah":11,"verses":[41]}],"verseLabel":"هود: 41","question":"ما دلالة ذكر المغفرة والرحمة في قوله: ﴿إن ربي لغفور رحيم﴾ وسط مشهد الطوفان؟","answer":"نجاة المؤمنين من الطوفان فضل من الله ورحمة، لا استحقاق يلزمه؛ فختم الكلام بالمغفرة والرحمة يعلل النجاة ويوازن بين إهلاك المكذبين ورعاية المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص20، تحت «دلالة ذكر المغفرة والرحمة»","url":""}]},{"id":"s11-76","number":76,"surah":11,"verses":[42],"references":[{"surah":11,"verses":[42]}],"verseLabel":"هود: 42","question":"ما دلالة تشبيه أمواج الطوفان بالجبال؟","answer":"لبيان علوها وضخامتها وثقل رهبتها؛ فالسفينة لا تسير فوق ماء هادئ بل بين كتل هائلة لا ينجي منها إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص29، تحت «دلالة التشبيه في «في موج كالجبال»»","url":""}]},{"id":"s11-77","number":77,"surah":11,"verses":[42],"references":[{"surah":11,"verses":[42]}],"verseLabel":"هود: 42","question":"لماذا انتقل السياق من قوله: ﴿وقال اركبوا فيها﴾ إلى قوله: ﴿ونادى نوح ابنه﴾؟","answer":"جاء الأمر بالركوب عامًا لمن معه، أما الابن فكان بعيدًا عن موضع السفينة فاحتاج إلى نداء يبلغ البعيد؛ وفي تخصيصه بالنداء تصوير لحرص الأب على نجاته في اللحظة الأخيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص31، تحت «سر التعبير في «وقال اركبوا» و«ونادى نوح ابنه»»","url":""}]},{"id":"s11-211","number":211,"surah":11,"verses":[42],"references":[{"surah":11,"verses":[42]}],"verseLabel":"هود: 42","question":"ما دلالة وصف ابن نوح بأنه ﴿كان في معزل﴾؟","answer":"يصوّر اسم المكان ابتعاده عن أبيه والمؤمنين وعن موضع النجاة، وتوحي عزلته المكانية بعزلته عن جماعة الإيمان التي حملتها السفينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص32، تحت «دلالة استعمال اسم المكان «معزل»»","url":""}]},{"id":"s11-78","number":78,"surah":11,"verses":[43],"references":[{"surah":11,"verses":[43]}],"verseLabel":"هود: 43","question":"ما دلالة قول ابن نوح: ﴿سآوي إلى جبل يعصمني من الماء﴾؟","answer":"يكشف قوله إصراره وغفلته عن حقيقة الموقف؛ فقد توهم أن الالتجاء إلى جبل ينجيه من الماء، وأنكر أن النجاة في الاستجابة لدعوة أبيه. وفي تصوير هذا الوهم تهكم باغتراره بالحماية التي يتخيلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص35، تحت «دلالة التهكم في «سآوي إلى جبل يعصمني»»","url":""}]},{"id":"s11-79","number":79,"surah":11,"verses":[43],"references":[{"surah":11,"verses":[43]}],"verseLabel":"هود: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿وحال بينهما الموج فكان من المغرقين﴾؟","answer":"الجملة تقطع الحوار فجأة كما قطع الموج الصلة بينهما؛ فسرعة الأسلوب تجسد مباغتة النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص39–40، تحت «دلالة التعبير بالفعل «وحال بينهما»؛ دلالة استعمال الفاء في «فكان»»","url":""}]},{"id":"s11-80","number":80,"surah":11,"verses":[44],"references":[{"surah":11,"verses":[44]}],"verseLabel":"هود: 44","question":"ما دلالة توجيه الخطاب إلى الأرض والسماء في قوله تعالى: ﴿يا أرض ابلعي ماءك ويا سماء أقلعي﴾؟","answer":"صوّرهما مأمورتين تستجيبان فورًا لسلطان الله؛ فالمشهد الكوني الهائل ينتهي بكلمتين موجزتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص47، 50، تحت «بلاغة التعبير بالنداء «يا أرض»؛ الغرض من التعبير بالاستعارة المكنية»","url":""}]},{"id":"s11-81","number":81,"surah":11,"verses":[44],"references":[{"surah":11,"verses":[44]}],"verseLabel":"هود: 44","question":"ما سرّ توجيه الخطاب إلى الأرض بـ﴿ابلعي﴾ وإلى السماء بـ﴿أقلعي﴾؟","answer":"الأرض مأمورة بابتلاع الماء الموجود، والسماء مأمورة بالكف عن إنزاله؛ فاختير لكل جهة الفعل المطابق لدورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص52، 58، تحت «بلاغة الاستعارة في «البلع»؛ غرض الاستعارة التصريحية في «أقلعي»»","url":""}]},{"id":"s11-82","number":82,"surah":11,"verses":[44],"references":[{"surah":11,"verses":[44]}],"verseLabel":"هود: 44","question":"ما سرّ بناء الفعلين للمفعول في قوله تعالى: ﴿وغيض الماء وقضي الأمر﴾؟","answer":"فاعل هذه الأفعال معلوم؛ فلا يقدر على إنهاء الطوفان وإنفاذ أمره إلا الله. وحذف الفاعل يوجز العبارة ويوجه النظر إلى تحقق النتائج: نقصان الماء وتمام ما وعد به من إهلاك الكافرين وإنجاء المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص62–63، 65، تحت «دلالة بناء الفعل «وغيض» للمفعول؛ نكتة بناء الفعل للمفعول في «وقضي»؛ غرض الكناية في الأفعال المبنية للمفعول»","url":""}]},{"id":"s11-83","number":83,"surah":11,"verses":[44],"references":[{"surah":11,"verses":[44]}],"verseLabel":"هود: 44","question":"ما دلالة ختم مشهد الطوفان بقوله تعالى: ﴿بعدًا للقوم الظالمين﴾؟","answer":"بعد سكون الطبيعة صدر الحكم الأخلاقي: لم يكن الغرق حادثًا طبيعيًا عابرًا، بل إبعادًا مستحقًا بسبب الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص70–72، تحت «فائدة استعمال المصدر «بعدًا»؛ معنى اللام الداخلة على «القوم»؛ سر التعبير بالظالمين دون الكافرين»","url":""}]},{"id":"s11-84","number":84,"surah":11,"verses":[45],"references":[{"surah":11,"verses":[45]}],"verseLabel":"هود: 45","question":"ما سرّ التعبير في قول نوح: ﴿إن ابني من أهلي وإن وعدك الحق﴾؟","answer":"في قوله إظهار لشفقته على ابنه، ورجاء أن يشمله وعد نجاة الأهل، لا اعتراض على حكم الله. وذكر المصدر أن كلامه يتضمن طلب الرحمة والمغفرة لابنه، مع التسليم بأن وعد الله حق وأن الحكم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص84–85، تحت «دلالة الجملة الخبرية «إن ابني من أهلي»؛ دلالة الجملة الخبرية في «وإن وعدك الحق»»","url":""}]},{"id":"s11-85","number":85,"surah":11,"verses":[46],"references":[{"surah":11,"verses":[46]}],"verseLabel":"هود: 46","question":"ما معنى قوله تعالى عن ابن نوح: ﴿إنه ليس من أهلك﴾؟","answer":"المنفي هو دخوله في الأهل الموعودين بالنجاة، لا نسبه إلى نوح؛ لأن رابطة الإيمان هي المعتبرة في هذا الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص94–95، تحت «معنى نفي الأهلية»","url":""}]},{"id":"s11-212","number":212,"surah":11,"verses":[46],"references":[{"surah":11,"verses":[46]}],"verseLabel":"هود: 46","question":"ما سر الإخبار عن ابن نوح بالمصدر في قوله: ﴿إنه عمل غير صالح﴾؟","answer":"بلغ في ملازمة العمل غير الصالح مبلغًا صُوِّر معه كأنه نفس العمل، مبالغة في بيان فساد طريقه وسبب خروجه من أهل النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص97، تحت «نكتة الإخبار عن الذات بالمصدر»","url":""}]},{"id":"s11-86","number":86,"surah":11,"verses":[46],"references":[{"surah":11,"verses":[46]}],"verseLabel":"هود: 46","question":"ما دلالة قوله تعالى لنوح: ﴿فلا تسألن ما ليس لك به علم﴾؟","answer":"هو تعليم وعتاب برفق، يرشد إلى ألا يُطلب أمر حتى يُعلم وجه صوابه، ويصحح إدخال ابنه في الأهل الموعودين بالنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص97، تحت «غرض النهي ودلالته»","url":""}]},{"id":"s11-87","number":87,"surah":11,"verses":[47],"references":[{"surah":11,"verses":[47]}],"verseLabel":"هود: 47","question":"ما دلالة استعاذة نوح بقوله: ﴿أعوذ بك أن أسألك ما ليس لي به علم﴾؟","answer":"لم يكتف بترك السؤال، بل لجأ إلى الله أن يعصمه من العودة إلى مثله؛ وفي ذلك كمال سرعة الرجوع وشدة الخوف من تجاوز حد العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص108، تحت «دلالة ذكر الاستعاذة»","url":""}]},{"id":"s11-213","number":213,"surah":11,"verses":[47],"references":[{"surah":11,"verses":[47]}],"verseLabel":"هود: 47","question":"لماذا قدّم نوح طلب المغفرة على الرحمة في قوله: ﴿وإلا تغفر لي وترحمني أكن من الخاسرين﴾؟","answer":"لأن إزالة أثر الذنب بالمغفرة تسبق نيل الفضل بالرحمة؛ فبدأ بطلب الوقاية من الضرر ثم طلب تمام الإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص110، تحت «نكتة تقديم المغفرة على الرحمة»","url":""}]},{"id":"s11-88","number":88,"surah":11,"verses":[48],"references":[{"surah":11,"verses":[48]}],"verseLabel":"هود: 48","question":"ما دلالة الجمع بين السلام والبركات في قوله: ﴿اهبط بسلام منا وبركات عليك﴾؟","answer":"السلام يؤمّن نوحًا ومن معه من مخاوف الطوفان، والبركات تبشرهم بنماء الحياة والخير بعد الخراب؛ فجمع لهم الأمن وامتداد النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص120، تحت «دلالة الجمع بين السلام والبركات»","url":""}]},{"id":"s11-89","number":89,"surah":11,"verses":[48],"references":[{"surah":11,"verses":[48]}],"verseLabel":"هود: 48","question":"لماذا ذُكرت أمم تتمتع ثم يمسها العذاب بعد بشارة نوح بالسلام والبركات؟","answer":"احتُرس بذلك من توهم شمول السلام والبركات لكل الذرية؛ فمنهم مؤمنون ينالون البركة، ومنهم أمم تتمتع زمنًا ثم تستحق العذاب بكفرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص123، تحت «بلاغة الاحتراس في التكرار اللفظي»","url":""}]},{"id":"s11-90","number":90,"surah":11,"verses":[49],"references":[{"surah":11,"verses":[49]}],"verseLabel":"هود: 49","question":"لماذا سُمّيت قصة نوح من ﴿أنباء الغيب﴾؟","answer":"لأن النبأ خبر عظيم ذو شأن؛ فالتعبير ينبه إلى عظمة ما أوحي من خبر نوح ووجوب الاعتبار به، لا تلقيه حكاية مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص131، تحت «نكتة التعبير بلفظ النبأ»","url":""}]},{"id":"s11-214","number":214,"surah":11,"verses":[49],"references":[{"surah":11,"verses":[49]}],"verseLabel":"هود: 49","question":"ما دلالة قوله بعد قصة نوح: ﴿ما كنت تعلمها أنت ولا قومك من قبل هذا﴾؟","answer":"ينفي أن تكون هذه التفاصيل مكتسبة من معرفة سابقة عند النبي ﷺ أو قومه، فيكون الإخبار بها حجة على أنها وحي من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص133، تحت «دلالة نفي العلم»","url":""}]},{"id":"s11-91","number":91,"surah":11,"verses":[49],"references":[{"surah":11,"verses":[49]}],"verseLabel":"هود: 49","question":"ما دلالة ختم قصة نوح بقوله تعالى: ﴿فاصبر إن العاقبة للمتقين﴾؟","answer":"ينقل القصة من حكاية الماضي إلى تثبيت الرسول ﷺ: كما طال ابتلاء نوح ثم نجا، فاصبر؛ فالعاقبة لأهل التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص137، تحت «غرض الأمر ونكتته»","url":""}]},{"id":"s11-92","number":92,"surah":11,"verses":[50],"references":[{"surah":11,"verses":[50]}],"verseLabel":"هود: 50","question":"ما سرّ التعبير في قوله تعالى في إرسال هود إلى عاد: ﴿أخاهم هودًا﴾؟","answer":"أخوّته لهم في النسب والقوم تجعل نصحه أقرب، وتنفي أن يكون غريبًا عن مصالحهم؛ أما مفاصلته فكانت في العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص144، تحت «دلالة التعبير بـ«أخاهم»»","url":""}]},{"id":"s11-93","number":93,"surah":11,"verses":[50],"references":[{"surah":11,"verses":[50]}],"verseLabel":"هود: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿ما لكم من إله غيره إن أنتم إلا مفترون﴾؟","answer":"بعد حصر الإله الحق كشف أن تعدد الآلهة اختلاق بلا برهان؛ فالشرك ليس نقص دليل فقط بل نسبة باطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص146–147، تحت «دلالة حرف «من» وغرضه؛ فائدة القصر بالنفي والاستثناء؛ بلاغة استعمال مفردة الافتراء»","url":""}]},{"id":"s11-94","number":94,"surah":11,"verses":[51],"references":[{"surah":11,"verses":[51]}],"verseLabel":"هود: 51","question":"ما دلالة نفي هود طلب الأجر في قوله: ﴿لا أسألكم عليه أجرًا﴾؟","answer":"يدل على إخلاص الدعوة وأنها ليست تجارة أو طلب منفعة من القوم، ويقطع شبهة أن يكون وراء دعوته مطمع دنيوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص147، تحت «دلالة نفي السؤال»","url":""}]},{"id":"s11-215","number":215,"surah":11,"verses":[51],"references":[{"surah":11,"verses":[51]}],"verseLabel":"هود: 51","question":"ما سر قول هود: ﴿إن أجري إلا على الذي فطرني﴾؟","answer":"اختار ﴿فطرني﴾ تذكيرًا بأن الخالق الذي أوجده هو وحده المستحق للعبادة والقادر على جزائه، بخلاف الأصنام التي لا تخلق ولا تنفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص149، تحت «سر استعمال «فطرني»»","url":""}]},{"id":"s11-95","number":95,"surah":11,"verses":[52],"references":[{"surah":11,"verses":[52]}],"verseLabel":"هود: 52","question":"لماذا ربط هود الاستغفار بنزول المطر وزيادة القوة؟","answer":"لأن التوبة سبب لفتح أبواب البركة، وجاء الوعد بما كانت عاد أحوج إليه: الغيث الذي يحيي أرضهم، وقوة تزداد على قوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص162، تحت «وجه الوعد بإنزال الماء»","url":""}]},{"id":"s11-96","number":96,"surah":11,"verses":[53],"references":[{"surah":11,"verses":[53]}],"verseLabel":"هود: 53","question":"ما دلالة قول قوم هود: ﴿ما جئتنا ببينة﴾؟","answer":"يعبر النفي عن عنادهم وعدم اعتدادهم بالحجج، لا عن خلو دعوته من البينة؛ فقد جعلوا إنكارها ذريعة للبقاء على كفرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص169، تحت «دلالة النفي»","url":""}]},{"id":"s11-97","number":97,"surah":11,"verses":[54],"references":[{"surah":11,"verses":[54]}],"verseLabel":"هود: 54","question":"ما دلالة اتهام قوم هود له بقولهم: ﴿إن نقول إلا اعتراك بعض آلهتنا بسوء﴾؟","answer":"عجزوا عن رد حجته ففسروا ثباته بالمس والجنون، ونسبوا الضر إلى أصنامهم ليحموا هيبتها؛ فجاء إعلان براءته منها وتحديه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص179–180، تحت «دلالة التعبير بلفظ «بعض»؛ الغرض من الخبر في الاتهام بالجنون»","url":""}]},{"id":"s11-98","number":98,"surah":11,"verses":[55],"references":[{"surah":11,"verses":[55]}],"verseLabel":"هود: 55","question":"ما دلالة تحدي هود قومه بقوله: ﴿فكيدوني جميعًا ثم لا تنظرون﴾؟","answer":"إظهار عملي لبطلان آلهتهم وثقته بالله؛ دعاهم مع معبوداتهم إلى أقصى الكيد دون إمهال، فعجزهم حجة محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص184، 186–187، تحت «معنى الفاء في قوله «فكيدوني»؛ بلاغة الكناية في الآية الكريمة؛ نكتة استعمال لفظ «جميعًا»»","url":""}]},{"id":"s11-99","number":99,"surah":11,"verses":[56],"references":[{"surah":11,"verses":[56]}],"verseLabel":"هود: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿إني توكلت على الله ربي وربكم﴾؟","answer":"جمع بين ربوبيته الخاصة التي تبعث الطمأنينة وربوبيته لهم التي تثبت سلطان الله عليهم ولو أنكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص193–194، تحت «دلالة الاستئناف التعليلي في «إني توكلت»؛ دلالة التعبير بـ«الله ربي»»","url":""}]},{"id":"s11-100","number":100,"surah":11,"verses":[56],"references":[{"surah":11,"verses":[56]}],"verseLabel":"هود: 56","question":"ما سر صورة ﴿ما من دابة إلا هو آخذ بناصيتها﴾؟","answer":"تمثل الصورة كل حي منقادًا تحت قبضة الله وتدبيره، كما يقاد المأخوذ بناصيته؛ فلا تتحرك قوة مستقلة عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص195، تحت «بلاغة الاستعارة التمثيلية في الأخذ بالناصية»","url":""}]},{"id":"s11-101","number":101,"surah":11,"verses":[56],"references":[{"surah":11,"verses":[56]}],"verseLabel":"هود: 56","question":"ما دلالة قوله تعالى: ﴿إن ربي على صراط مستقيم﴾ بعد ذكر التوكل وسلطان الله على كل دابة؟","answer":"يبين أن سلطان الله وتدبيره قائمان على الحق والعدل؛ لذلك صح التوكل عليه، فلا يخذل من اعتصم به ولا يفلت الظالم من حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص196، تحت «سر التعليل بعد ذكر التوكل»","url":""}]},{"id":"s11-216","number":216,"surah":11,"verses":[56],"references":[{"surah":11,"verses":[56]}],"verseLabel":"هود: 56","question":"ما دلالة تصوير عدل الله بقوله: ﴿إن ربي على صراط مستقيم﴾؟","answer":"صُوّر نهج الله في تدبير خلقه بالصراط المستقيم الذي لا عوج فيه، للدلالة على كمال العدل والاستقامة في حكمه ووعده ووعيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص197، تحت «بلاغة الاستعارة التصريحية في «صراط مستقيم»»","url":""}]},{"id":"s11-102","number":102,"surah":11,"verses":[57],"references":[{"surah":11,"verses":[57]}],"verseLabel":"هود: 57","question":"ما سرّ التعبير في قول هود: ﴿فقد أبلغتكم ما أرسلت به إليكم﴾؟","answer":"أقام الحجة وأعلن تمام مهمته؛ فإذا تولوا فالخسارة عليهم، والله قادر أن يستبدل بهم قومًا لا يعصونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص205–206، 208، تحت «معنى الفاء في قوله «فقد أبلغتكم»؛ دلالة «ما» في «ما أرسلت»؛ دلالة جملة الاستئناف في «ويستخلف ربي»»","url":""}]},{"id":"s11-103","number":103,"surah":11,"verses":[58],"references":[{"surah":11,"verses":[58]}],"verseLabel":"هود: 58","question":"ما سر تكرار فعل النجاة في قوله: ﴿نجينا هودًا﴾ ثم ﴿ونجيناهم من عذاب غليظ﴾؟","answer":"يفخم التكرار نعمة النجاة وينبه إلى تعدد وجوهها؛ فنجوا من العذاب الذي نزل بعاد، وقيل إن الثانية تشير كذلك إلى النجاة من عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص220، تحت «بلاغة الإطناب في تكرار الإنجاء في الآية»","url":""}]},{"id":"s11-217","number":217,"surah":11,"verses":[58],"references":[{"surah":11,"verses":[58]}],"verseLabel":"هود: 58","question":"ما دلالة تنكير ﴿عذاب غليظ﴾ في قصة عاد؟","answer":"يفيد تفخيم العذاب وتهويل شدته، حتى كأنه عذاب لا يحيط الوصف بمقداره ولا تعرف له غلظة مماثلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص221، تحت «إيثار التعبير بالتنكير في «عذاب غليظ»»","url":""}]},{"id":"s11-104","number":104,"surah":11,"verses":[59],"references":[{"surah":11,"verses":[59]}],"verseLabel":"هود: 59","question":"ما سرّ التعبير في قوله تعالى عن عاد: ﴿وتلك عاد جحدوا بآيات ربهم﴾؟","answer":"اسم الإشارة يعرضهم كأثر حاضر للعبرة، وجمع الجحود وعصيان الرسل واتباع الجبابرة جذور سقوطهم الديني والسياسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص226–228، 233، تحت «سر الإشارة بلفظ «وتلك»؛ سر إيثار التعبير بلفظ الجحود؛ نكتة ترتيب الجمل المبدوءة بالأفعال»","url":""}]},{"id":"s11-105","number":105,"surah":11,"verses":[60],"references":[{"surah":11,"verses":[60]}],"verseLabel":"هود: 60","question":"ما دلالة قوله في عاد: ﴿وأتبعوا في هذه الدنيا لعنة ويوم القيامة﴾؟","answer":"صوّر اللعنة كأنها لاحقة بهم ملازمة لآثارهم في الدنيا، ثم تتبعهم يوم القيامة؛ فليس هلاك حضارتهم نهاية الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص239، تحت «سر إيثار التعبير بـ«وأتبعوا» و«لعنة»»","url":""}]},{"id":"s11-106","number":106,"surah":11,"verses":[60],"references":[{"surah":11,"verses":[60]}],"verseLabel":"هود: 60","question":"ما دلالة ختم قصة عاد بقوله تعالى: ﴿ألا بعدًا لعاد قوم هود﴾؟","answer":"﴿ألا﴾ تلفت إلى الحكم النهائي، ونسبتهم إلى هود تزيد التوبيخ: جاءهم ناصح منهم فعادوه، فاستحقوا الإبعاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص241–243، تحت «نكتة تكرار «ألا»؛ دلالة الدعاء عليهم في «بعدًا لعاد»؛ دلالة عطف البيان في ختام الآية»","url":""}]},{"id":"s11-107","number":107,"surah":11,"verses":[61],"references":[{"surah":11,"verses":[61]}],"verseLabel":"هود: 61","question":"ما سرّ التعبير في قول صالح: ﴿هو أنشأكم من الأرض واستعمركم فيها﴾؟","answer":"ذكّرهم بأصلهم الأرضي وبالتكليف بعمارتها؛ فالذي أنشأهم ومكّنهم هو المستحق للعبادة لا ما يصنعونه فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص253–255، تحت «فائدة جملة «هو أنشأكم»؛ دلالة التعبير بصيغة «واستعمركم»»","url":""}]},{"id":"s11-108","number":108,"surah":11,"verses":[61],"references":[{"surah":11,"verses":[61]}],"verseLabel":"هود: 61","question":"ما دلالة ختم دعوة صالح إلى التوبة بقوله: ﴿إن ربي قريب مجيب﴾؟","answer":"القرب يزيل وحشة الرجوع، والإجابة تبعث الأمل في قبول الدعاء؛ فجاءت الخاتمة ملائمة للاستغفار والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص257–258، تحت «دلالة الاستئناف البياني بـ«إن»؛ نكتة الجمع بين القريب والمجيب»","url":""}]},{"id":"s11-109","number":109,"surah":11,"verses":[62],"references":[{"surah":11,"verses":[62]}],"verseLabel":"هود: 62","question":"ما دلالة قول قوم صالح: ﴿قد كنت فينا مرجوًا قبل هذا﴾؟","answer":"حاولوا الضغط عليه بماضي مكانته بينهم: كنا نرجو أن تكون زعيمًا موافقًا لنا، فإذا بالتوحيد يهدم توقعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص265، تحت «سر الوصف بكونه «مرجوًا»؛ فائدة التعبير بقوله «قبل هذا»»","url":""}]},{"id":"s11-110","number":110,"surah":11,"verses":[62],"references":[{"surah":11,"verses":[62]}],"verseLabel":"هود: 62","question":"ما دلالة كثرة التوكيد في قول قوم صالح: ﴿وإننا لفي شك مما تدعونا إليه﴾؟","answer":"بالغوا في تثبيت شكهم ليصوروه موقفًا راسخًا لا ترددًا عابرًا، ولييئسوا صالحًا من استجابتهم، مع أن قولهم مسوق للطعن وتبرير الرفض.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص268، تحت «دلالة تأكيد الخبر في شكهم في دعوته»","url":""}]},{"id":"s11-218","number":218,"surah":11,"verses":[62],"references":[{"surah":11,"verses":[62]}],"verseLabel":"هود: 62","question":"ما دلالة وصف شك قوم صالح بأنه ﴿مريب﴾؟","answer":"يدل على شك يورث الريبة والقلق ويمنع النفس من الطمأنينة إلى الدعوة، فزاد الوصف تصوير اضطرابهم مع إصرارهم على الرفض.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص270، تحت «غرض وصف الشك بأنه ﴿مريب﴾»","url":""}]},{"id":"s11-111","number":111,"surah":11,"verses":[63],"references":[{"surah":11,"verses":[63]}],"verseLabel":"هود: 63","question":"ما سرّ الاستفهام في قول صالح: ﴿فمن ينصرني من الله إن عصيته﴾؟","answer":"ينكر وجود من يحميه من الله إن عصاه إرضاءً لقومه، فيرد طلبهم إلى ميزان المسؤولية ويبين أن موافقتهم في الشرك خذلان لا نجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص285، تحت «غرض الاستفهام البلاغي»","url":""}]},{"id":"s11-112","number":112,"surah":11,"verses":[64],"references":[{"surah":11,"verses":[64]}],"verseLabel":"هود: 64","question":"ما دلالة إضافة الناقة إلى الله في قوله: ﴿هذه ناقة الله﴾؟","answer":"إضافة تشريف وملكية خاصة؛ لأنها آية خلقها الله على وجه خارق وجعل لها حرمة، لا ملكًا عاديًا للبشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص294، تحت «دلالة التعريف بالإضافة»","url":""}]},{"id":"s11-219","number":219,"surah":11,"verses":[64],"references":[{"surah":11,"verses":[64]}],"verseLabel":"هود: 64","question":"ما دلالة إضافة الأرض إلى الله في قوله: ﴿تأكل في أرض الله﴾؟","answer":"تقرر أن الأرض لله لا لقوم صالح، فلا يملكون منع ناقته من رزق ساقه الله إليها في ملكه الواسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص298، تحت «بديع التعريف بإضافة ﴿أرض﴾ للفظ الجلالة»","url":""}]},{"id":"s11-114","number":114,"surah":11,"verses":[65],"references":[{"surah":11,"verses":[65]}],"verseLabel":"هود: 65","question":"ما غرض الأمر في قوله لقوم صالح: ﴿تمتعوا في داركم﴾؟","answer":"ليس إباحة مطمئنة، بل تهديد ووعيد بأن متاعهم قصير يعقبه العذاب المحتوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص307، تحت «غرض الأمر»","url":""}]},{"id":"s11-220","number":220,"surah":11,"verses":[65],"references":[{"surah":11,"verses":[65]}],"verseLabel":"هود: 65","question":"ما دلالة توقيت عذاب ثمود بثلاثة أيام؟","answer":"يجعل الوعيد قريبًا محسوسًا، فتتحول المهلة المحدودة إلى انتظار يملؤه الخوف والقلق ويقيم الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص309، تحت «دلالة توقيت العذاب»","url":""}]},{"id":"s11-221","number":221,"surah":11,"verses":[65],"references":[{"surah":11,"verses":[65]}],"verseLabel":"هود: 65","question":"ما دلالة وصف الوعد بأنه ﴿غير مكذوب﴾؟","answer":"يؤكد أن الوعيد حق واقع لا خلف فيه ولا كذب، فيقطع طمعهم في النجاة بعد انتهاء المهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص310، تحت «سر الوصف بقوله ﴿غير مكذوب﴾»","url":""}]},{"id":"s11-115","number":115,"surah":11,"verses":[66],"references":[{"surah":11,"verses":[66]}],"verseLabel":"هود: 66","question":"ما دلالة تنكير ﴿رحمة﴾ في قوله: ﴿برحمة منا﴾؟","answer":"يفخم الرحمة التي أحاطت بصالح والمؤمنين؛ فالنجاة فضل عظيم من الله لا استحقاق يلزمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص317، تحت «غرض تنكير ﴿رحمة﴾»","url":""}]},{"id":"s11-222","number":222,"surah":11,"verses":[66],"references":[{"surah":11,"verses":[66]}],"verseLabel":"هود: 66","question":"ما دلالة قوله في نجاة المؤمنين: ﴿ومن خزي يومئذ﴾؟","answer":"يبين أنهم نُجّوا من الذلة والهوان والفضيحة المشهودة مع نجاتهم من الهلاك، فحُفظت سلامتهم وكرامتهم معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص318، تحت «دلالة التعبير بمفردة ﴿خزي﴾»","url":""}]},{"id":"s11-116","number":116,"surah":11,"verses":[67],"references":[{"surah":11,"verses":[67]}],"verseLabel":"هود: 67","question":"ما دلالة أخذ الظالمين بالصيحة؟","answer":"تصور الصيحة عذابًا مباغتًا شديدًا يقطع حركتهم دفعة واحدة ويبرز سرعة نزول العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص327، تحت «فائدة التعبير بالصيحة»","url":""}]},{"id":"s11-223","number":223,"surah":11,"verses":[67],"references":[{"surah":11,"verses":[67]}],"verseLabel":"هود: 67","question":"ما دلالة وصف ثمود بأنهم ﴿في ديارهم جاثمين﴾؟","answer":"يصوّر سكونهم التام وعجزهم عن الحركة والهرب بعد الصيحة، حتى صاروا أجسادًا لا حراك بها في مساكنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص329، تحت «سر التعبير بالجثوم»","url":""}]},{"id":"s11-117","number":117,"surah":11,"verses":[68],"references":[{"surah":11,"verses":[68]}],"verseLabel":"هود: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿كأن لم يغنوا فيها﴾؟","answer":"يصوّر زوالهم التام حتى كأنهم لم يقيموا وينعموا في تلك الديار قط؛ وهو انقلاب يبدد غرور الحضارة الراسخة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص330، تحت «بلاغة التعبير بقوله تعالى ﴿لم يغنوا فيها﴾»","url":""}]},{"id":"s11-118","number":118,"surah":11,"verses":[69],"references":[{"surah":11,"verses":[69]}],"verseLabel":"هود: 69","question":"ما سرّ اختيار المجيء في قوله: ﴿ولقد جاءت رسلنا إبراهيم﴾ دون الإرسال؟","answer":"يستحضر وصول الملائكة إلى إبراهيم ومشهد لقائهم به، مع أنهم مرسلون أصلًا إلى قوم لوط، فيقرب الحدث من الحس.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص337، تحت «سر اختيار لفظ المجيء دون الإرسال»","url":""}]},{"id":"s11-224","number":224,"surah":11,"verses":[69],"references":[{"surah":11,"verses":[69]}],"verseLabel":"هود: 69","question":"ما دلالة قول الله: ﴿جاءت رسلنا إبراهيم بالبشرى﴾؟","answer":"تصوّر الباء البشرى كأنها شيء تحمله الرسل وتجيء به إلى إبراهيم، فتقدم معنى السرور في مشهد اللقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص338، تحت «بلاغة استعمال حرف الباء»","url":""}]},{"id":"s11-119","number":119,"surah":11,"verses":[69],"references":[{"surah":11,"verses":[69]}],"verseLabel":"هود: 69","question":"ما دلالة قوله في ضيافة إبراهيم: ﴿فما لبث أن جاء﴾؟","answer":"ينفي التباطؤ ليصور مبادرته وسرعة إكرامه للضيوف قبل أن يعرف حقيقتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص340، تحت «غرض النفي»","url":""}]},{"id":"s11-225","number":225,"surah":11,"verses":[69],"references":[{"surah":11,"verses":[69]}],"verseLabel":"هود: 69","question":"ما دلالة وصف العجل بأنه ﴿حنيذ﴾؟","answer":"يفيد أنه طعام مشوي مهيأ للضيف، فيصوّر جودة الضيافة وتمام كرم إبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص341، تحت «فائدة التعبير بوصف ﴿حنيذ﴾»","url":""}]},{"id":"s11-120","number":120,"surah":11,"verses":[70],"references":[{"surah":11,"verses":[70]}],"verseLabel":"هود: 70","question":"ما دلالة التعبير عن امتناع الضيوف بقول الله: ﴿رأى أيديهم لا تصل إليه﴾؟","answer":"هو كناية حية عن تركهم الطعام، تعرض المشهد أمام القارئ بدل الاكتفاء بالإخبار أنهم لم يأكلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص346، تحت «بلاغة التعبير بنفي وصول الأيدي إلى العجل»","url":""}]},{"id":"s11-226","number":226,"surah":11,"verses":[70],"references":[{"surah":11,"verses":[70]}],"verseLabel":"هود: 70","question":"ما دلالة عطف ﴿وأوجس منهم خيفة﴾ على ﴿نكرهم﴾؟","answer":"يصوّر تدرج أثر امتناعهم فيه: بدأ باستغراب حالهم ثم تحول إلى خوف أحسه في نفسه وأخفاه إكرامًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص347، تحت «بلاغة عطف الإيجاس على النكارة»","url":""}]},{"id":"s11-121","number":121,"surah":11,"verses":[71],"references":[{"surah":11,"verses":[71]}],"verseLabel":"هود: 71","question":"ما دلالة ذكر ضحك امرأة إبراهيم قبل بشارتها بإسحاق؟","answer":"يفيد زوال الخوف وعودة الطمأنينة، ثم جاءت البشارة عقب ذلك؛ فانتقل المشهد من الخيفة إلى السرور ثم إلى بشارة عظيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص352، تحت «دلالة ذكر الضحك»","url":""}]},{"id":"s11-122","number":122,"surah":11,"verses":[71],"references":[{"surah":11,"verses":[71]}],"verseLabel":"هود: 71","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن وراء إسحاق يعقوب﴾؟","answer":"لم تقتصر البشرى على الولد مع الكبر، بل امتدت إلى الحفيد؛ فضمنت بقاء إسحاق حتى يولد له يعقوب وزادت الطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص353، تحت «براعة التعبير بقوله «ومن وراء»»","url":""}]},{"id":"s11-123","number":123,"surah":11,"verses":[72],"references":[{"surah":11,"verses":[72]}],"verseLabel":"هود: 72","question":"ما دلالة جمع سارة بين قولها: ﴿وأنا عجوز﴾ وقولها: ﴿وهذا بعلي شيخًا﴾؟","answer":"سبب الاستبعاد في نظر العادة مركب من حالهما معًا، فجمعهما يصور شدة دهشتها البشرية أمام القدرة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص361، تحت «براعة اجتماع الحال»","url":""}]},{"id":"s11-124","number":124,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة استفهام الملائكة: ﴿أتعجبين من أمر الله﴾؟","answer":"ينكر استبعادها للخبر ويطمئنها؛ فبيت النبوة الذي عرف آيات الله ورحمته لا يستبعد في حقه خرق العادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص368، تحت «غرض الاستفهام»","url":""}]},{"id":"s11-227","number":227,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة إيثار المضارع في قوله: ﴿أتعجبين﴾؟","answer":"يستحضر تعجبها في لحظته ويصوره متجددًا أمام السامع، فيجيء الإنكار والتطمين مباشرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص369، تحت «نكتة إيثار المضارع على الماضي»","url":""}]},{"id":"s11-228","number":228,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة إضافة الأمر إلى الله في قوله: ﴿من أمر الله﴾؟","answer":"ترد الأمر إلى القدرة الإلهية التي لا تقيدها أسباب العادة، فيزول وجه الاستبعاد مع العلم بأن البشارة من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص370، تحت «دلالة الإضافة»","url":""}]},{"id":"s11-125","number":125,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة مجيء قوله: ﴿رحمت الله وبركاته عليكم أهل البيت﴾ عقب إنكار تعجب سارة؟","answer":"يعلل زوال العجب بأن ما بُشرت به امتداد لرحمات وبركات عرفها هذا البيت النبوي، لا حادثًا بعيدًا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص370، تحت «براعة موقع الجمل من السابق»","url":""}]},{"id":"s11-229","number":229,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة تقديم الرحمة على البركة في خطاب أهل بيت إبراهيم؟","answer":"الرحمة أصل الإنعام والرعاية، والبركات آثارها المتكاثرة؛ فقدم الأصل ثم أتبع بما يتفرع عنه من الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص371، تحت «فائدة تقديم الرحمة على البركة»","url":""}]},{"id":"s11-230","number":230,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة اجتماع وصفي ﴿حميد مجيد﴾ في ختام بشارة أهل بيت إبراهيم؟","answer":"يجمع الحمد على النعم والمجد الدال على سعة العظمة والكرم؛ فيناسب مقام الرحمة والبركة والبشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص375، تحت «بلاغة اجتماع وصفي ﴿حميد مجيد﴾»","url":""}]},{"id":"s11-126","number":126,"surah":11,"verses":[74],"references":[{"surah":11,"verses":[74]}],"verseLabel":"هود: 74","question":"ما دلالة التعبير عن مراجعة إبراهيم في قوم لوط بالمجادلة دون المحاورة؟","answer":"تفيد المجادلة شدة مراجعته رجاء تأخير العذاب لوجود مؤمنين أو إمهال القوم للتوبة، وكان دافعها حلمه ورحمته بعد زوال الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص386، تحت «دلالة استعمال مفردة المجادلة دون المحاورة»","url":""}]},{"id":"s11-127","number":127,"surah":11,"verses":[75],"references":[{"surah":11,"verses":[75]}],"verseLabel":"هود: 75","question":"ما دلالة وصف إبراهيم بأنه ﴿حليم أواه منيب﴾ في سياق مجادلته في قوم لوط؟","answer":"الحلم يفسر رفقه بالمعاندين، والأواه رقة قلبه، والإنابة رجوعه إلى الله؛ فترتيب الصفات يكشف منابع مجادلته الرحيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص391، تحت «بلاغة اجتماع الأوصاف وترتيبها»","url":""}]},{"id":"s11-128","number":128,"surah":11,"verses":[76],"references":[{"surah":11,"verses":[76]}],"verseLabel":"هود: 76","question":"لماذا قيل لإبراهيم: ﴿أعرض عن هذا﴾ بدل النهي عن الجدال؟","answer":"لأن الرحمة التي دفعته إلى المراجعة محمودة، وإنما طُلب منه أن يصرف نفسه عن أمر انتهى حكمه بعد قيام الحجة ومجيء أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص394، تحت «سر الأمر بالإعراض دون النهي عن الجدال»","url":""}]},{"id":"s11-231","number":231,"surah":11,"verses":[76],"references":[{"surah":11,"verses":[76]}],"verseLabel":"هود: 76","question":"ما دلالة وصف عذاب قوم لوط بأنه ﴿غير مردود﴾ في سياق مجادلة إبراهيم؟","answer":"يقطع الرجاء في دفعه بعد أن بلغ الحكم نهايته؛ فصار استمرار المجادلة بلا محل مهما كان باعثها الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص399، تحت «نكتة وصف العذاب في سياق المجادلة»","url":""}]},{"id":"s11-129","number":129,"surah":11,"verses":[77],"references":[{"surah":11,"verses":[77]}],"verseLabel":"هود: 77","question":"ما دلالة عطف ﴿وضاق بهم ذرعًا﴾ على ﴿سيء بهم﴾؟","answer":"يجمع أثرين متتابعين: ساءه مجيئهم لما خشي عليهم، ثم ضاق بعجزه عن حمايتهم؛ فاجتمع ألم النفس وقلة الحيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص406، تحت «فائدة العطف»","url":""}]},{"id":"s11-232","number":232,"surah":11,"verses":[77],"references":[{"surah":11,"verses":[77]}],"verseLabel":"هود: 77","question":"ما الصورة التي يرسمها التعبير: ﴿وضاق بهم ذرعًا﴾؟","answer":"يمثل حال لوط وقد عجزت قدرته عن حمايتهم بحال من ضاق مدى ذراعه عن بلوغ ما يريد، فيصور شدة الحرج وقلة الحيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص406، تحت «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s11-130","number":130,"surah":11,"verses":[78],"references":[{"surah":11,"verses":[78]}],"verseLabel":"هود: 78","question":"ما سرّ ذكر لوط النساء باسم البنات في قوله: ﴿هؤلاء بناتي﴾؟","answer":"دعا قومه إلى النساء بطريق الزواج المشروع، وقيل أراد نساء قومه لأن النبي في مقام الأب لهم؛ فصرفهم من الفاحشة إلى الحلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص420، تحت «فائدة ذكر النساء باسم البنات»","url":""}]},{"id":"s11-233","number":233,"surah":11,"verses":[78],"references":[{"surah":11,"verses":[78]}],"verseLabel":"هود: 78","question":"ما دلالة قوله: ﴿هن أطهر لكم﴾ مع أن الفاحشة لا طهارة فيها؟","answer":"ليس المراد مشاركة الطريقين في الطهر، بل بيان أن الزواج هو الطريق الطاهر وحده، فجاء اسم التفضيل للحث الشديد على العدول إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص424، تحت «نكتة مجيء اسم التفضيل مع انتفاء المفاضلة»","url":""}]},{"id":"s11-131","number":131,"surah":11,"verses":[78],"references":[{"surah":11,"verses":[78]}],"verseLabel":"هود: 78","question":"ما دلالة الاستفهام في قول لوط: ﴿أليس منكم رجل رشيد﴾؟","answer":"يستنكر خلو هذا الجمع ممن يردهم عن الفاحشة وفضيحة الضيف، ويوقظ ما بقي فيهم من فطرة وعقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص428، تحت «غرض الاستفهام»","url":""}]},{"id":"s11-234","number":234,"surah":11,"verses":[78],"references":[{"surah":11,"verses":[78]}],"verseLabel":"هود: 78","question":"ما دلالة تنكير ﴿رجل﴾ ووصفه بـ﴿رشيد﴾ في قول لوط؟","answer":"يفيد أنه كان يطلب أي رجل، ولو واحدًا، يملك رشدًا يرده وقومه عن المنكر؛ وفي ذلك تصوير لشدة فساد الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص429، تحت «غرض التنكير وسر الوصف»","url":""}]},{"id":"s11-132","number":132,"surah":11,"verses":[79],"references":[{"surah":11,"verses":[79]}],"verseLabel":"هود: 79","question":"ما دلالة التوكيد في قول قوم لوط: ﴿لقد علمت ما لنا في بناتك من حق﴾؟","answer":"يصرح بإصرارهم على رفض الحلال، ويزعمون أن مقصدهم معلوم لا يحتاج نقاشًا؛ فبلغت مجاهرتهم غايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص429، تحت «غرض التوكيد»","url":""}]},{"id":"s11-235","number":235,"surah":11,"verses":[79],"references":[{"surah":11,"verses":[79]}],"verseLabel":"هود: 79","question":"ما دلالة قول قوم لوط: ﴿لقد علمت﴾ بدل الإخبار المباشر برفضهم؟","answer":"احتجوا بعلمه السابق بحالهم ليغلقوا باب المراجعة، كأن مقصدهم مقرر لا يخفى ولا يتغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص430، تحت «دلالة استعمال لفظ العلم مادة وصيغة»","url":""}]},{"id":"s11-236","number":236,"surah":11,"verses":[79],"references":[{"surah":11,"verses":[79]}],"verseLabel":"هود: 79","question":"عمّ كنّى قوم لوط بقولهم: ﴿وإنك لتعلم ما نريد﴾؟","answer":"كنوا عن الفاحشة التي يقصدونها، لكن الكناية هنا لا تستر قبحهم بل تكشف مجاهرتهم بالمقصد حتى جعلوه معلومًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص431، تحت «بلاغة الكناية»","url":""}]},{"id":"s11-133","number":133,"surah":11,"verses":[80],"references":[{"surah":11,"verses":[80]}],"verseLabel":"هود: 80","question":"ما سرّ تمني لوط قوة أو ركنًا شديدًا؟","answer":"نطق بها في لحظة استضعاف طلبًا لوسيلة تحمي ضيوفه، مع أن ركنه الحقيقي كان الله؛ ولذلك كشفت الملائكة فورًا أنهم رسل ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص433–436، تحت «غرض استعمال «لو»؛ فائدة التقديم والتأخير؛ بلاغة الاستعارة التصريحية»","url":""}]},{"id":"s11-134","number":134,"surah":11,"verses":[81],"references":[{"surah":11,"verses":[81]}],"verseLabel":"هود: 81","question":"ما سرّ التعبير بـ﴿بقطع من الليل﴾ في أمر لوط بالخروج بأهله؟","answer":"الليل أستر للخروج وأبعد عن ملاحقة القوم، والقطع جزء منه؛ فالتعبير يرسم نجاة خفية قبل حلول الصبح.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص449، تحت «بلاغة التعبير «بقطع من الليل» دون «في الليل»»","url":""}]},{"id":"s11-135","number":135,"surah":11,"verses":[81],"references":[{"surah":11,"verses":[81]}],"verseLabel":"هود: 81","question":"ما دلالة النهي في قوله تعالى: ﴿ولا يلتفت منكم أحد﴾؟","answer":"ليقطعوا صلتهم النفسية والمكانية ببلد العذاب، ويمضوا إلى النجاة بلا تباطؤ أو تحسر على ما تركوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص450، تحت «غرض النهي»","url":""}]},{"id":"s11-136","number":136,"surah":11,"verses":[81],"references":[{"surah":11,"verses":[81]}],"verseLabel":"هود: 81","question":"ما سرّ إيثار لفظ ﴿الصبح﴾ على الفجر في تحديد موعد عذاب قوم لوط؟","answer":"الصبح زمن انكشاف الضوء ووضوح الأشياء، فناسب ظهور العذاب وتمام النجاة، وفيه تطمين بأن الموعد قد دنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص454، تحت «سر إيثار الصبح على الفجر»","url":""}]},{"id":"s11-237","number":237,"surah":11,"verses":[81],"references":[{"surah":11,"verses":[81]}],"verseLabel":"هود: 81","question":"ما دلالة الاستفهام في قوله: ﴿أليس الصبح بقريب﴾؟","answer":"يقرر قرب الموعد ويطمئن لوطًا بأن الخلاص قد دنا، وقد يحمل كذلك على الحث على الإسراع في الخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص455، تحت «غرض الاستفهام»","url":""}]},{"id":"s11-137","number":137,"surah":11,"verses":[82],"references":[{"surah":11,"verses":[82]}],"verseLabel":"هود: 82","question":"ما دلالة التعبير بالجعل في قوله: ﴿جعلنا عاليها سافلها﴾؟","answer":"يصوّر تحويلًا حقيقيًا تامًا لحال القرى، ويبرز قدرة الله على قلب نظامها الذي استقر عليه أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص462، تحت «سر التعبير بالجعل»","url":""}]},{"id":"s11-238","number":238,"surah":11,"verses":[82],"references":[{"surah":11,"verses":[82]}],"verseLabel":"هود: 82","question":"ما دلالة التعبير بـ﴿عاليها﴾ و﴿سافلها﴾ في عذاب قوم لوط؟","answer":"يرسم انقلاب القرى من أعلاها إلى أسفلها، ويهوّل الإهانة إذ صارت مواضع استقرارهم مقلوبة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص463، تحت «نكتة التعبير بـ﴿عاليها﴾ و﴿سافلها﴾»","url":""}]},{"id":"s11-138","number":138,"surah":11,"verses":[82],"references":[{"surah":11,"verses":[82]}],"verseLabel":"هود: 82","question":"ما دلالة وصف الحجارة بأنها ﴿من سجيل منضود﴾؟","answer":"يبرز «سجيل»، على تفسيره الذي رجحه المصدر، صلابة الحجارة وشدتها، فهي من طين تحجر فاشتد. ويصور «منضود» كثرتها وإعدادها وتتابع بعضها إثر بعض، فيكتمل به تصوير هول العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص467–468، تحت «إيثار لفظ «سجيل» في وصف الحجارة؛ دلالة وصف «سجيل» بـ«منضود»»","url":""}]},{"id":"s11-139","number":139,"surah":11,"verses":[83],"references":[{"surah":11,"verses":[83]}],"verseLabel":"هود: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿مسومة عند ربك﴾؟","answer":"أي معلَّمة أو مقدرة لمستحقيها، فتبدو العقوبة دقيقة لا عشوائية؛ كل حجر يجري بعلم وتقدير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص468–469، تحت «سر التعبير بـ«مسومة»؛ دلالة الكناية في «مسومة»؛ دلالة التعبير بالظرفية «عند»»","url":""}]},{"id":"s11-140","number":140,"surah":11,"verses":[83],"references":[{"surah":11,"verses":[83]}],"verseLabel":"هود: 83","question":"ما دلالة ختم قصة لوط بقوله تعالى: ﴿وما هي من الظالمين ببعيد﴾؟","answer":"يحول القصة إلى تهديد دائم لكل من يشابههم في الظلم؛ فالعبرة ليست محصورة في قوم مضوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص471–472، 474، تحت «نكتة التعبير بالإضمار في «وما هي»؛ علة اختيار وصف الظالمين؛ دلالة ختام قصة لوط»","url":""}]},{"id":"s11-141","number":141,"surah":11,"verses":[84],"references":[{"surah":11,"verses":[84]}],"verseLabel":"هود: 84","question":"ما سرّ التعبير في قوله تعالى في شعيب: ﴿أخاهم شعيبًا﴾؟","answer":"يكرر قرب الرسول من قومه ومعرفته بأحوالهم، فلا عذر لهم بدعوى الغربة؛ وقد واجه فساد عبادتهم ومعاملاتهم معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص481–482، 487، تحت «سر التعبير بالأخوة في «أخاهم»؛ دلالة الإضافة في «أخاهم»؛ أسلوب القرآن في عرض أصول دعوة شعيب»","url":""}]},{"id":"s11-142","number":142,"surah":11,"verses":[84],"references":[{"surah":11,"verses":[84]}],"verseLabel":"هود: 84","question":"ما دلالة الجمع بين التوحيد والنهي عن نقص المكيال والميزان في دعوة شعيب؟","answer":"يبين أن الدين لا ينفصل عن السوق؛ فمن عبد الله لزمه العدل في أموال الناس، وإلا ناقضت معاملته عقيدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص487، تحت «أسلوب القرآن في عرض أصول دعوة شعيب»","url":""}]},{"id":"s11-143","number":143,"surah":11,"verses":[84],"references":[{"surah":11,"verses":[84]}],"verseLabel":"هود: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿إني أراكم بخير﴾ ثم خوّفهم العذاب؟","answer":"كانوا في سعة تغنيهم عن الغش، فصار التطفيف أشد قبحًا؛ كما أن الخير القائم قد يزول بعذاب محيط إن كفروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص491–494، تحت «دلالة الفصل في «إني أراكم بخير»؛ سر التعبير بـ«خير»؛ بلاغة الإجمال في «عذاب يوم محيط»»","url":""}]},{"id":"s11-144","number":144,"surah":11,"verses":[85],"references":[{"surah":11,"verses":[85]}],"verseLabel":"هود: 85","question":"لماذا أُمر قوم شعيب بإيفاء المكيال والميزان بعد نهيهم عن النقص؟","answer":"لأن ترك النقص لا يكفي حتى يتحول إلى أداء إيجابي كامل للحقوق؛ فجمع السياق بين إزالة الظلم وإقامة العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص500، تحت «علة الأمر بالإيفاء بعد النهي عن النقص»","url":""}]},{"id":"s11-239","number":239,"surah":11,"verses":[85],"references":[{"surah":11,"verses":[85]}],"verseLabel":"هود: 85","question":"ما دلالة تقييد إيفاء المكيال والميزان بـ﴿القسط﴾؟","answer":"يبين أن المطلوب إتمام الحقوق على وجه العدل والتسوية، لا مجرد زيادة ظاهرية أو وفاء يخالطه ميل وجور.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص501، تحت «دلالة لفظ القسط»","url":""}]},{"id":"s11-145","number":145,"surah":11,"verses":[85],"references":[{"surah":11,"verses":[85]}],"verseLabel":"هود: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تعثوا في الأرض مفسدين﴾؟","answer":"العثو فساد شديد منتشر، والحال ﴿مفسدين﴾ تكشف أن حركتهم في الأرض تحولت إلى صناعة فساد لا خطأ عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص504–505، 507، تحت «سر التعبير بـ«ولا تعثوا»؛ سر التعبير بالاسمية «مفسدين»؛ بلاغة التأكيد في «ولا تعثوا في الأرض مفسدين»»","url":""}]},{"id":"s11-146","number":146,"surah":11,"verses":[86],"references":[{"surah":11,"verses":[86]}],"verseLabel":"هود: 86","question":"ما دلالة التعبير بـ﴿بقية الله﴾ في قوله تعالى: ﴿بقية الله خير لكم﴾؟","answer":"ما يبقيه الله لكم من الربح الحلال بعد ترك التطفيف خير من الزيادة المحرمة، ويدخل فيه ثواب الطاعة الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص514–516، تحت «سر التعبير بلفظ «بقية»؛ دلالة الإضافة «بقية الله»؛ دلالة التعبير بقوله «خير»»","url":""}]},{"id":"s11-148","number":148,"surah":11,"verses":[87],"references":[{"surah":11,"verses":[87]}],"verseLabel":"هود: 87","question":"ما دلالة قول قوم شعيب: ﴿أصلاتك تأمرك أن نترك ما يعبد آباؤنا أو أن نفعل في أموالنا ما نشاء﴾؟","answer":"ساقوا السؤال للسخرية من شعيب وصلاته، واعترضوا على دعوته في أصلين: ترك عبادة الآباء، وترك التصرف الظالم في المال. وإسناد الأمر إلى الصلاة يربط عبادته بما يدعو إليه؛ فقد كانت عنوان إيمانه وتقواه ودافعًا إلى إصلاح الاعتقاد والمعاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص524–525، 529–531، تحت «دلالة الاستفهام في «أصلاتك»؛ سر اختيارهم للصلاة؛ بلاغة المجاز العقلي في «أصلاتك تأمرك»؛ سر الجمع بين عدم الترك وحرية التصرف»","url":""}]},{"id":"s11-149","number":149,"surah":11,"verses":[87],"references":[{"surah":11,"verses":[87]}],"verseLabel":"هود: 87","question":"ما دلالة وصف قوم شعيب له بقولهم: ﴿إنك لأنت الحليم الرشيد﴾؟","answer":"يحتمل التهكم وإرادة الضد، ويحتمل اعترافهم بما عرفوه من حلمه ورشده ثم احتجاجهم بهما عليه؛ وفي الوجهين تكشف العبارة اعتراضهم لا حجة تبطل دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص532، تحت «علة الوصف بـ﴿الحليم الرشيد﴾»","url":""}]},{"id":"s11-150","number":150,"surah":11,"verses":[88],"references":[{"surah":11,"verses":[88]}],"verseLabel":"هود: 88","question":"ما دلالة النفي في قول شعيب: ﴿وما أريد أن أخالفكم إلى ما أنهاكم عنه﴾؟","answer":"يعلن اتساق قوله وعمله وينفي أصل قصده إلى فعل ما ينهى عنه؛ فمصداقية المصلح تبدأ من نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص550، تحت «بلاغة أسلوب النفي»","url":""}]},{"id":"s11-240","number":240,"surah":11,"verses":[88],"references":[{"surah":11,"verses":[88]}],"verseLabel":"هود: 88","question":"ما دلالة اختيار فعل ﴿أخالفكم﴾ في كلام شعيب؟","answer":"يصور أن يفعل المصلح من وراء قومه ما نهاهم عنه كأنه يتجه إلى الجهة المخالفة لهم؛ فنفى عن نفسه ازدواج القول والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص551، تحت «سر اختيار فعل ﴿أخالفكم﴾»","url":""}]},{"id":"s11-151","number":151,"surah":11,"verses":[88],"references":[{"surah":11,"verses":[88]}],"verseLabel":"هود: 88","question":"ما دلالة القصر في قول شعيب: ﴿إن أريد إلا الإصلاح﴾؟","answer":"حصر قصده في الإصلاح، فنفى عن دعوته كل غرض شخصي وأثبت أنه لا يريد إلا صلاح قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص553، تحت «دلالة أسلوب القصر»","url":""}]},{"id":"s11-241","number":241,"surah":11,"verses":[88],"references":[{"surah":11,"verses":[88]}],"verseLabel":"هود: 88","question":"لماذا قيّد شعيب إرادته الإصلاح بقوله: ﴿ما استطعت﴾؟","answer":"اعترافًا بحدود القدرة البشرية وتواضعًا؛ فهو يبذل ما يقدر عليه ولا يدعي إصلاحًا يتجاوز استطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص555، تحت «سر التعبير بالاستطاعة»","url":""}]},{"id":"s11-242","number":242,"surah":11,"verses":[88],"references":[{"surah":11,"verses":[88]}],"verseLabel":"هود: 88","question":"ما دلالة قول شعيب: ﴿وما توفيقي إلا بالله﴾؟","answer":"احتراس من توهم استقلاله بقدرته؛ فالنية والسعي منه، أما إصابة الحق وتمام الأثر فبتوفيق الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص556، تحت «بلاغة الاحتراس في «وما توفيقي إلا بالله»»","url":""}]},{"id":"s11-152","number":152,"surah":11,"verses":[89],"references":[{"surah":11,"verses":[89]}],"verseLabel":"هود: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يجرمنكم شقاقي﴾؟","answer":"المعنى: لا تجعلوا عداوتكم لي سببًا للإعراض عن الدعوة والإصرار على الباطل، فيصيبكم مثل ما أصاب الأمم المكذبة. وصوّر الشقاق كأنه يكسبهم العذاب، تنبيهًا إلى أن خصومتهم للرسول تضرهم هم بعاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص565–567، تحت «توجيه التعبير بقوله «لا يجرمنكم»؛ غرض النهي وبلاغة مجازه؛ معنى الإضافة ودلالتها»","url":""}]},{"id":"s11-153","number":153,"surah":11,"verses":[89],"references":[{"surah":11,"verses":[89]}],"verseLabel":"هود: 89","question":"ما دلالة ختم تعداد الأمم بقوله تعالى: ﴿وما قوم لوط منكم ببعيد﴾؟","answer":"لأنهم قريبون زمانًا أو مكانًا ومعرفةً، وآثارهم أمامهم؛ فالحجة الأقرب أشد إيقاظًا من أخبار بعيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص573، تحت «نكتة التعبير «ببعيد»»","url":""}]},{"id":"s11-154","number":154,"surah":11,"verses":[90],"references":[{"surah":11,"verses":[90]}],"verseLabel":"هود: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿إن ربي رحيم ودود﴾ بعد الاستغفار والتوبة؟","answer":"جمع الوصفان سعة الرحمة والمغفرة مع المحبة والإحسان إلى التائب. فجاء الختام تعليلًا للدعوة إلى الاستغفار والتوبة، وترغيبًا فيها، حتى لا يحملهم ما سبق من ذنوبهم على اليأس من قبول الله ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص582، تحت «الجمع بين وصفي «رحيم ودود»»","url":""}]},{"id":"s11-155","number":155,"surah":11,"verses":[91],"references":[{"surah":11,"verses":[91]}],"verseLabel":"هود: 91","question":"ما سرّ تعبير قوم شعيب بـ﴿ما نفقه كثيرًا مما تقول﴾ بدلًا من «لا نفهم»؟","answer":"الفقه فهم عميق يأتي بعد تأمل؛ فاختياره يزيد التعريض بكلام شعيب، وكأنهم يدّعون أنه لا يستحق هذا النظر أو لا يفهم مع إعماله. ولم يكن كلامه غامضًا؛ وإنما كشف النفي عن إعراضهم وعدم تصديقهم، ثم أسندوه إلى جماعتهم لتقوية الاعتراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص588، 596، تحت «دلالة النفي بـ«ما»؛ نكتة إسناد نفي الفقه للجميع؛ الفقه والفهم»","url":""}]},{"id":"s11-156","number":156,"surah":11,"verses":[91],"references":[{"surah":11,"verses":[91]}],"verseLabel":"هود: 91","question":"ما دلالة قول قوم شعيب: ﴿ولولا رهطك لرجمناك﴾؟","answer":"صرحوا بأن المانع من رجمه مراعاة قرابته الباقين على دينهم. ولفظ «رهطك» يدل على قلة هذه الجماعة؛ فلم يكن امتناعهم إقرارًا بحقه أو احترامًا لدعوته، بل إكرامًا لرهطه الموافقين لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص591–592، 596، تحت «سر التعبير بـ«لولا»؛ سر التعبير بالرهط دون القوم؛ بلاغة التذييل»","url":""}]},{"id":"s11-157","number":157,"surah":11,"verses":[92],"references":[{"surah":11,"verses":[92]}],"verseLabel":"هود: 92","question":"ما سرّ التعبير في قول شعيب: ﴿أرهطي أعز عليكم من الله﴾؟","answer":"فضح انقلاب ميزانهم: راعوا رهطه الضعيف ولم يراعوا الله القادر، فجعلوا حرمة القبيلة فوق حرمة الرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص603، تحت «غرض التعبير بصيغة المفاضلة «أعز»»","url":""}]},{"id":"s11-158","number":158,"surah":11,"verses":[92],"references":[{"surah":11,"verses":[92]}],"verseLabel":"هود: 92","question":"ما دلالة ﴿واتخذتموه وراءكم ظهريًا﴾؟","answer":"كناية عن الإهمال والنبذ؛ صوّرتهم كمن يطرح أمر الله خلف ظهره فلا يلتفت إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص605، تحت «بلاغة الكناية»","url":""}]},{"id":"s11-243","number":243,"surah":11,"verses":[92],"references":[{"surah":11,"verses":[92]}],"verseLabel":"هود: 92","question":"ما دلالة وصف الله بأنه ﴿بما تعملون محيط﴾؟","answer":"يدل على إحاطة علمه وقدرته بأعمالهم إحاطة لا يفلت منها شيء، وفيه وعيد لمن نبذ أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص608، تحت «قوله تعالى «محيط» بين المجاز والاستعارة»","url":""}]},{"id":"s11-160","number":160,"surah":11,"verses":[94],"references":[{"surah":11,"verses":[94]}],"verseLabel":"هود: 94","question":"ما دلالة قوله: ﴿نجينا شعيبًا والذين آمنوا معه برحمة منا﴾؟","answer":"نسب النجاة إلى رحمة الله لا إلى الاستحقاق المجرد، ليظل المؤمن شاكرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص634، تحت «بلاغة التعبير المجازي بالرحمة»","url":""}]},{"id":"s11-244","number":244,"surah":11,"verses":[94],"references":[{"surah":11,"verses":[94]}],"verseLabel":"هود: 94","question":"ما دلالة قوله: ﴿وأخذت الذين ظلموا الصيحة﴾؟","answer":"صوّر الصيحة كقوة استولت عليهم وأحاطت بهم فلم يستطيعوا منها فرارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص635، تحت «نكتة إسناد فعل الأخذ للصيحة»","url":""}]},{"id":"s11-161","number":161,"surah":11,"verses":[95],"references":[{"surah":11,"verses":[95]}],"verseLabel":"هود: 95","question":"ما دلالة تكرار ﴿كأن لم يغنوا فيها﴾ في ختام قصتي ثمود ومدين؟","answer":"تلتقي العبارتان في تصوير الاستئصال: زال القوم حتى صاروا كأنهم لم يقيموا في ديارهم ولم ينعموا بعيشها. فالتشبيه يجمع المصيرين في صورة واحدة، ويجعل ما عرفوه من عمران ورخاء شاهدًا على شدة ما نزل بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص330، تحت «بلاغة التشبيه»","url":""}]},{"id":"s11-162","number":162,"surah":11,"verses":[96],"references":[{"surah":11,"verses":[96]}],"verseLabel":"هود: 96","question":"لماذا عبّر عن معجزات موسى بلفظ ﴿آياتنا﴾؟","answer":"لأنها علامات بينات تدل على صدقه وقدرة مرسلها، فلا تقف دلالتها عند خرق العادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص649، تحت «سر التعبير بالآيات دون المعجزات»","url":""}]},{"id":"s11-245","number":245,"surah":11,"verses":[96],"references":[{"surah":11,"verses":[96]}],"verseLabel":"هود: 96","question":"ما سر وصف حجة موسى بأنها ﴿سلطان مبين﴾؟","answer":"لأن الحجة الواضحة تتسلط على الباطل وتظهر عليه، فيبرز اللفظ قوتها وقهرها للشبهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص651، تحت «سر التعبير بالسلطان عن الحجة»","url":""}]},{"id":"s11-163","number":163,"surah":11,"verses":[97],"references":[{"surah":11,"verses":[97]}],"verseLabel":"هود: 97","question":"ما دلالة قوله عن قوم فرعون: ﴿فاتبعوا أمر فرعون﴾؟","answer":"يصوّر انقيادهم لقيادته مع وضوح آيات موسى، فيحمّلهم تبعة اختيار طريق الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص654، تحت «دلالة ذكر لفظ الاتباع»","url":""}]},{"id":"s11-246","number":246,"surah":11,"verses":[97],"references":[{"surah":11,"verses":[97]}],"verseLabel":"هود: 97","question":"لماذا قال: ﴿وما أمر فرعون برشيد﴾ بدل التصريح بسفهه؟","answer":"نفي الرشد يوبخ من اتبعوه؛ فقد تبعوا أمرًا لا يقود إلى صلاح أو نجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص656، تحت «سر نفي الرشد دون إثبات السفه»","url":""}]},{"id":"s11-164","number":164,"surah":11,"verses":[98],"references":[{"surah":11,"verses":[98]}],"verseLabel":"هود: 98","question":"ما سرّ التعبير في قوله تعالى عن فرعون: ﴿يقدم قومه يوم القيامة فأوردهم النار﴾؟","answer":"كما قادهم في الدنيا إلى الضلال يتقدمهم في الآخرة إلى نتيجته؛ فقلب صورة الزعيم الذي يوصل قومه إلى الموارد إلى قائد يوردهم النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص662–663، 665–666، تحت «نكتة إيثار لفظ «يقدم»؛ نكتة إيثار صيغة المضارع؛ بلاغة الاستعارة التهكمية»","url":""}]},{"id":"s11-165","number":165,"surah":11,"verses":[99],"references":[{"surah":11,"verses":[99]}],"verseLabel":"هود: 99","question":"ما سرّ تسمية اللعنة ﴿رفدًا﴾ في قوله تعالى: ﴿بئس الرفد المرفود﴾؟","answer":"الرفد عادة عطاء ومعونة، فاستعمل تهكمًا: عطاؤهم المتتابع لعنة في الدنيا ثم لعنة في الآخرة، وبئس العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص675، تحت «بلاغة الاستعارة التهكمية»","url":""}]},{"id":"s11-166","number":166,"surah":11,"verses":[100],"references":[{"surah":11,"verses":[100]}],"verseLabel":"هود: 100","question":"ما سرّ التعبير في قوله تعالى عن القرى: ﴿منها قائم وحصيد﴾؟","answer":"شبه آثارها بزرع: منه ما بقي قائمًا يراه الناس، ومنه ما استؤصل كالحصيد؛ وفي الحالتين تشهد البقايا أو الفراغ بالمصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص683، تحت «بلاغة الاستعارة التصريحية»","url":""}]},{"id":"s11-167","number":167,"surah":11,"verses":[101],"references":[{"surah":11,"verses":[101]}],"verseLabel":"هود: 101","question":"ما دلالة قوله: ﴿فما أغنت عنهم آلهتهم... من شيء﴾؟","answer":"عمّم نفي النفع، فلا تدفع آلهتهم عنهم قليلًا من العذاب ولا كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص689، تحت «بلاغة العموم»","url":""}]},{"id":"s11-247","number":247,"surah":11,"verses":[101],"references":[{"surah":11,"verses":[101]}],"verseLabel":"هود: 101","question":"ما دلالة قوله: ﴿وما زادوهم غير تتبيب﴾؟","answer":"زادهم تعلقهم بآلهتهم خسارًا وهلاكًا؛ لأن رجاء نصرتها صدّهم عن التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص691، تحت «توجيه استعمال «تتبيب» في سياقها»","url":""}]},{"id":"s11-168","number":168,"surah":11,"verses":[102],"references":[{"surah":11,"verses":[102]}],"verseLabel":"هود: 102","question":"ما دلالة قوله: ﴿وكذلك أخذ ربك إذا أخذ القرى وهي ظالمة﴾؟","answer":"شبّه أخذ كل قرية ظالمة بما قصه من أخذ الأمم، ليعمم العبرة ويؤكد ثبات سنة العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص696، تحت «غرض التشبيه في الآية»","url":""}]},{"id":"s11-248","number":248,"surah":11,"verses":[102],"references":[{"surah":11,"verses":[102]}],"verseLabel":"هود: 102","question":"ما دلالة الجمع بين ﴿أليم﴾ و﴿شديد﴾؟","answer":"الأليم يبرز وجع العذاب، والشديد يبرز قوته وصعوبة الخلاص منه؛ فاجتماعهما أبلغ في التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص699، تحت «نكتة الجمع بين صفتي الألم والشدة»","url":""}]},{"id":"s11-169","number":169,"surah":11,"verses":[103],"references":[{"surah":11,"verses":[103]}],"verseLabel":"هود: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿إن في ذلك لآية لمن خاف عذاب الآخرة﴾؟","answer":"المنتفع بالتاريخ هو من يرى وراء هلاك الدنيا حسابًا أكبر؛ أما من لا يخاف الآخرة فقد يشاهد الآثار ولا يعتبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص705، تحت «سر إيثار لفظ الخوف»","url":""}]},{"id":"s11-170","number":170,"surah":11,"verses":[103],"references":[{"surah":11,"verses":[103]}],"verseLabel":"هود: 103","question":"ما دلالة وصف يوم القيامة بأنه ﴿يوم مجموع له الناس﴾ و﴿يوم مشهود﴾؟","answer":"«مجموع له الناس» يؤكد ثبوت جمع الخلائق لأجل الحساب، و«مشهود» يبرز كثرة من يحضرون هذا الموقف وهوله. فتجتمع في الوصفين حتمية الجمع وعظمة المشهد الذي لا يغيب عنه أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص708، تحت «دلالة استعمال صيغة المفعول»","url":""}]},{"id":"s11-171","number":171,"surah":11,"verses":[104],"references":[{"surah":11,"verses":[104]}],"verseLabel":"هود: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿وما نؤخره إلا لأجل معدود﴾؟","answer":"يبين القصر أن تأخير القيامة إنما هو إلى وقت معلوم حدده الله، فلا يصح اتخاذ التأخير دليلًا على نفي البعث. ووصف الأجل بأنه «معدود» يؤكد ضبط مدته وانتهاءها بلا زيادة ولا نقصان.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص710، تحت «نكتة إيثار لفظ «معدود»»","url":""}]},{"id":"s11-172","number":172,"surah":11,"verses":[105],"references":[{"surah":11,"verses":[105]}],"verseLabel":"هود: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تكلم نفس إلا بإذنه﴾؟","answer":"يسقط كل وهم في الاحتجاج أو الشفاعة المستقلة؛ حتى الكلام في ذلك الموقف خاضع لسلطان الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص716–718، تحت «فائدة الاستئناف في قوله «لا تكلم»؛ سر تنكير «نفس»؛ توجيه الاستثناء»","url":""}]},{"id":"s11-173","number":173,"surah":11,"verses":[105],"references":[{"surah":11,"verses":[105]}],"verseLabel":"هود: 105","question":"ما دلالة تقسيم الناس إلى ﴿شقي وسعيد﴾ قبل تفصيل حال الفريقين؟","answer":"لخّص المصير النهائي بعد انقضاء زمن العمل: فريق بلغ الشقاء وفريق نال السعادة، ثم فصل حال كل منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص723، تحت «بديع التقسيم»","url":""}]},{"id":"s11-174","number":174,"surah":11,"verses":[106],"references":[{"surah":11,"verses":[106]}],"verseLabel":"هود: 106","question":"ما دلالة وصف أهل النار بأن لهم فيها ﴿زفير وشهيق﴾؟","answer":"يصوّر ذكر الزفير والشهيق شدة الكرب واضطراب التنفس من الألم. والجمع بين إخراج النفس وإدخاله يبرز استمرار الحياة مع العذاب، ويجعل المشهد أوقع في التحذير وأشد تنفيرًا من أسبابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص725، تحت «توجيه تخصيص الزفير والشهيق بالذكر»","url":""}]},{"id":"s11-176","number":176,"surah":11,"verses":[108],"references":[{"surah":11,"verses":[108]}],"verseLabel":"هود: 108","question":"ما دلالة ختم نعيم الجنة بقوله تعالى: ﴿عطاء غير مجذوذ﴾؟","answer":"﴿غير مجذوذ﴾ أي غير مقطوع؛ فجاءت العبارة لتزيل أي توهم يولده الاستثناء السابق في انقطاع نعيمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص733، تحت «إيثار لفظ «مجذوذ» دون لفظ مقطوع»","url":""}]},{"id":"s11-177","number":177,"surah":11,"verses":[109],"references":[{"surah":11,"verses":[109]}],"verseLabel":"هود: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تك في مرية مما يعبد هؤلاء﴾؟","answer":"ليس نهيًا عن الشك في وقوع عبادتهم، بل عن الارتياب في بطلانها ومصيرها؛ فهم يقلدون آباءهم وسينالون نصيبهم كاملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص739، تحت «فائدة النهي عن الامتراء»","url":""}]},{"id":"s11-178","number":178,"surah":11,"verses":[109],"references":[{"surah":11,"verses":[109]}],"verseLabel":"هود: 109","question":"ما دلالة كثرة المؤكدات في قوله: ﴿وإنا لموفوهم نصيبهم غير منقوص﴾؟","answer":"تقطع الشك في وقوع الجزاء كاملًا، وتبين أن تأخيره لا يعني سقوطه أو نقصه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص748، تحت «بلاغة حشد المؤكدات في الآية»","url":""}]},{"id":"s11-249","number":249,"surah":11,"verses":[109],"references":[{"surah":11,"verses":[109]}],"verseLabel":"هود: 109","question":"ما وجه التهكم في تسمية عذابهم ﴿نصيبهم﴾؟","answer":"سُمّي العذاب نصيبًا كأنه عطاء ينتظرونه، تهكمًا بهم وإيذانًا بأن لهم منه حظًا مقررًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص749، تحت «أسلوب التهكم»","url":""}]},{"id":"s11-250","number":250,"surah":11,"verses":[109],"references":[{"surah":11,"verses":[109]}],"verseLabel":"هود: 109","question":"ما دلالة قوله عن نصيبهم: ﴿غير منقوص﴾؟","answer":"ينفي كل احتمال لنقص الجزاء، فيبلغ كل واحد ما استحقه كاملًا من غير بخس.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص750، تحت «علة التعبير بـ«منقوص»»","url":""}]},{"id":"s11-179","number":179,"surah":11,"verses":[110],"references":[{"surah":11,"verses":[110]}],"verseLabel":"هود: 110","question":"لماذا صرّح باسم موسى في قوله: ﴿ولقد آتينا موسى الكتاب فاختلف فيه﴾؟","answer":"استحضار قصته يسلي النبي ﷺ بأن الاختلاف في الوحي سنة قديمة لقيها رسول قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص756، تحت «وجه إظهار اسم موسى»","url":""}]},{"id":"s11-251","number":251,"surah":11,"verses":[110],"references":[{"surah":11,"verses":[110]}],"verseLabel":"هود: 110","question":"ما دلالة قوله: ﴿ولولا كلمة سبقت من ربك لقضي بينهم﴾؟","answer":"يبين أن تأخير الفصل ليس إقرارًا للباطل، بل تنفيذ لكلمة سبقت بإمهالهم إلى الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص757، تحت «فائدة التعبير بـ«لولا»»","url":""}]},{"id":"s11-180","number":180,"surah":11,"verses":[111],"references":[{"surah":11,"verses":[111]}],"verseLabel":"هود: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن كلًا لما ليوفينهم ربك أعمالهم﴾ بهذا التوكيد المتراكم؟","answer":"كثرة أدوات التوكيد تزيل الشك في شمول الجزاء لكل مختلف، وأن أعمالهم محفوظة لا يغيب منها شيء عن الخبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص766، تحت «بلاغة اجتماع المؤكدات»","url":""}]},{"id":"s11-181","number":181,"surah":11,"verses":[112],"references":[{"surah":11,"verses":[112]}],"verseLabel":"هود: 112","question":"ما دلالة تقييد الاستقامة بقوله تعالى: ﴿كما أمرت﴾، وما وجه شدة هذا التكليف؟","answer":"يطلب التعبير دوام الاستقامة مطابقةً لأمر الله في الاعتقاد والعمل والأخلاق، من غير إفراط ولا تفريط. ويشمل الأمر من تاب مع النبي، ثم يتبعه النهي عن الطغيان؛ فشدة التكليف في دقة الوفاء بهذا المنهج كله والثبات عليه مع ما يلقونه من أذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص777، تحت «بلاغة التشبيه بالكاف»","url":""}]},{"id":"s11-182","number":182,"surah":11,"verses":[112],"references":[{"surah":11,"verses":[112]}],"verseLabel":"هود: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تطغوا﴾ بعد الأمر بالاستقامة؟","answer":"الاستقامة وسط بين التقصير ومجاوزة الحد؛ فحتى الحماسة للحق لا تبرر تعدي ما أمر الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص780، تحت «إيثار لفظ الطغيان دون غيره»","url":""}]},{"id":"s11-183","number":183,"surah":11,"verses":[113],"references":[{"surah":11,"verses":[113]}],"verseLabel":"هود: 113","question":"ما دلالة النهي عن الركون إلى الذين ظلموا؟","answer":"الركون ميل وسكون إلى الظالمين، ومنه الرضا بظلمهم وتحسين طريقهم. والنهي عن هذا الميل يمنع ما يفضي إلى مشاركتهم؛ فإذا ورد الوعيد على الركون، كانت المشاركة في الظلم أشد دخولًا في التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص787، تحت «إيثار لفظ الركون»","url":""}]},{"id":"s11-184","number":184,"surah":11,"verses":[113],"references":[{"surah":11,"verses":[113]}],"verseLabel":"هود: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿فتمسكم النار﴾؟","answer":"المس يوحي بأن أدنى اتصال بالنار كاف في التحذير، وهو مناسب للنهي عن أدنى ميل إلى الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص790، تحت «إيثار لفظ المس وبلاغة المجاز فيه»","url":""}]},{"id":"s11-185","number":185,"surah":11,"verses":[114],"references":[{"surah":11,"verses":[114]}],"verseLabel":"هود: 114","question":"ما دلالة التعبير عن أوقات الصلاة بـ﴿طرفي النهار﴾؟","answer":"يجمع أول النهار وآخره ليحيط اليوم بمحطتي ذكر متقابلتين تعينان على الاستقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص799، تحت «فائدة التعبير بالطرف وتثنيته»","url":""}]},{"id":"s11-252","number":252,"surah":11,"verses":[114],"references":[{"surah":11,"verses":[114]}],"verseLabel":"هود: 114","question":"ما دلالة قوله: ﴿وزلفًا من الليل﴾؟","answer":"الزلف ساعات الليل القريبة، فاختير اللفظ لأوقات متقاربة تتكرر فيها الصلة بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص800، تحت «إيثار لفظ الزلف في السياق»","url":""}]},{"id":"s11-186","number":186,"surah":11,"verses":[114],"references":[{"surah":11,"verses":[114]}],"verseLabel":"هود: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الحسنات يذهبن السيئات﴾ بعد الأمر بالصلاة؟","answer":"جاءت الجملة تعليلًا للأمر بالصلاة وترغيبًا في الحسنات، والصلاة في مقدمتها. والتعبير بالإذهاب يصوّر أثر الطاعة في محو السيئة، كما يشمل تهيئة النفس لتركها؛ فتقاوم الحسنات الذنب وتعين على دوام الاستقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص802، تحت «سر التعبير بقوله «يذهبن السيئات»»","url":""}]},{"id":"s11-187","number":187,"surah":11,"verses":[115],"references":[{"surah":11,"verses":[115]}],"verseLabel":"هود: 115","question":"ما مناسبة الأمر بالصبر بعد الأمر بالاستقامة؟","answer":"لأن الثبات على الطاعة واجتناب الطغيان والركون يحتاج إلى صبر على المشقة والأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص11، تحت «مناسبة وقوع الأمر بالصبر عقب الاستقامة»","url":""}]},{"id":"s11-253","number":253,"surah":11,"verses":[115],"references":[{"surah":11,"verses":[115]}],"verseLabel":"هود: 115","question":"لماذا قال: ﴿لا يضيع أجر المحسنين﴾ بدل «أجركم»؟","answer":"ليبين أن الصبر والامتثال من الإحسان، وليعم الوعد كل من أحسن عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص13، تحت «فائدة العدول من المضمر إلى المظهر»","url":""}]},{"id":"s11-188","number":188,"surah":11,"verses":[116],"references":[{"surah":11,"verses":[116]}],"verseLabel":"هود: 116","question":"ما دلالة ﴿فلولا كان من القرون من قبلكم﴾؟","answer":"جاءت ﴿لولا﴾ للتحضيض بمعنى هلا، وخرجت إلى توبيخ الأمم على ترك مقاومة الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص17، تحت «دلالة لولا على التحضيض»","url":""}]},{"id":"s11-254","number":254,"surah":11,"verses":[116],"references":[{"surah":11,"verses":[116]}],"verseLabel":"هود: 116","question":"لماذا وصف الناهين عن الفساد بأنهم ﴿أولو بقية﴾؟","answer":"لأن البقية ما يُستبقى لنفاسته، فكانت كناية عن أصحاب الفضل والعقل والخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص19، تحت «إيثار لفظ البقية ودلالته»","url":""}]},{"id":"s11-189","number":189,"surah":11,"verses":[116],"references":[{"surah":11,"verses":[116]}],"verseLabel":"هود: 116","question":"ما دلالة استثناء ﴿قليلًا ممن أنجينا منهم﴾ بعد ذكر غياب الناهين عن الفساد؟","answer":"يستدرك الاستثناء ذكر الفئة القليلة التي نهت عن الفساد فأنجاها الله، فلا يوهم الكلام السابق خلو جميع القرون من المصلحين. وفي وصفهم بالقلة إبراز لندرتهم بالنسبة إلى أقوامهم، مع بيان أثر موقفهم في النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص20، تحت «توجيه الاستثناء»","url":""}]},{"id":"s11-190","number":190,"surah":11,"verses":[116],"references":[{"surah":11,"verses":[116]}],"verseLabel":"هود: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿واتبع الذين ظلموا ما أترفوا فيه﴾؟","answer":"يصور الاتباع انقيادهم لما تنعموا به من الشهوات حتى أعرضوا عن النهي عن الفساد. ولفظ الإتراف يدل على مجاوزة حد الاعتدال في التنعم على وجه يورث البطر والطغيان، ثم جاء وصفهم بالإجرام ليكشف عاقبة هذا المسلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص23، تحت «إيثار لفظ الإتراف دون غيره»","url":""}]},{"id":"s11-191","number":191,"surah":11,"verses":[117],"references":[{"surah":11,"verses":[117]}],"verseLabel":"هود: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان ربك ليهلك القرى بظلم وأهلها مصلحون﴾؟","answer":"ينفي أن يهلكهم ظلمًا منه وهم قائمون بالإصلاح؛ فالهلاك العام لا يأتي مع حياة الإصلاح، وإنما حين يستحكم فساد الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص26–29، تحت «نكتة النفي بـ«وما كان»؛ دلالة حرف الباء؛ دلالة الواو في «وأهلها مصلحون»؛ توجيه الحالية في جملة الفاصلة»","url":""}]},{"id":"s11-192","number":192,"surah":11,"verses":[118],"references":[{"surah":11,"verses":[118]}],"verseLabel":"هود: 118","question":"ما دلالة قوله تعالى: ﴿ولو شاء ربك لجعل الناس أمة واحدة﴾ في سياق اختلافهم؟","answer":"شاء أن يكون التكليف والابتلاء في مجال الاختيار، فتظهر الاستجابة والإعراض؛ ولو شاء قسرهم على طريق واحد لفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص35–38، 50، تحت «معنى لو في قوله «ولو شاء ربك»؛ نكتة التعبير بالجملة الشرطية في الآية؛ معنى أل في الناس؛ فائدة الخبر «ولذلك خلقهم»»","url":""}]},{"id":"s11-193","number":193,"surah":11,"verses":[118],"references":[{"surah":11,"verses":[118]}],"verseLabel":"هود: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يزالون مختلفين﴾؟","answer":"يصور استمرار الاختلاف ما دام الاختيار والهوى، لا أنه غاية محمودة في ذاته؛ ثم استثنى من رحمهم الله بالهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص40–45، تحت «فائدة الخبر «ولا يزالون مختلفين»؛ نكتة المضارع في «ولا يزالون»؛ نكتة حذف متعلق «مختلفين»؛ بلاغة القصر في الآية الكريمة»","url":""}]},{"id":"s11-194","number":194,"surah":11,"verses":[119],"references":[{"surah":11,"verses":[119]}],"verseLabel":"هود: 119","question":"ما دلالة الإشارة في قوله تعالى: ﴿ولذلك خلقهم﴾: أإلى الاختلاف تعود أم إلى الرحمة؟","answer":"ذكر المصدر ثلاثة أوجه لعود الإشارة: الاختلاف، أو الرحمة، أو مجموعهما. فعلى عودها إلى الاختلاف أو مجموعهما قد تكون اللام للعاقبة، أو يفسر الاختلاف بما جُبل عليه الناس من تفاوت واختيار؛ وعلى عودها إلى الرحمة تكون للتعليل. فلا يصح اختزال هذه الأوجه في الجزم بأن الكفر غاية محبوبة؛ والسياق يبين الاختيار وعاقبته ورحمة الله بالمهتدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص35، 46–50، تحت «معنى الواو في «ولذلك»؛ معنى اللام في قوله «ولذلك»؛ مرجع اسم الإشارة؛ دلالة التعبير باسم الإشارة «ذلك»؛ فائدة الخبر»","url":""}]},{"id":"s11-195","number":195,"surah":11,"verses":[119],"references":[{"surah":11,"verses":[119]}],"verseLabel":"هود: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿وتمت كلمة ربك لأملأن جهنم من الجنة والناس أجمعين﴾؟","answer":"يقرر نفاذ الحكم فيمن اختار طريق الشقاء من الصنفين؛ فلا يعطل اختلافهم وعد الله ولا يخرجهم عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص50–57، تحت «بلاغة العطف في قوله «وتمت كلمة ربك»؛ بلاغة المجاز؛ فائدة توالي المؤكدات في قوله «لأملأن»؛ معنى من في «من الجنة»؛ فائدة التوكيد بـ«أجمعين»»","url":""}]},{"id":"s11-196","number":196,"surah":11,"verses":[120],"references":[{"surah":11,"verses":[120]}],"verseLabel":"هود: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿وكلا نقص عليك من أنباء الرسل ما نثبت به فؤادك﴾؟","answer":"القصص لم تسق للاستمتاع التاريخي، بل كل خبر منها يمد القلب بدليل ثبات جديد أمام تكرر التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص66–67، 71–73، تحت «نكتة تقديم المفعول «كلا»؛ معنى ما في «ما نثبت» وإعرابها؛ دلالة التعبير بالمضارع ونون العظمة في «نثبت»؛ بلاغة الاستعارة»","url":""}]},{"id":"s11-197","number":197,"surah":11,"verses":[120],"references":[{"surah":11,"verses":[120]}],"verseLabel":"هود: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاءك في هذه الحق وموعظة وذكرى للمؤمنين﴾؟","answer":"خص هذه السورة بما جمعته من حقائق القصص المطمئنة، وموعظة تزجر، وذكرى تجدد ما يعرفه المؤمن؛ فتنوع أثر الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص74–80، تحت «غرض العطف في قوله «وجاءك»؛ سر التخصيص بالحق في الآية؛ دلالة التعبير بـ«موعظة»؛ فائدة تقديم الموعظة على الذكرى»","url":""}]},{"id":"s11-198","number":198,"surah":11,"verses":[121],"references":[{"surah":11,"verses":[121]}],"verseLabel":"هود: 121","question":"ما سرّ توجيه الخطاب إلى المكذبين بقوله تعالى: ﴿اعملوا على مكانتكم إنا عاملون﴾؟","answer":"أمر تهديد لا إباحة: استمروا على طريقكم وسنستمر على الحق، وستكشف النهاية قيمة كل عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص87–91، تحت «دلالة الأمر في قوله «اعملوا»؛ سر اختيار مادة العمل؛ نكتة التعدية في قوله «على مكانتكم»؛ نكتة فصل قوله تعالى «إنا عاملون»»","url":""}]},{"id":"s11-199","number":199,"surah":11,"verses":[122],"references":[{"surah":11,"verses":[122]}],"verseLabel":"هود: 122","question":"ما دلالة المقابلة في قوله تعالى: ﴿وانتظروا إنا منتظرون﴾؟","answer":"قابل انتظارهم سقوط الدعوة بانتظار المؤمنين حكم الله؛ والتكرار يصور المواجهة ويثبت أن العاقبة ستفصل بين الانتظارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص95، تحت «بلاغة المقابلة في الآية»","url":""}]},{"id":"s11-200","number":200,"surah":11,"verses":[123],"references":[{"surah":11,"verses":[123]}],"verseLabel":"هود: 123","question":"ما دلالة تقديم ﴿لله﴾ في قوله: ﴿ولله غيب السماوات والأرض﴾؟","answer":"يفيد اختصاص الله بعلم الغيب كله، فلا يملك أحد سر المستقبل استقلالًا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص100، تحت «نكتة التقديم في «ولله غيب»»","url":""}]},{"id":"s11-255","number":255,"surah":11,"verses":[123],"references":[{"surah":11,"verses":[123]}],"verseLabel":"هود: 123","question":"ما دلالة قوله: ﴿وإليه يرجع الأمر كله﴾؟","answer":"يرد التدبير والنتائج جميعًا إلى الله وحده، فلا يخرج شيء عن حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص106، تحت «فائدة توكيد الأمر بـ«كله»»","url":""}]},{"id":"s11-201","number":201,"surah":11,"verses":[123],"references":[{"surah":11,"verses":[123]}],"verseLabel":"هود: 123","question":"ما دلالة الجمع بين العبادة والتوكل في ختام السورة: ﴿فاعبده وتوكل عليه﴾؟","answer":"يجمع الختام امتثال أمر الله مع الاعتماد عليه؛ فالعبادة عمل وطاعة، والتوكل ثقة بالله وتفويض الأمر إليه مع الأخذ بالأسباب. وتقديم العبادة يؤكد أن التوكل يصحب العمل، وباجتماعهما يثبت الرسول والمؤمنون على دعوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص99، 107–109، تحت «دلالة الأمر في قوله «فاعبده وتوكل»؛ نكتة عطف التوكل في الآية؛ نكتة تقديم الأمر بالعبادة في الآية»","url":""}]},{"id":"s11-202","number":202,"surah":11,"verses":[123],"references":[{"surah":11,"verses":[123]}],"verseLabel":"هود: 123","question":"ما دلالة ختم سورة هود بقوله تعالى: ﴿وما ربك بغافل عما تعملون﴾؟","answer":"تختم بالرقابة الشاملة: لا يضيع عمل الداعية ولا يغيب ظلم المكذب، وفيها وعد ووعيد يلخصان مسار السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص114، تحت «بلاغة التذييل في آخر الآية»","url":""}]},{"id":"s12-1","number":1,"surah":12,"verses":[1],"references":[{"surah":12,"verses":[1]}],"verseLabel":"يوسف: 1","question":"ما دلالة افتتاح سورة يوسف بالحروف ﴿الر﴾ ثم ذكر الكتاب المبين؟","answer":"من الأوجه المذكورة في تفسير الحروف المقطعة أنها تنبّه إلى إعجاز القرآن: فهو مؤلف من الحروف التي يعرفها العرب، ومع ذلك يعجزون عن الإتيان بمثله. وعلى هذا الوجه يناسب أن يعقبها ذكر آيات الكتاب المبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص129–130، تحت «المعنى الإجمالي»","url":""}]},{"id":"s12-2","number":2,"surah":12,"verses":[1],"references":[{"surah":12,"verses":[1]}],"verseLabel":"يوسف: 1","question":"ما سرّ وصف الكتاب في مطلع سورة يوسف بـ﴿المبين﴾؟","answer":"المبين هو الواضح في نفسه والمبيّن للحق. ويلائم هذا الوصف سورة يوسف خاصة؛ إذ تكشف تفاصيل قصة لم يكن العرب يعرفونها بهذا البيان قبل نزول القرآن، وتظهر فيها دلائل الوحي والعبر في أبلغ أسلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص133، تحت «دلالة التعبير بـ﴿المبين﴾ في الآية»","url":""}]},{"id":"s12-3","number":3,"surah":12,"verses":[2],"references":[{"surah":12,"verses":[2]}],"verseLabel":"يوسف: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿إنا أنزلناه قرآنًا عربيًا﴾، دون أن يقال «كتابًا عربيًا»؟","answer":"سبق وصفه بالكتاب، فجاء ﴿قرآنًا﴾ ليضيف أنه كتاب مقروء متلوّ، فيجتمع حفظه في السطور وحفظه في الصدور. ووصفه بالعربية يبين أنه نزل بلسان المخاطبين الأولين، ليعقلوا معانيه ويظهر لهم بيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص143، تحت «فائدة العدول في ﴿قرآنًا﴾»","url":""}]},{"id":"s12-4","number":4,"surah":12,"verses":[2],"references":[{"surah":12,"verses":[2]}],"verseLabel":"يوسف: 2","question":"ما دلالة تعليل إنزال القرآن عربيًا بقوله: ﴿لعلكم تعقلون﴾؟","answer":"لأن وضوح اللسان يزيل عذر عدم الفهم، لكن الغاية ليست سماع الألفاظ وحدها بل عقل المعاني والاعتبار بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص145، تحت «غرض التعبير بـ﴿تعقلون﴾»","url":""}]},{"id":"s12-5","number":5,"surah":12,"verses":[3],"references":[{"surah":12,"verses":[3]}],"verseLabel":"يوسف: 3","question":"ما دلالة بدء قوله تعالى: ﴿نحن نقص عليك﴾ بضمير العظمة؟","answer":"إسناد القصّ إلى الله بضمير العظمة يقرر أن الخبر وحي صادق، ويفخم شأن القصة التي يتولى الله بيانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص152، تحت «نكتة بدء الآية بضمير العظمة»","url":""}]},{"id":"s12-209","number":209,"surah":12,"verses":[3],"references":[{"surah":12,"verses":[3]}],"verseLabel":"يوسف: 3","question":"لماذا وُصف القصص في قوله تعالى: ﴿أحسن القصص﴾ بأنه أحسن؟","answer":"لأنه أحسن الاقتصاص والبيان، وأحسن الأخبار المقصوصة بما اشتملت عليه من صدق وحكم وعبر وجمال أداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص156، تحت «دلالة اسم التفضيل ﴿أحسن القصص﴾»","url":""}]},{"id":"s12-6","number":6,"surah":12,"verses":[3],"references":[{"surah":12,"verses":[3]}],"verseLabel":"يوسف: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿بما أوحينا إليك هذا القرآن﴾؟","answer":"يقرر أن معرفة النبي بهذه التفاصيل لم تأت من تعلم بشري، بل من الوحي؛ فالقصة نفسها برهان على النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص158، تحت «معنى الباء في قوله: ﴿بما أوحينا إليك﴾»","url":""}]},{"id":"s12-7","number":7,"surah":12,"verses":[3],"references":[{"surah":12,"verses":[3]}],"verseLabel":"يوسف: 3","question":"ما دلالة وصف النبي قبل الوحي بأنه ﴿لمن الغافلين﴾ عن هذا القصص؟","answer":"الغفلة هنا عدم العلم لا الذم؛ وذكرها يقوي الدليل، إذ جاءه خبر لم يكن يعرفه بهذه الصورة المحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص166، تحت «نكتة التعبير بـ﴿الغافلين﴾»","url":""}]},{"id":"s12-8","number":8,"surah":12,"verses":[4],"references":[{"surah":12,"verses":[4]}],"verseLabel":"يوسف: 4","question":"ما سرّ تكرار فعل الرؤية في قول يوسف: ﴿إني رأيت أحد عشر كوكبًا والشمس والقمر رأيتهم لي ساجدين﴾؟","answer":"قيل: أعاد الفعل لتوكيد الرؤية بعد طول الفصل بينه وبين حال السجود. وقيل: ﴿رأيتهم لي ساجدين﴾ جواب لسؤال مقدّر: كيف رأيتها؟ فتنتقل العبارة من ذكر المرئيات إلى بيان هيئتها العجيبة في الرؤيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص179–181، تحت «الموقع البياني لـ﴿رأيتهم﴾»","url":""}]},{"id":"s12-9","number":9,"surah":12,"verses":[4],"references":[{"surah":12,"verses":[4]}],"verseLabel":"يوسف: 4","question":"ما سرّ استعمال ضمير العقلاء في ﴿رأيتهم﴾ للكواكب والشمس والقمر؟","answer":"لأنها ظهرت في الرؤيا ساجدة، والسجود فعل العقلاء؛ فشخّصها التعبير وجعلها مشهدًا حيًا ينبئ بأشخاص يسجدون.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص181–182، تحت «نكتة ضمير الجمع في الآية الكريمة»","url":""}]},{"id":"s12-10","number":10,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"ما دلالة بدء يعقوب نصيحته بقوله: ﴿يا بني﴾؟","answer":"تصغير التحبيب يهيئ يوسف لقبول النصح ويكشف حنان الأب، خصوصًا أن الأمر يتضمن كتمان رؤيا عظيمة عن إخوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص188، تحت «فائدة تصغير (بني)، وإضافته في السياق»","url":""}]},{"id":"s12-11","number":11,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"ما دلالة نهي يعقوب يوسف عن قصّ الرؤيا على إخوته؟","answer":"هو نهي نصح وإرشاد؛ فقد أدرك يعقوب ما تبشر به الرؤيا من رفعة يوسف، وخشي أن يحمل الحسد إخوته على الكيد له. فإخفاؤها حماية له من الشر الذي قد يثيره ظهور هذه النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص189–190، تحت «دلالة النهي في: ﴿لا تقصص رؤياك﴾»","url":""}]},{"id":"s12-12","number":12,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"لماذا عُدّي فعل الكيد باللام في قوله تعالى: ﴿فيكيدوا لك﴾؟","answer":"تفيد اللام أن الكيد موجّه إلى يوسف ومخصوص به، وقيل ضُمّن الفعل معنى الاحتيال له.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص196، تحت «فائدة تعدية فعل الكيد باللام»","url":""}]},{"id":"s12-210","number":210,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"ما فائدة المفعول المطلق ﴿كيدًا﴾ في قوله تعالى: ﴿فيكيدوا لك كيدًا﴾؟","answer":"يؤكد المفعول المطلق وقوع الكيد وقوته، فيشدد التحذير من تدبير الإخوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص197، تحت «فائدة التعبير بالمفعول المطلق ﴿كيدًا﴾»","url":""}]},{"id":"s12-211","number":211,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"ما دلالة تنكير ﴿كيدًا﴾ في قوله تعالى: ﴿فيكيدوا لك كيدًا﴾؟","answer":"يفيد التنكير تهويل الكيد الذي قد يدبرونه ليوسف وإبهام صورته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص197، تحت «نكتة تنكير ﴿كيدًا﴾»","url":""}]},{"id":"s12-13","number":13,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"ما دلالة تعليل التحذير من كيد الإخوة بقوله: ﴿إن الشيطان للإنسان عدو مبين﴾؟","answer":"لم يقطع رابطة الأخوة باتهامهم وحدهم، بل كشف المحرك الذي يوقد الحسد؛ فالشيطان عدو ظاهر يسعى لإفساد الأسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص198، تحت «نكتة الفصل في: ﴿إن الشيطان﴾»","url":""}]},{"id":"s12-14","number":14,"surah":12,"verses":[6],"references":[{"surah":12,"verses":[6]}],"verseLabel":"يوسف: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك يجتبيك ربك﴾ بعد الرؤيا مباشرة؟","answer":"يربط التشبيه بين ما أكرمه الله به من الرؤيا وما سيختاره له من النبوة والتعليم وإتمام النعمة. فجاءت البشارة عقب التحذير من الكيد تطمينًا ليوسف وإعدادًا له لما سيلاقيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص205، تحت «بلاغة التشبيه في ﴿وكذلك﴾»","url":""}]},{"id":"s12-15","number":15,"surah":12,"verses":[6],"references":[{"surah":12,"verses":[6]}],"verseLabel":"يوسف: 6","question":"ما دلالة لفظ ﴿تأويل﴾ في قوله تعالى: ﴿تأويل الأحاديث﴾؟","answer":"التأويل ردّ الخبر إلى حقيقته وما يؤول إليه؛ أي كشف مآل الرؤيا وما ترمز إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص208، تحت «إيثار لفظ ﴿تأويل﴾ في السياق»","url":""}]},{"id":"s12-212","number":212,"surah":12,"verses":[6],"references":[{"surah":12,"verses":[6]}],"verseLabel":"يوسف: 6","question":"ما المراد بـ﴿الأحاديث﴾ في قوله تعالى: ﴿تأويل الأحاديث﴾؟","answer":"من تفسيرها الرؤى، وقيل تشمل معاني كتب الله وسنن الأنبياء وما فيها من دقائق وحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص209، تحت «معنى ﴿الأحاديث﴾، وسر استعمالها في السياق»","url":""}]},{"id":"s12-16","number":16,"surah":12,"verses":[6],"references":[{"surah":12,"verses":[6]}],"verseLabel":"يوسف: 6","question":"ما دلالة الجمع بين يوسف وآل يعقوب في إتمام النعمة؟","answer":"لم تقف بركة النعمة عند يوسف؛ بل شملت آل يعقوب بما حصل لهم بسببه من العز والتمكين والسرور. وذكره أولًا ثم عطف آله يبرز خصوص منزلته وامتداد أثر نعمته إلى أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص211، تحت «فائدة التعبير بـ﴿عليك وعلى آل يعقوب﴾»","url":""}]},{"id":"s12-17","number":17,"surah":12,"verses":[7],"references":[{"surah":12,"verses":[7]}],"verseLabel":"يوسف: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد كان في يوسف وإخوته آيات للسائلين﴾ بالجمع؟","answer":"الجمع يدل على كثرة الدلائل وتنوعها في القصة؛ ففيها عاقبة الصبر، وآثار الحسد، ودلائل صدق الوحي. وتنكير ﴿آيات﴾ يفيد تعظيمها، فكأن كل مرحلة من القصة باب للعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص226، تحت «فائدة جمع ﴿آيات﴾ وتنكيرها في الآية الكريمة»","url":""}]},{"id":"s12-18","number":18,"surah":12,"verses":[7],"references":[{"surah":12,"verses":[7]}],"verseLabel":"يوسف: 7","question":"ما سرّ تخصيص ﴿السائلين﴾ بذكر الآيات في قصة يوسف؟","answer":"فيه حثّ على طلب خبر القصة والسؤال للتعلم والاعتبار؛ فالسائل المعتني أهيأ لفهم دلائلها ممن يعرض عنها. وقيل يوافق اللفظ سؤالًا كان سببًا لنزولها، مع أن عبرها لا تنحصر في أولئك السائلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص227–228، تحت «سر تقييد ﴿آيات﴾ بتعليقها بلفظ السائلين»","url":""}]},{"id":"s12-19","number":19,"surah":12,"verses":[8],"references":[{"surah":12,"verses":[8]}],"verseLabel":"يوسف: 8","question":"ما سرّ التعبير في قول الإخوة: ﴿ليوسف وأخوه أحب إلى أبينا منا﴾ ولم يسموا بنيامين؟","answer":"أضافوا الأخ إلى يوسف لأنهما شقيقان، فجمعوهما في جهة واحدة بإزاء بقية الإخوة، مع أنهم جميعًا إخوة. وفي قولهم ﴿وأخوه﴾ تظهر الجفوة التي أحدثها الحسد في نظرتهم إلى الأسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص230–231، تحت «علة عطف قوله: ﴿وأخوه﴾ في السياق»","url":""}]},{"id":"s12-20","number":20,"surah":12,"verses":[8],"references":[{"surah":12,"verses":[8]}],"verseLabel":"يوسف: 8","question":"ما دلالة احتجاج الإخوة بقولهم: ﴿ونحن عصبة﴾؟","answer":"جعلوا القوة والعدد معيار استحقاق المحبة؛ رأوا أنفسهم أنفع للأب، وغفلوا أن المحبة ليست صفقة تقاس بالكثرة والمنفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص233، تحت «سر التعبير بلفظ ﴿عصبة﴾»","url":""}]},{"id":"s12-21","number":21,"surah":12,"verses":[8],"references":[{"surah":12,"verses":[8]}],"verseLabel":"يوسف: 8","question":"ما وجه قولهم عن أبيهم: ﴿إن أبانا لفي ضلال مبين﴾؟","answer":"أرادوا خطأه في تقدير المحبة لا ضلال الدين، لكن العبارة تكشف كيف يدفع الحسد صاحبه إلى تضخيم الحكم على أقرب الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص235، تحت «معنى ﴿ضلال﴾ وسر وصفه بالإبانة»","url":""}]},{"id":"s12-22","number":22,"surah":12,"verses":[9],"references":[{"surah":12,"verses":[9]}],"verseLabel":"يوسف: 9","question":"ما دلالة التخيير بـ﴿أو﴾ في قولهم: ﴿اقتلوا يوسف أو اطرحوه أرضًا﴾؟","answer":"عرضوا طريقين لتحقيق غرض واحد هو إبعاد يوسف عن أبيه: القتل المباشر أو الطرح في مكان بعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص241، تحت «دلالة التخيير في ﴿أو﴾»","url":""}]},{"id":"s12-213","number":213,"surah":12,"verses":[9],"references":[{"surah":12,"verses":[9]}],"verseLabel":"يوسف: 9","question":"ما دلالة تنكير ﴿أرضًا﴾ في قولهم: ﴿أو اطرحوه أرضًا﴾؟","answer":"يلائم التنكير إرادتهم مكانًا مجهولًا بعيدًا لا يُعرف فيه أثر يوسف ولا يهتدي منه إلى أبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص242، تحت «تنكير ﴿أرضًا﴾»","url":""}]},{"id":"s12-23","number":23,"surah":12,"verses":[9],"references":[{"surah":12,"verses":[9]}],"verseLabel":"يوسف: 9","question":"ما وجه قولهم: ﴿يخل لكم وجه أبيكم﴾؟","answer":"صوّروا وجه الأب واهتمامه كمساحة مشغولة بيوسف، وتوهموا أن إزالته ستفرغها لهم؛ وهي صورة دقيقة لاستحواذ الغيرة على رؤيتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص244، تحت «سر إسناد الخلو إلى الوجه بين الاستعارة والمجاز»","url":""}]},{"id":"s12-24","number":24,"surah":12,"verses":[9],"references":[{"surah":12,"verses":[9]}],"verseLabel":"يوسف: 9","question":"ما دلالة قول الإخوة: ﴿وتكونوا من بعده قومًا صالحين﴾ وهم يدبرون إبعاد يوسف؟","answer":"على تفسير الصلاح بصلاح الدين، سوّلت لهم أنفسهم أن يرتكبوا الجريمة ثم يتوبوا بعدها. وقيل أرادوا صلاح حالهم مع أبيهم وانتظام أمرهم بعد انفرادهم بمحبته؛ وفي الوجهين يظهر توهمهم أن إبعاد يوسف طريق إلى إصلاح شأنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص248، تحت «نكتة حذف متعلق ﴿صالحين﴾»","url":""}]},{"id":"s12-25","number":25,"surah":12,"verses":[10],"references":[{"surah":12,"verses":[10]}],"verseLabel":"يوسف: 10","question":"ما سرّ التصريح باسم يوسف في ﴿لا تقتلوا يوسف﴾ مع إمكان إضماره؟","answer":"ذكر الاسم يستحضر شخص يوسف في نفوس إخوته، ويستبقي ما في القلوب من رحمة به؛ فجاء مع النهي عن قتله لاستجلاب شفقتهم وإقناعهم بالعدول عن القتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص256، تحت «وضع المظهر ﴿يوسف﴾ موضع المضمر في الآية»","url":""}]},{"id":"s12-26","number":26,"surah":12,"verses":[10],"references":[{"surah":12,"verses":[10]}],"verseLabel":"يوسف: 10","question":"ما دلالة ﴿غيابت الجب﴾؟","answer":"الغيابة هي ما يستر عن العين، وفي الجب موضع مظلم لا يظهر فيه من أُلقي فيه. فاختيارها يبرز غرض الإخفاء، لا مجرد الوصول إلى أسفل البئر؛ إذ قد يكون القعر عميقًا مع بقاء ما فيه مرئيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص256، تحت «إيثار كلمتي ﴿غيابت الجب﴾»","url":""}]}]);
